// 文件: 前端/src/降级/公共降级.rs
// 职责: 高层表示 → 底层表示 降级转换的公共函数，供所有后端共用

use crate::语义::{
    高层表示节点::{高层表示表达式, 高层表示语句, 高层表示运算符, 字面值 as 高层表示字面值},
    类型信息::{类型信息, 基本类型},
};
use crate::底层表示::{
    模块结构::{异常目标, 底层表示函数, 基本块, 常量值},
    指令集::{三地址码, 操作码, 操作数, 终止指令},
    类型定义::底层表示类型,
};
use std::collections::{HashMap, HashSet};
use std::cell::RefCell;
use crate::语法分析::参数传递方式;
use crate::降级::类型转换::{解析函数索引, 转换类型};

// 清理诊断字段
use crate::降级::函数转换::转换函数;
use crate::语义::类型推断::从表达式推断;

// 取消函数/方法重载（规范 §2.4）：函数/方法名必须唯一。
// 发射阶段统一从 函数签名详情 取 (形参数量, 默认值列表, 传递方式, 形参类型)，
// 无需重载表。（F12 方法重载记录/解析全局函数重载 已删除。）

// 当前函数内的「传引用」形参局部索引集合（读取时走 间接加载）。
// 降级为单线程编译路径，用 thread_local 携带 per-function 信息，避免改动 38+ 处调用签名。
thread_local! {
    pub static 当前函数引用局部: RefCell<HashSet<usize>> = RefCell::new(HashSet::new());
    /// 当前函数内「传引用」形参名 → 其局部索引（赋值走 间接存储）。
    pub static 当前函数引用名映射: RefCell<HashMap<String, usize>> = RefCell::new(HashMap::new());
    /// 🆕 2026-09-16 引用计数闭环（−1 侧）：当前函数「待释放的栈槽局部」(变量名, 局部索引)。
    /// 在 `返回语句`（无「始终」链待办时）与**函数末尾**发射 `操作码::释放引用`（−1），
    /// 与 base 的 `堆释放`（归零即回收 + 级联子句柄）形成闭环 ⇒ 内存真正可回收。
    /// ⚠ 只登记「确定无别名」的栈槽：值语义复合类型局部（赋值/传参已深拷贝 ⇒ 独立对象，
    ///    每个声明点独占一个局部槽、槽不复用 ⇒ 在函数出口释放是安全的）。
    ///    接口型不登记（引用语义共享同一实例 ⇒ 保守处置、宁可泄漏不误回收）；
    ///    `传引用` 形参与 `自身` 属借用，同样不登记。
    pub static 当前函数待释放局部: RefCell<Vec<(String, usize)>> = RefCell::new(Vec::new());
    /// 已被 `返回 <名称>` 整体移出的局部名（move ⇒ 该槽不得释放：所有权已交给调用方）。
    pub static 当前函数已移出名称: RefCell<HashSet<String>> = RefCell::new(HashSet::new());

/// 🆕 2026-10-13（**#13 收窄版**）：当前被转换函数的**声明返回类型**（逐函数在 `函数转换.rs` 重置处写入）。
/// 用途：`返回 <映射读值>` 的**去重**只允许在"本函数返回文本"时生效 ——
/// 文本可安全共享（方案明文：值语义**不可变**堆对象，共享 +1/−1 语义不可区分）；
/// 而复合类型（结构体/数组/映射/接口）可能被**按身份借用**（读取处不会 +1）⇒ 去重会**误回收**（红灯反例 `272`）。
pub static 当前函数返回类型: RefCell<Option<类型信息>> = RefCell::new(None);

/// 🆕 2026-10-13（**#13 收窄版**）：当前**条件表达式**内新建的「文本返回调用结果槽」索引集合。
/// 释放时机：条件求值结束（条件是**语句**、非表达式 ⇒ 其中不可能存入具名槽 ⇒ 结构上安全）。
pub static 当前条件可释放临时: RefCell<Vec<usize>> = RefCell::new(Vec::new());

/// 🆕 2026-10-13（**#15 / E 形态**）：当前函数内「**值直接来自映射读**（`.获取(键)` / `地[键]`）」的局部名集合。
/// 用途：这些槽里的文本已由**读取处 +1**（缺陷C1）保护 ⇒ `返回 <裸变量>` 时**不再重复 +1**
/// （与 #13 的"投影返回去重"同构、同边界）。
/// 维护：① 变量声明处按 RHS 是否为映射读 插入/移除；② **赋值语句**处一律移除（重赋值 ⇒ 来源失效，保守优先）。
pub static 当前函数映射读局部: RefCell<HashSet<String>> = RefCell::new(HashSet::new());

    /// 🔁 2026-09-24（**`返回 <值传递形参>` 过度释放修复**）：当前函数的**值传递形参名**集合。
    ///
    /// **为什么需要**（实测取证，见记忆 §18.113）：值传递形参在 callee 内是**自有副本**
    ///   （值语义隔离已实测 ✓ `F10`：callee 改字段不影响调用方）⇒ `返回 <裸名>` 按 move
    ///   把该副本交给调用方（记 `已移出`）；
    ///   但实测（`F9` 最小复现 / `F8` 四变体 / `F11` 表达式语句形态；**双模一致** + 账本）
    ///   该对象在**调用返回前后即被释放** ⇒ 调用方拿到**悬垂句柄** ⇒ `无效句柄`
    ///   ⇒ 表现为 `类型转换错误: 空值不能参与类型转换` ✗
    ///   （`验证_复杂调用.智` 的 `包装(任意<值> 数值) 任意<值>: 返回 数值` 正是此形态 ⇒ 双模 FAIL ✓）
    /// **正解（依铁律「宁可泄漏，绝不误回收」）**：在 `返回 <值传递形参>` 处**为调用方 +1**
    ///   —— 与"投影返回 ⇒ 被调方 +1 计数一份"**同构** ✓（帧内那份即使被释放，调用方仍存活 ✓）
    /// **只收「值传递」形参**：`传引用` 形参是**借用别名**（本不属于本帧，且实测该形态**本已正常** ✓）
    ///   ⇒ 一律不收（避免引入幽灵计数）✓
    pub static 当前函数值传递形参名: RefCell<HashSet<String>> = RefCell::new(HashSet::new());

    /// 🆕 阶段 6b（2026-09-23）**函数级「槽元数据表」**（**只读记录，不参与任何判定**）。
    ///
    /// 为什么加它（对应方案 §五 的收敛目标，取**可行且零风险**的那一半）：
    ///   现状：槽信息被拆在三处 —— ① 降级的 `变量映射`（名字→槽，快照/恢复实现块作用域）；
    ///     ② 语义层符号表（名字→符号/层级）；③ 内存层 `拥有型槽索引`（由 `当前函数待释放局部` 增量维护）。
    ///   后果：**降级后名字即消失**（LIR 只剩槽下标）⇒ 排障只能靠 dump 下标；且清单类缺陷
    ///     （曾出"清单全空 ⇒ 系统性泄漏""幽灵计数""过度释放"）只能靠逐例验证发现。
    ///   ⚠ **为什么不让本表去"派生"是否拥有**：所有权需要**数据流推理**（现由增量逻辑逼近，
    ///     含"返回移出/接口闸门/含接口成员排除"等语义）⇒ 强行派生会引入**新风险**，违反"治本不冒险"。
    ///   ⇒ 本表定位 = **与清单互为校验的只读真相 + 可转储**：把"清单里到底是什么"变成可读，
    ///     并把若干**结构不变量**（越界/重复）从静默变成红灯。
    pub static 当前函数槽元数据: RefCell<Vec<槽元数据>> = RefCell::new(Vec::new());

    /// 🔁 2026-09-23（**soak 缺陷修复的安全收窄**）：**"返回即转移所有权"的用户函数名集**。
    ///
    /// 语义：该函数的**每一个** `返回 <表达式>` 都返回**它自己声明的局部**（非形参 / 非 `自身` /
    ///   非模块级全局）⇒ 返回值确定由被调方**自有并转移**给调用方 ⇒ **调用点持有一份自有引用**
    ///   ⇒ 深拷贝入目标槽后，可以对"调用结果临时"安全 −1 ✓
    ///
    /// ⚠ 为什么必须有它（实测血泪）：若对所有用户函数调用结果一律 −1，会打中**借用返回**：
    ///   `引用返回数组(传引用 数组<整数> 列) 数组<整数>: … 返回 列` ⇒ 返回的是**调用方自己的对象**
    ///   ⇒ 调用点 −1 ⇒ **过度释放** ⇒ `无效句柄`（用例 `28值引用传递与接口细节全面测试` 双模 FAIL ✗）
    /// ⚠ 填充点：`公共降级::降级转换`（**所有函数体降级之前**预扫描 HIR）✓；**fail-closed**：
    ///   遇到未识别的语句变体 ⇒ 该函数判为**非转移**（宁可保守泄漏，绝不误释放）✓
    pub static 返回即转移函数集: RefCell<HashSet<String>> = RefCell::new(HashSet::new());
    /// 🆕 引用计数**启用闸门①**：本函数是否含嵌套控制流（如果/循环/代码块）。
    /// 为真 ⇒ 本函数整体不发射释放（分支/循环内声明的槽在某些返回路径上未赋值 ⇒ 释放会碰到残留句柄）。
    pub static 当前函数含嵌套控制流: RefCell<bool> = RefCell::new(false);
    /// 🆕 引用计数**启用闸门②**：本函数是否含接口用法（接口声明/接口赋值 = 引用语义共享实例）。
    /// 为真 ⇒ 本函数整体不发射释放（否则会误回收仍被接口持有的对象）。
    pub static 当前函数含接口用法: RefCell<bool> = RefCell::new(false);
    /// ⚡双模式⚡ **结构体字段类型表**（结构体名 → [(字段名, 类型信息)]），由 `公共降级::降级转换` 从 HIR 填入。
    /// 用途：**值语义深拷贝必须"按成员身份"** —— 接口 / `任意<接口>` 成员是**引用语义（标签）**，
    ///   深拷贝时必须**只复制标签、绝不克隆被指对象**（规范 §4772/§4834：标签贴在同一个实例上）。
    /// 背景（2026-09-21 实测缺陷）：`base::堆_深拷贝` 是**通用递归克隆**，**看不见成员身份**
    ///   ⇒ `乙 = 甲`（甲含 `可移动 设备` 字段）会把接口指向的实例一起克隆
    ///   ⇒ 随后 `乙.设备.移动(70)` 改的是克隆体，`甲.设备` 仍为 10（应为 70）；解释/编译**双模一致地错**。
    pub static 结构体字段类型表: RefCell<HashMap<String, Vec<(String, 类型信息)>>> =
        RefCell::new(HashMap::new());

    /// ⚠ P2「块级作用域栈（映射快照 + 恢复）」**已两次实施、两次撤销，勿再直接复活**：
    /// - 需求真实：内层块**显式声明**（`数组 乙 = [7]`）遮蔽外层后，**块外应恢复外层绑定**
    ///   （语义层已正确：`分析代码块` 进出作用域 + `声明符号` 只查最内层 ⇒ 允许同名遮蔽）。
    /// - 已确证**方案本身有效**：加栈后 `探针_遮蔽语义.智` 的 D 点由 1 → **3**（块外恢复 ✓）。
    /// - 但**两次均引入回归**：`211 内存回收冒烟.智` 的 `计数 > 2000` 判假 ⇒ 精准门禁 13 → **14**
    ///   （第二次已补"每函数 `clear()`"，仍复现 ⇒ **根因未查明**，不是跨函数污染）。
    /// - ⇒ 结论：**必须先用最小探针定位该回归**（怀疑与循环变量的槽/绑定在块退出后不可见有关），
    ///   再连同"每函数重置"一次性落地；当前按「零回归优先」保持撤销状态。

    /// ⚠ P2 块级作用域栈（2026-09-17 曾实现后**撤销**，勿直接复活）：
    /// 需求真实存在（规范 §2.3.5：局部变量「到包含它的代码块结束时失效」、内层可遮蔽外层），
    /// 但在**降级层**单独加"进入/退出块作用域"包裹会破坏循环变量等绑定的可见性
    /// （实测：`211 内存回收冒烟.智` 的 `计数 > 2000` 变为假 ⇒ 精准门禁新增 1 例回归）。
    /// ⇒ 正确做法是**先在语义分析层实现块级符号表**（"声明 vs 赋值"的判定依赖"当前作用域"，
    ///    见规范 §1404），再由语义层给出块作用域结论、降级层据此同步映射，二者必须同批落地。

    /// 🆕 方案B S1：当前「异常目标」上下文栈。异常控制 转换进入 危险/异常/始终 区时压栈，
    /// 区段结束弹栈；新建基本块时读取栈顶标注其 异常目标（见 helper 压/弹/取）。栈空 = 无。
    pub static 当前异常目标栈: RefCell<Vec<异常目标>> = RefCell::new(Vec::new());
    /// 🆕 FFI: 当前模块的外部函数名称集，用于判断函数调用应走 调用 还是 外部调用。
    pub static 当前外部函数集: RefCell<HashSet<String>> = RefCell::new(HashSet::new());
    /// 🆕 2026-08-29 FFI 数组：当前模块外部函数的「数组形参」索引集（函数名 → 数组形参索引集合）。
    /// 供 调用实参降级 判定 FFI 数组实参**不深拷贝**——数组为 In/Out 缓冲区语义（`数组<元素> 名`），
    /// 实参传共享句柄，宿主 处理外部调用 回写时原地修改即可反映到调用方变量；
    /// 普通函数数组实参仍按智语言值语义深拷贝（互不影响）。
    pub static 当前外部函数数组形参: RefCell<HashMap<String, HashSet<usize>>> = RefCell::new(HashMap::new());
    /// ⚡双模式⚡ A1 闭包索引同源：本模块用户函数数 K，供闭包注册时计算固定索引 `200 + K + 闭包序`，
    /// 与编译器 函数名映射(200+i, i=函数列表位置) 严格对齐。外部函数不在 函数列表，故闭包紧随用户函数
    /// 占据 [200+K, 200+K+C)，不混入外部函数偏移 E（此前 `200+len` 含 E 导致存在 FFI 时索引错位）。
    /// 降级为单线程且无重入，用 AtomicUsize 存 K（避免 thread_local 在此宏下的解析问题）。
    // 【`当前函数为初始化方法` 已彻底移除（2026-09-21 · A2 收口）】
    //   该开关用于把「初始化方法内的无值 `返回`」改写成 `返回 自身`，以配合 A2 的隐式 `返回 自身`。
    //   A2 移除后 初始化 = 普通方法、无返回值 ⇒ 无值 `返回` 就是无值返回，与其他函数**完全同源**，
    //   不需要任何按函数类型的特判（单源：`返回语句(None)` 只有一条路径）。
    pub static 模块用户函数数: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);
    /// ════════════════════════════════════════════════════════════════════════════
    /// 「始终」出口完备化（2026-09-16）：非局部退出（返回/跳出/继续）穿越始终。
    /// 语义目标：无论从哪个出口离开 捕获 区，其 始终 体都恰好执行一次（内层先、外层后），
    ///          且退出动作在整条始终链跑完之后才生效（与 Java finally 一致）。
    /// 实现约束（纯前端、零后端改动 —— 仅使用既有 LIR 原语）：
    ///   ① 每个 异常控制 层分配隐藏局部「站点槽」（整数64），危险块入口清 0；
    ///   ② 非局部退出站点：把唯一站点编号写入各层站点槽 → 跳最内层始终块；
    ///   ③ 每层始终块出口：查询重抛标志 → 传播块；否则 终止指令::切换(本层站点槽){点表, 默认=续延块}；
    ///   ④ 点表由「经过该层的退出站点」在降级时静态登记（内层外传 / 本层落点）；
    ///   ⑤ 落点：带值返回 → 函数统一返回块；裸返回 → 统一裸返回块；跳出/继续 → 循环 结束块/继续目标。
    /// ════════════════════════════════════════════════════════════════════════════
    pub static 始终层栈: RefCell<Vec<始终层>> = RefCell::new(Vec::new());
    /// 当前循环层栈（规范 §2.5.3：跳出/继续 的目标 = 最内层循环）。
    /// `循环语句` 降级时 push/pop；跳出/继续 读栈顶。与 始终层栈 同构，**纯前端、零后端改动**。
    pub static 循环栈: RefCell<Vec<循环层>> = RefCell::new(Vec::new());
    /// 函数级退出槽（每次 `转换函数` 重置；闭包降级保存/恢复，避免污染外层函数）。
    pub static 当前函数退出槽: RefCell<Option<退出槽位>> = RefCell::new(None);
}

/// 🆕 阶段 6b（2026-09-23）：槽的声明层级（**诊断用**）。
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum 槽声明层级 {
    /// 函数形参 / 闭包捕获（进入函数即存在）
    形参或捕获,
    /// 源码里的具名局部变量（含显式声明与隐式声明）
    局部变量,
}

/// 🆕 阶段 6b：**槽元数据**（只读记录；见 `当前函数槽元数据` 的说明）。
#[derive(Debug, Clone)]
pub struct 槽元数据 {
    pub 槽下标: usize,
    pub 名字: String,
    pub 声明层级: 槽声明层级,
    /// 记录时的底层表示类型调试名（`{:?}`）—— 便于"这个槽是什么形状"一眼可读。
    pub 类型名: String,
    /// 是否被登记进「拥有型槽清单」（与 `当前函数待释放局部` **同源**，仅作记录）。
    pub 可能拥有: bool,
}

/// 🆕 阶段 6b：登记一条槽元数据（按**槽下标**幂等：重复登记覆盖，保持"槽 → 元数据"唯一）。
pub(crate) fn 登记槽元数据(名字: &str, 槽下标: usize, 层级: 槽声明层级, 类型名: String, 可能拥有: bool) {
    当前函数槽元数据.with(|表| {
        let mut 表 = 表.borrow_mut();
        if let Some(项) = 表.iter_mut().find(|项| 项.槽下标 == 槽下标) {
            项.名字 = 名字.to_string();
            项.声明层级 = 层级;
            项.类型名 = 类型名;
            项.可能拥有 = 可能拥有;
        } else {
            表.push(槽元数据 { 槽下标, 名字: 名字.to_string(), 声明层级: 层级, 类型名, 可能拥有 });
        }
    });
}

/// 🆕 阶段 6b：**校验 + 转储**（env `智语言_转储槽元数据` 门控 ⇒ 产品路径零开销）。
///
/// 精确断言（**结构不变量，无启发式误报**）：
///   ① 清单项必须 `槽下标 < 局部表长度`（越界 = 真缺陷）；
///   ② 清单项不得重复（重复 ⇒ 弹帧**双份 −1** ⇒ 过度释放 ✗）；
///   ③ 打印"清单可还原名字数 / 清单长度"⇒ 让"清单里到底是什么"可读（排障关键：降级后名字本已消失）。
pub(crate) fn 校验并转储槽元数据(函数名: &str, 局部表长度: usize, 拥有型槽索引: &[usize]) {
    let 元数据 = 当前函数槽元数据.with(|表| 表.borrow().clone());
    let 名字可还原 = 拥有型槽索引
        .iter()
        .filter(|i| 元数据.iter().any(|m| m.槽下标 == **i))
        .count();
    let 越界 = 拥有型槽索引.iter().filter(|i| **i >= 局部表长度).count();
    let 重复 = 拥有型槽索引.len() - {
        let mut 去重 = 拥有型槽索引.to_vec();
        去重.sort_unstable();
        去重.dedup();
        去重.len()
    };
    let 转储 = std::env::var("智语言_转储槽元数据").is_ok();
    if 转储 || 越界 > 0 || 重复 > 0 {
        eprintln!(
            "[槽元数据] 函数={} 局部表={} 名录={} 清单={} 名字可还原={} 越界={} 重复={}",
            函数名, 局部表长度, 元数据.len(), 拥有型槽索引.len(), 名字可还原, 越界, 重复
        );
        if 转储 {
            for m in 元数据.iter() {
                eprintln!(
                    "     · 槽{} 名字={} 层级={:?} 类型={} 可能拥有={}",
                    m.槽下标, m.名字, m.声明层级, m.类型名, m.可能拥有
                );
            }
            for i in 拥有型槽索引.iter() {
                match 元数据.iter().find(|m| m.槽下标 == *i) {
                    Some(m) => eprintln!("     · 清单项 槽{} = `{}`（{}）", i, m.名字, m.类型名),
                    None => eprintln!("     · 清单项 槽{} = <无名（临时槽）>", i),
                }
            }
        }
    }
    debug_assert!(越界 == 0, "槽元数据自检：拥有型槽清单含越界下标");
    debug_assert!(重复 == 0, "槽元数据自检：拥有型槽清单含重复项（会导致双份 −1）");
}

/// 「始终」一层：始终块标识 + 本层「待办站点」隐藏槽 + 出口派发点表（站点编号 → 出口目标块）。
#[derive(Debug, Clone)]
pub struct 始终层 {
    pub 始终块: usize,
    pub 站点槽: usize,
    pub 点表: Vec<(i64, usize)>,
}

/// 函数级非局部退出状态（每个函数一份；闭包降级保存/恢复）。
#[derive(Debug, Clone)]
pub struct 退出槽位 {
    /// 「返回暂存」隐藏槽（usize::MAX = 尚未分配）。
    pub 返回暂存槽: usize,
    /// 「统一返回块」（带值返回跑完全部始终后的最终落点）。
    pub 统一返回块: usize,
    /// 「统一裸返回块」（无值返回跑完全部始终后的最终落点）。
    pub 统一裸返回块: usize,
    /// 站点编号计数器（从 1 起；0 保留表示「无待办」）。
    pub 下一站点编号: i64,
    /// 是否真的产生过非局部退出（决定是否产出统一落点块，避免不可达块）。
    pub 用过退出: bool,
    /// 闭包降级前的「始终层栈」长度（用于闭包隔离后恢复）。
    pub 闭包前层数: usize,
}

/// 循环一层：跳出/继续 的目标解析所需的最小信息。
#[derive(Debug, Clone, Copy)]
pub struct 循环层 {
    /// `继续` 的落点：有 步进 时为步进块，否则为条件块。
    pub 继续目标: usize,
    /// `跳出` 的落点：循环结束块。
    pub 结束块: usize,
    /// 进入本层循环时的「始终层栈」长度 —— 用于计算需穿越的始终层数。
    pub 入循环始终层数: usize,
}

/// 取当前最内层循环（规范 §2.5.3：跳出/继续 的目标 = 最内层循环）。
/// 栈空 = 语法层不变量被破坏（调用点 debug_assert 兜底）。
pub(crate) fn 取最内循环层() -> Option<循环层> {
    循环栈.with(|s| s.borrow().last().copied())
}

/// 🆕 方案B S1：读取当前基本块应标注的异常目标（栈空 = 函数顶层 = 无）。
pub(crate) fn 取当前异常目标() -> 异常目标 {
    当前异常目标栈.with(|s| s.borrow().last().copied().unwrap_or(异常目标::无))
}

/// 🆕 方案B S1：压入当前区域异常目标（异常控制 转换 进入 危险/异常/始终 区时调用）。
pub(crate) fn 压当前异常目标(目标: 异常目标) {
    当前异常目标栈.with(|s| s.borrow_mut().push(目标));
}

/// 🆕 方案B S1：弹出区域异常目标（区段转换结束、离开区域时调用，与压入严格配对）。
pub(crate) fn 弹当前异常目标() {
    当前异常目标栈.with(|s| {
        s.borrow_mut().pop();
    });
}

/// 「始终」出口完备化：惰性分配「返回暂存」隐藏槽（调用方给出底层槽类型）。
/// 单源：同一函数内所有 带值返回 站点共用同一槽。
pub(crate) fn 确保返回暂存槽(局部表: &mut Vec<底层表示类型>, 槽类型: 底层表示类型) -> usize {
    let 已 = 当前函数退出槽
        .with(|s| s.borrow().as_ref().map(|c| c.返回暂存槽).unwrap_or(usize::MAX));
    if 已 != usize::MAX {
        return 已;
    }
    let idx = 局部表.len();
    局部表.push(槽类型);
    当前函数退出槽.with(|s| {
        if let Some(c) = s.borrow_mut().as_mut() {
            c.返回暂存槽 = idx;
        }
    });
    idx
}

/// 「始终」出口完备化：登记一次非局部退出（返回/跳出/继续）。
/// 步骤：分配唯一站点编号 → 逐层登记「点表」（内层外传 / 本层落点）→ 写入各层站点槽 →
/// 终止指令改为跳「最内层始终块」。跑完整条始终链后由落点块执行真正的退出动作。
/// `层数` = 需要穿越的始终层数（0 表示无需穿越，调用方应走原有直达路径）。
/// 返回 true 表示已改写终止指令。
pub(crate) fn 发射非局部退出(当前块: &mut 基本块, 层数: usize, 落点块: usize) -> bool {
    if 层数 == 0 {
        return false;
    }
    let 站点 = 当前函数退出槽.with(|s| {
        let mut b = s.borrow_mut();
        match b.as_mut() {
            Some(槽) => {
                let n = 槽.下一站点编号;
                槽.下一站点编号 += 1;
                槽.用过退出 = true;
                n
            }
            None => 0,
        }
    });
    if 站点 == 0 {
        return false;
    }
    let (登记结果, 槽列表, 最内始终块) = 始终层栈.with(|s| {
        let mut 栈 = s.borrow_mut();
        let 深 = 栈.len();
        if 层数 > 深 {
            return (false, Vec::new(), usize::MAX);
        }
        let mut 槽列表 = Vec::with_capacity(层数);
        for j in 0..层数 {
            let idx = 深 - 1 - j; // 内层在前
            let 目标 = if j + 1 < 层数 { 栈[idx - 1].始终块 } else { 落点块 };
            栈[idx].点表.push((站点, 目标));
            槽列表.push(栈[idx].站点槽);
        }
        let 最内 = 栈[深 - 1].始终块;
        (true, 槽列表, 最内)
    });
    if !登记结果 {
        return false;
    }
    // 写入各层站点槽（同一站点编号；各层出口按各自点表派发）
    for 槽 in 槽列表 {
        当前块.指令列表.push(三地址码 {
            结果: 操作数::无,
            操作码: 操作码::存储,
            操作数1: 操作数::局部变量(槽),
            操作数2: Some(操作数::立即整数(站点)),
            调试位置: None,
            操作数3: None,
        });
    }
    当前块.终止指令 = 终止指令::无条件跳转(最内始终块);
    true
}

/// 「始终」出口完备化：把「本站点位于始终体/异常体内、需取消待传播异常」时的重抛标志复位。
/// 语义：始终体内 `返回` 覆盖待传播异常（与 Java finally 一致）；其余位置调用无害（本已为 0）。
pub(crate) fn 复位重抛标志以取消异常(当前块: &mut 基本块) {
    当前块.指令列表.push(三地址码 {
        结果: 操作数::无,
        操作码: 操作码::复位重抛标志,
        操作数1: 操作数::无,
        操作数2: None,
        调试位置: None,
        操作数3: None,
    });
}

/// 引用计数闭环（−1 侧）：发射「释放引用」——对当前函数登记的待释放栈槽局部逐个发射。
/// 调用点：`返回语句`（「始终」链为空时 = 出口不经过函数级落点块）与**函数末尾**（合成 返回 之前）。
/// ⚠ 已 `返回 <名称>` 移出的槽跳过（move 语义：所有权已交给调用方）。
///    「始终」链待办的出口走函数级落点块，本批不在落点块发射 ⇒ 那些路径**保守泄漏**
///    （绝不误回收），留待「异常路径 / 落点块」批次统一收紧。
pub(crate) fn 发射释放引用(当前块: &mut 基本块, 局部表: &mut Vec<底层表示类型>) {
    // ⚡帧级批量释放（2026-09-22）⚡ 开关开启时**停发逐槽释放**：释放改由引擎弹帧时按
    //   「拥有型槽索引」清单批量执行（见 base::值类型::帧级释放启用 / 批量释放槽清单）。
    //   ⚠ 与 base 侧**共用同一开关**，必须同开同关：
    //     只开 VM 侧 ⇒ 逐槽 + 批量**双份 −1**（提前回收）；只开前端侧 ⇒ 完全不释放（泄漏不降）。
    if base::值类型::帧级释放启用() { return; }
    let 列表 = 当前函数待释放局部.with(|s| s.borrow().clone());
    if 列表.is_empty() { return; }
    let 已移出 = 当前函数已移出名称.with(|s| s.borrow().clone());
    for (名称, 索引) in 列表 {
        if 已移出.contains(&名称) { continue; }
        // ⚠ 必须带「结果」槽位：字节码为寄存器式编码（dest + 操作数），
        //    若 结果=操作数::无 会与 VM 解码错位 ⇒ 越界 panic（本批实测踩过）。
        let 临时 = 局部表.len();
        局部表.push(底层表示类型::整数64);
        当前块.指令列表.push(三地址码 {
            结果: 操作数::局部变量(临时),
            操作码: 操作码::释放引用,
            操作数1: 操作数::局部变量(索引),
            操作数2: None,
            调试位置: None,
            操作数3: None,
        });
    }
}

/// 🆕 2026-09-22 引用计数闭环（**+1 侧**）：发射 `操作码::增加引用`（+1，非句柄无操作）。
///
/// 用途：**接口 / `任意<接口>` 是「标签」**（引用语义共享同一实例，规范 §4772/§4834）——
///   `可移动 标签 = 车丙;` 时标签槽**新产生一份对既有对象 `车丙` 的引用** ⇒ 必须 +1，
///   与「标签槽消亡/被覆盖」处的 −1（`发射释放槽` / `发射释放引用`）成对。
///
/// ⚠ 只在「**复制既有句柄**」时 +1；新建对象内嵌新建子对象属**移动**，不 +1（否则计数虚高 ⇒ 泄漏）。
///   两引擎共用同一 opcode/base 函数（`堆_增加引用`）⇒ **由构造保证双模一致**。
/// 🆕 2026-09-22：**此刻**本函数是否仍处于「可释放」状态（与 `函数转换.rs::清单可用` 对齐）。
/// 用途：`返回 <非裸变量>` 是否为调用方 `+1` 计数，取决于"这份计数能否被配平" —— 配平来源是
///   本函数**弹帧批量释放**（清单里的拥有型槽被 −1）。若本函数已被闸门判定为"不释放"，
///   此刻 +1 就**无人配平 ⇒ 幽灵计数（泄漏）**（实测：无条件 +1 曾使 `110内存值语义隔离矩阵` 存活 57 → 70 ✗）。
///   🔁 2026-09-22②：随 `函数转换.rs` 的闸门细化**放开闸门①（嵌套控制流）**（弹帧释放为单点释放，
///   不存在"某返回路径上槽未赋值"问题；详见 `函数转换.rs::清单可用` 注释）；仅保留闸门②（接口）。
///   ⚠ 已知边界：本判定看不到"本函数后续是否创建闭包"（需等匿名函数收集完成）⇒ 若某函数
///     既有投影返回又创建闭包，会产生 1 次幽灵计数（清单最终为空、无人配平）——方向为保守泄漏，接受并记录。
pub(crate) fn 本函数此刻可释放() -> bool {
    !当前函数含接口用法.with(|f| *f.borrow())
}

pub(crate) fn 发射增加引用(当前块: &mut 基本块, 局部表: &mut Vec<底层表示类型>, 源: 操作数) {
    // ⚠ 必须带「结果」槽位：字节码为寄存器式编码（dest + 操作数），结果=无 会与 VM 解码错位 ⇒ 越界 panic。
    let 临时 = 局部表.len();
    局部表.push(底层表示类型::整数64);
    当前块.指令列表.push(三地址码 {
        结果: 操作数::局部变量(临时),
        操作码: 操作码::增加引用,
        操作数1: 源,
        操作数2: None,
        调试位置: None,
        操作数3: None,
    });
}

/// 🆕 S2 覆盖释放：对「局部槽」当前持有的旧值发射 −1（`操作码::释放引用`）。
/// 用途：同一条声明/赋值语句在**循环体内重复执行**时，槽内旧值已无人引用 ⇒ 存储新值前先释放旧值。
/// 这是「循环体内直接创建临时对象」内存增长（实测 30 万次 99.4MB）的**直接解**。
/// 语义安全：base `堆_释放引用` **仅对 `标签_句柄` 生效** ⇒ 首次执行时槽为未初始化（空值标签 0）、
///          标量、函数指针等一律自动跳过（不会误碰槽 0 的有效对象）。
/// 顺序安全：调用点均在新值**已求值并完成深拷贝之后**（`甲 = 甲` 自引用也已复制成独立对象）。
pub(crate) fn 发射释放槽(当前块: &mut 基本块, 局部表: &mut Vec<底层表示类型>, 槽: usize) {
    // ⚠ 必须带「结果」槽位：字节码为寄存器式编码（dest + 操作数），结果=无 会与 VM 解码错位 ⇒ 越界 panic。
    let 临时 = 局部表.len();
    局部表.push(底层表示类型::整数64);
    当前块.指令列表.push(三地址码 {
        结果: 操作数::局部变量(临时),
        操作码: 操作码::释放引用,
        操作数1: 操作数::局部变量(槽),
        操作数2: None,
        调试位置: None,
        操作数3: None,
    });
    // 🆕 2026-09-22 **释放后写空值**（悬垂归零，与 `释放字面量源` 同款收口）：
    //   −1 只解除"本槽自持的那份引用"，但槽内仍留**陈旧句柄**；而两引擎的根枚举都对
    //   "帧区间 / 影子块"**全扫**（宁可多标，绝不漏标）⇒ 陈旧句柄被当根 ⇒ 对账报「悬垂引用」
    //   （实测：`112内存循环创建与槽覆盖` 周期行 3、`拷贝密集` 2/2；终局虽为 0，但**指标判别力受损**，
    //     且"陈旧句柄在 id 复用后被误读为有效对象"是潜在错值隐患）。
    //   ⚠ 安全性：本函数两处调用点之后**紧随新值的 `存储`**（见 变量声明 / 赋值 臂）⇒ 期间无任何读取该槽的
    //     指令 ⇒ 写空值不改变任何语义；也**不影响**函数出口的帧级批量释放（届时槽内是新值或空值）。
    当前块.指令列表.push(三地址码 {
        结果: 操作数::无,
        操作码: 操作码::存储,
        操作数1: 操作数::局部变量(槽),
        操作数2: Some(操作数::立即空值),
        调试位置: None,
        操作数3: None,
    });
}

/// 🔁 2026-09-24（**soak F 形状修复**）：对「**模块级全局槽**」当前持有的旧值发射 −1 + 写空值。
///
/// 为什么需要：全局槽的**声明 / 赋值**分支此前**只发 `存储`**，而全局槽**独占**其持有的复合对象
///   （模块级声明即拥有型）⇒ 循环内 `本模块.全局列 = [..]` **每轮旧数组无人 −1** ⇒
///   soak 实测 **+1/轮**（N=1000 存活 1005 → N=10000 存活 10005，**双引擎相同** ⇒ 前端同源）✗
///
/// 语义/顺序安全（与 `发射释放槽` 同款）：
///   · `存储` 发生在**新值求值并深拷贝之后** ⇒ 释放旧值不影响新值 ✓
///   · 首次执行时全局槽为**零值（空值标签 0）** ⇒ `堆_释放引用` 自动跳过 ⇒ **no-op** ✓
///   · `释放引用` 走**通用操作数**（解释器 `一元寄存器指令`；编译器按 base 单表委托）
///     ⇒ 全局操作数可用，**无需新增 opcode** ✓
/// ⚠ 门控（由调用方负责）：只在"新值**是独立对象**"时调用（复合类型 + 深拷贝/新建）——
///   文本 / 接口 / 函数标签的全局槽**不做 +1**（无配平）⇒ 释放会**过度回收**，故一律跳过（保守泄漏）✓
pub(crate) fn 发射释放全局槽(当前块: &mut 基本块, 局部表: &mut Vec<底层表示类型>, 全局索引: usize) {
    // ⚠ 必须带「结果」槽位（寄存器式编码：dest + 操作数），结果=无 会与 VM 解码错位 ⇒ 越界 panic。
    let 临时 = 局部表.len();
    局部表.push(底层表示类型::整数64);
    当前块.指令列表.push(三地址码 {
        结果: 操作数::局部变量(临时),
        操作码: 操作码::释放引用,
        操作数1: 操作数::全局变量(全局索引 + 1),   // 全局表索引自 gi+1 起（0 保留给异常标志）
        操作数2: None,
        调试位置: None,
        操作数3: None,
    });
    // 释放后写空值（悬垂归零，与 `发射释放槽` / `释放字面量源` 同款收口）✓
    当前块.指令列表.push(三地址码 {
        结果: 操作数::无,
        操作码: 操作码::存储,
        操作数1: 操作数::全局变量(全局索引 + 1),
        操作数2: Some(操作数::立即空值),
        调试位置: None,
        操作数3: None,
    });
}

/// 🆕 2026-09-22（**阶段 1a**）：判断表达式是否为「**新建文本**」——
/// 即运行期**新分配**一个文本对象（**无别名、无外部所有者**）的表达式形态。
///
/// 用途：文本槽在存储前 `+1`（共享一份，因文本**不可变** ⇒ 共享在语义上不可观测，规范 §7.3 合规）；
///   若右值本身是新建文本，还须把**生产者持有的那份计数**就地 −1（否则每执行一次留 1 个对象
///   ⇒ 循环内逐轮泄漏；实测探针 `I_文本赋值_300`：300 轮 ⇒ 存活 302，两引擎相同）。
///
/// ⚠⚠ **红线（实测踩过，2026-09-22）**：**绝不能**把判定扩大到"任意表达式结果"——
///   本文件 `释放字面量源` 的原注释早已写明："`返回 自身.字段` 这类返回值**不转移所有权**，
///   对它发释放会**误 free 仍被原对象持有的活对象**"。首版判定误把「**方法调用**／**用户函数调用**」
///   一并纳入（它们完全可能返回**借用的**文本，如 `取得名称()` 内部 `返回 自身.名称`）⇒
///   **单项落地即令 `121内存接口标签与容器循环回收` 双模 NG**（过度释放）✗
///   ⇒ 收紧为**白名单**：只收"**确定新建**"的形态。
///
/// **白名单（保守）**：
///   · `二元运算`（推断结果类型为文本 ⇒ 必为 `+` 拼接；base `堆_加法` 对文本**必新建**对象）✓
///   · `调用` 且函数名为**文本转换/生成类标准库**（见下白名单；这些实现**必新建**对象）✓
/// **不收**（皆可能为借用 ⇒ 只 +1，不释放生产者；宁可泄漏，绝不误回收）：
///   字面量（解释模式归常量池）、变量引用、字段访问、索引访问、枚举成员访问、隐式转换、
///   **方法调用**、**用户函数调用**。
fn 是新建文本表达式(e: &高层表示表达式) -> bool {
    // 🔁 2026-09-25（**必须透过「隐式转换」下钻**）★★ —— 修正"发送侧释放**永不发射**" ✗
    //   当形参类型为 `任意类型`（如 `通道.发送` 的载荷 `任意<甲>`；`任意<值>` 等）时，语义层会给实参
    //   包一层 `隐式转换 { 源表达式, 目标类型: 任意 }` ⇒ 原实现 ① 首行按**外层类型**判定（任意 ≠ 文本）
    //   ⇒ 直接 false ✗；② 即便过了，`match e` 也会落到 `_ => false` ✗
    //   ⇒ **现象**：`通道甲.发送(转文本(x))` 的文本实参**从未被 −1** ⇒ **+1 文本/轮（100% 泄漏）** ✗
    //   **实测证据（分解探针，解释模式；N=500/2000/8000）**：
    //     · `F14`（**发送静态文本** ⇒ 发送侧不新建堆文本）⇒ 存活 **4/4/4** ⇒ **接收侧记账正常** ✓
    //     · `F13`（发送 `转文本(计数)`）⇒ 存活 **503/2003/8003**、文本 **502/2002/8002** ⇒ **发送侧泄漏** ✓
    //   ⇒ 正解：**先下钻 `隐式转换.源表达式` 再判**（包装不改变"是否新建"这一事实 ✓）
    let e = match e {
        高层表示表达式::隐式转换 { 源表达式, .. } => 源表达式.as_ref(),
        _ => e,
    };
    if !matches!(从表达式推断(e), 类型信息::基本型(基本类型::文本)) { return false; }
    match e {
        // ① 文本拼接：`甲 + 乙` ⇒ base `堆_加法` 分配**新**文本对象
        高层表示表达式::二元运算 { .. } => true,
        // ② 文本转换/生成类标准库（实现均为"读入 → 分配新文本"）
        高层表示表达式::调用 { 函数名, .. } => matches!(
            函数名.as_str(),
            "转文本" | "整数转文本" | "小数转文本" | "逻辑转文本" | "任意转文本"
        ),
        _ => false,
    }
}

/// 🔁 2026-09-24（**D1 收尾：内置返回值记账**）★ —— 该调用是否为「**并发收发/等待类**」内置，
/// 其返回值**必为本调用新建的堆对象**（`拥有值转运行时值` 逐元素新建、计数 = 1、无别名）✓
///
/// **事实依据（已读 base 实现核实）**：
///   · `并发接收`（核心库 68）→ `拥有值转运行时值(&输出)` ⇒ **新建** ✓
///   · `并发等待任务` / `并发批量等待(超时)`（并发系统函数）→ `拥有值转运行时值(&结果)` ⇒ **新建** ✓
///   · 而 **`并发发送`** 走 `运行时值转拥有值(数据)` ⇒ **深转为自包含拥有值** ⇒ 通道**不持有**调用方句柄 ✓
///     （故"发送实参"侧可在调用点安全 −1，见调用路径；本判定只管**返回值**侧）
///
/// **为什么必须记账**：声明臂对文本槽/复合槽都已"**共享 +1**"（槽持一份），而新建返回值的
///   **生产者那份计数**无人持有 ⇒ 每收发一次泄漏 1 个对象 ✗（`115` 实测：`文本 204`
///   ≈ 100 次接收 + 100 次发送相关新建 ✓✓）
///
/// ⚠ **不可泛化到全部内置**（红线，与 `是新建文本表达式` 同）：`数组.取` / 映射取值 / 字段读等
///   完全可能返回**借用**句柄（无 +1）⇒ 泛化会**过度释放** ✗ ⇒ 仅收本表**经核实**的并发族 ✓
pub(crate) fn 是并发新建返回值(e: &高层表示表达式) -> bool {
    // 🔁 2026-09-25：与 `是新建文本表达式` 同款 —— **先透过 `隐式转换` 下钻**
    //   （形参为 `任意类型` 时实参被包装；不下钻会漏判 ⇒ 该值无人 −1 ⇒ 泄漏）✓
    let e = match e {
        高层表示表达式::隐式转换 { 源表达式, .. } => 源表达式.as_ref(),
        _ => e,
    };
    // ⚠ **HIR 有两种形态**（实测）：`通道甲.接收()` 是 **`方法调用 { 结构体名, 方法名 }`** ✗
    //   （不是 `调用 { 函数名 }` —— 首版只匹配 `调用` ⇒ 判定恒假 ⇒ 修复零效果 ✓ 教训记录）✓
    let 全名 = match e {
        高层表示表达式::调用 { 函数名, .. } => 函数名.clone(),
        高层表示表达式::方法调用 { 结构体名, 方法名, .. } => format!("{}.{}", 结构体名, 方法名),
        // ⚠ 一律用**子串/后缀**匹配（调用点函数名可能是限定名 `通道.接收` / base 名 `通道接收` /
        //   泛型限定 `通道<文本>`——`是只读检视系统函数` 曾因全等匹配失效，教训在此复用 ✓）
        _ => return false,
    };
    (全名.contains("通道") && (全名.ends_with("接收") || 全名.ends_with("尝试接收")))
        || (全名.contains("任务") && 全名.contains("等待"))
        || 全名.contains("批量等待")
}

/// 🔁 2026-09-24（**item 7：发送实参侧 · 白名单化**）★ —— 该调用是否为「**实参深转、不保留调用方引用**」
/// 的内置（即：调用期间就把实参**深转为自包含值**、调用返回后**不再使用**调用方对象）✓
///
/// **为什么需要**：`115` 中 `通道甲.发送(转文本(序号 * 2))` 的文本实参是**调用方自持的自有右值**，
///   而 base 的 `通道发送` 语义是 `运行时值转拥有值(数据)`（**深转自包含拥有值**，通道**不持有**
///   调用方句柄、**同步**完成）⇒ 调用返回后该文本**无人持有** ⇒ 不 −1 则**每发送一次泄漏 1 个文本** ✗
///   （实测：修后 `115` 文本 **104 → 1**、总存活 **226 → 19** ✓✓）
///
/// ⚠⚠ **必须白名单化**（红线，上一版泛化到"所有调用"⇒ 实测踩坑 ✓）：
///   泛化后 `总网络模块全面测试`（**解释**）出现 `悬垂(拥有型)=5` ✗ —— 网络类内置**并非**同步消费实参
///   （响应/请求处理经**任务/线程**异步持有该文本，且**交接处未 +1** ⇒ 与 D1「任务在途值」同源 ✗）
///   ⇒ 依铁律「**宁可泄漏，绝不误回收**」：**只收本表已核实"深转不保留"者**，其余一律不收 ✓
///
/// 收录标准（不得放宽）：① base 实现**同步**完成 ② 实参经 `运行时值转拥有值` **深转**（自包含）
///   ③ 调用返回后 base **不再引用**调用方对象。三者缺一不可 ✓
pub(crate) fn 是深转不保留名(全名: &str) -> bool {
    // 已核实（base `并发系统函数.rs::并发发送` = `运行时值转拥有值` + crossbeam 发送，同步且自包含 ✓）：
    全名.contains("通道") && (全名.ends_with("发送") || 全名.ends_with("尝试发送"))
}

/// 🔁 2026-09-24（**实参释放的"被调方白名单"**）★★ —— 仅当被调方**不会保留**实参时才可释放 ✓
///
/// **依据（账本证据 §18.104 + 四次尝试复盘）**：`网络.获取(网址, {选项映射})` 的选项映射被**被调方**
///   **移动**进请求结构体（**无 `+1`** ✓ = base 的"移动"语义）⇒ 若调用点再释放 = **多释放一次** ✗
///   （实测 `悬垂(拥有型)=2` ✗；账本：该对象 创建 1 → **零次 `+1`** → **两次 `−1`** ✓✓）
///   ⇒ 这**解释了此前四次"字面量侧"尝试为何全败**：被调方**始终**保留了那个对象 ✗
///
/// **判据（与 item 7 文本实参**同一机制** ✓）**：
///   · **用户函数** ⇒ 形参**借用**（`函数转换.rs` 明示"形参从不登记" ⇒ 被调方**不保留** ✓）⇒ 可释放 ✓
///   · **已核实"同步深转、不保留"的内置**（`是深转不保留名`：`通道.发送` 等 ✓）⇒ 可释放 ✓
///   · **其余（未核实的内置）** ⇒ **一律不收** ✓（宁可泄漏，绝不误回收 ✓）
/// ⚠ 闭包/间接调用（`间接调用` 路径）**不加本门** —— 闭包体是**用户代码**、形参同为借用 ✓ 安全 ✓
pub(crate) fn 实参可释放(
    函数名: &str,
    函数签名详情: &HashMap<String, (usize, Vec<Option<高层表示表达式>>, Vec<参数传递方式>, Vec<类型信息>)>,
) -> bool {
    函数签名详情.contains_key(函数名)                 // 用户函数 / 用户方法（形参借用 ✓ 不保留 ✓）
        || 是深转不保留名(函数名)                     // 已核实"同步深转、不保留"（`通道.发送` 等 ✓）
        || 是只读检视系统函数(函数名)                 // 既有"只读检视"表（长度/类型索引等 ✓ 只读不保留 ✓）
        || 函数名.contains("转文本")                  // `转文本` 族（`堆_任意/整数/小数/逻辑转文本` ✓ 只读不保留 ✓）
}

pub(crate) fn 是实参深转不保留内置(e: &高层表示表达式) -> bool {
    // ⚠ 同 `是并发新建返回值`：`通道甲.发送(x)` 是 **方法调用** 形态；`通道.发送(x)` 是 **调用** 形态
    let 全名 = match e {
        高层表示表达式::调用 { 函数名, .. } => 函数名.clone(),
        高层表示表达式::方法调用 { 结构体名, 方法名, .. } => format!("{}.{}", 结构体名, 方法名),
        _ => return false,
    };
    是深转不保留名(&全名)
    // ⏸ 待核（**不得**在核实前加入）：
    //   · 网络响应/请求类（`响应.发送` 等）—— 实测泛化会致悬垂 ✗，其内部疑似经任务异步持有 ⇒ 待核 ✓
    //   · `输出(...)` 等文本消费类（当前 soak 平坦 ⇒ 无需处理 ✓）
    //   · 用户函数调用（形参借用安全，但**被调方可能把文本存入全局槽**（全局槽无 +1 配平）⇒ 待核 ✓）
}

/// 🆕 M0.5：**复合字面量**源临时值的就地释放（引用计数 −1）。
/// 依据：`甲 = [1,2,3]` 的执行是「字面量新建对象 T（计数 1）→ 值语义深拷贝出 C → 甲 绑定 C」；
/// 此后无人再持有 T ⇒ 在深拷贝之后立即释放 T 是**安全**的（T 必为本次新建、无别名）。
/// ⚠ 严格限定「字面量」：不得扩大到"任意表达式结果"——例如 `返回 自身.字段` 这类返回值
///    **不转移所有权**，对它发释放会误 free 仍被原对象持有的活对象。
pub(crate) fn 释放字面量源(
    当前块: &mut 基本块,
    局部表: &mut Vec<底层表示类型>,
    源: &操作数,
    是否复合字面量: bool,
) {
    if !是否复合字面量 { return; }
    let 临时 = 局部表.len();
    局部表.push(底层表示类型::整数64);
    if let 操作数::局部变量(槽) = 源 {
        let 源槽 = *槽;
        当前块.指令列表.push(三地址码 {
            结果: 操作数::局部变量(临时),
            操作码: 操作码::释放引用,
            操作数1: 源.clone(),
            操作数2: None,
            调试位置: None,
            操作数3: None,
        });
        // 🆕 2026-09-22 **释放后写空值**（UFC 边界收口 ⑥）：临时槽在 −1 后仍持有**陈旧句柄**
        //   ⇒ 保守根扫描（UFC 宁可多标）会把它当根 ⇒ 对账报「悬垂引用」噪声（实测解释模式 6–103，编译模式 0）
        //   ⇒ 归零该槽：① 消除噪声；② 杜绝后续重复 −1 的可能。
        //   ⚠ 仅对**本次释放的临时槽**（该操作数已被消费，不再被读取）⇒ 不影响任何在用值。
        当前块.指令列表.push(三地址码 {
            结果: 操作数::无,
            操作码: 操作码::存储,
            操作数1: 操作数::局部变量(源槽),
            操作数2: Some(操作数::立即空值),
            调试位置: None,
            操作数3: None,
        });
    } else {
        当前块.指令列表.push(三地址码 {
            结果: 操作数::局部变量(临时),
            操作码: 操作码::释放引用,
            操作数1: 源.clone(),
            操作数2: None,
            调试位置: None,
            操作数3: None,
        });
    }
}

/// 判断是否为**复合字面量**（数组/映射字面量，M0.5 安全释放的唯一适用形态）。
pub(crate) fn 是复合字面量(表达式: &高层表示表达式) -> bool {
    matches!(
        表达式,
        高层表示表达式::字面值(高层表示字面值::数组(..) | 高层表示字面值::映射(..), _)
    )
}

/// ★单源★ 判断是否为**新建值**（`创建结构体` / 复合字面量）——
/// **本语句新产生、句柄从未外泄 ⇒ 不可能是别名** ⇒ 值语义存储可**安全省略深拷贝**。
///
/// 这是"**可证明的拷贝省略**"（零拷贝优化）的唯一判据：
///   · `甲 = 单车(0)` / `函数(单车(0))` / `列表.追加([1,2,3])` ⇒ 新建值 ⇒ 免拷贝 ✓
///   · `甲 = 乙` / `甲 = 乙.字段` / `甲 = f()` ⇒ **可能被别处持有** ⇒ 必须拷贝 ✓
///
/// ⚠ 不得扩大范围到"任意表达式结果"：函数调用结果虽是新对象，但**所有权未必在本语句**
///   （可被闭包捕获/返回缓存等），故不在本条内（由各自的成对记账负责）。
pub(crate) fn 是新建值(表达式: &高层表示表达式) -> bool {
    // 🔁 2026-09-25：同款**透过 `隐式转换` 下钻**（形参为 `任意类型` / 接口时实参被包装 ⇒
    //   不下钻会把"新建值"误判为非新建 ⇒ 既少了一次免拷贝优化，也少了一次源临时 −1）✓
    let 表达式 = match 表达式 {
        高层表示表达式::隐式转换 { 源表达式, .. } => 源表达式.as_ref(),
        _ => 表达式,
    };
    matches!(表达式, 高层表示表达式::创建结构体 { .. }) || 是复合字面量(表达式)
}

/// 🔁 2026-09-23（**soak 门禁实测缺陷修复**）：**"用户函数调用"在复合值语境下 = 调用方持有计数引用**。
///
/// 依据（前端自有的所有权规则，两处已文档化）：
///   · `返回 <裸名变量>` ⇒ 该槽被 `当前函数已移出名称` 排除 ⇒ **移动语义**（所有权交给调用方）✓
///   · `返回 <投影>`（`甲.字段`/`甲[下标]`）⇒ 被调方**已在返回处为调用方 `+1` 计数一份** ✓
///   ⇒ 两种情形下，**调用点都持有一份"自有的"计数引用** ⇒ 若该值被**深拷贝入目标槽**（声明/赋值），
///     则**那份源临时引用必须 −1**（否则逐轮泄漏）。
///   ⚠ 为什么只认**用户函数**（`函数签名详情` 有登记）：其"返回即移出/投影 +1"规则由**前端自己**保证 ✓；
///     标准库 / 系统函数返回复合值时的所有权口径**未逐一取证**（可能返回**借用**句柄）
///     ⇒ **一律不释放**（宁可保守泄漏，绝不过度释放 ⇒ 不引入悬垂）✓
///   实测（soak 探针 A，双引擎数值相同）：`载体 = 造一次(计数)` 每轮泄漏 1 个根对象 + 其级联子对象
///     （小N=1000 存活 2007 → 大N=10000 存活 20007 ⇒ **+2/轮**）✗
pub(crate) fn 是用户函数调用(
    表达式: &高层表示表达式,
    函数签名详情: &HashMap<String, (usize, Vec<Option<高层表示表达式>>, Vec<参数传递方式>, Vec<类型信息>)>,
) -> bool {
    // ⚠ 必须**同时**满足「用户函数」与「**返回即转移**」（见 `返回即转移函数集` 注释）：
    //   仅凭"是用户函数"就 −1 会打中**借用返回**（`返回 传引用形参`）⇒ 过度释放 ⇒ `无效句柄` ✗
    matches!(表达式, 高层表示表达式::调用 { 函数名, .. }
        if 函数签名详情.contains_key(函数名.as_str())
            && 返回即转移函数集.with(|s| s.borrow().contains(函数名.as_str())))
}

/// 🔁 2026-09-23（**soak 门禁 C 形状修复**）：**该表达式是否"确定产生一个新的闭包对象"**。
///
/// 用途：**函数类型槽**（闭包环境 = 堆对象）的「**别名 vs 新建**」分流（见声明/赋值臂注释）。
///   · `匿名函数(..)` **闭包字面量** ⇒ 现场新建、无他人持有 ✓
///   · **返回即转移**的用户函数调用（`返回 <自有裸名局部>` / `返回 <闭包字面量>`）⇒ 所有权交给调用方 ✓
/// ⚠ 其余一律视为**别名**（变量/字段/索引/未证明的调用）⇒ 调用方按别名 `+1`（宁可多持一份 ⇒ 保守泄漏；
///   绝**不能**因缺 +1 而**过度释放**共享闭包 ✗ —— 那会造成悬垂，方向性错误）。
/// ⚠ 另注：`函数指针`（静态函数引用，纯值不计数）在 base 侧释放/`+1` 均自动 no-op ⇒ 无需特判 ✓
pub(crate) fn 确定新建闭包(
    表达式: &高层表示表达式,
    函数签名详情: &HashMap<String, (usize, Vec<Option<高层表示表达式>>, Vec<参数传递方式>, Vec<类型信息>)>,
) -> bool {
    match 表达式 {
        高层表示表达式::匿名函数(_) => true,
        _ => 是用户函数调用(表达式, 函数签名详情),
    }
}

pub fn 转换语句(
    语句: &高层表示语句, 当前块: &mut 基本块, 块列表: &mut Vec<基本块>, 块编号: &mut usize,
    局部表: &mut Vec<底层表示类型>, 变量映射: &mut HashMap<String, usize>,
    常量池: &mut Vec<常量值>, 结构体布局: &HashMap<String, Vec<(String, 底层表示类型)>>,
    函数索引映射: &mut HashMap<String, usize>,
    结构体类型索引: &HashMap<String, usize>,
    函数签名详情: &HashMap<String, (usize, Vec<Option<高层表示表达式>>, Vec<参数传递方式>, Vec<类型信息>)>,
    全局变量名列表: &[String],
    匿名函数收集: &mut Vec<(usize, 底层表示函数)>,
    后续块标识: usize,
) {
    match 语句 {
        高层表示语句::表达式语句(e) => {
            let val = 转换表达式(e, 当前块, 块列表, 块编号, 后续块标识, 局部表, 变量映射, 常量池, 结构体布局, 函数索引映射, 结构体类型索引, 函数签名详情, 全局变量名列表, 匿名函数收集);
            // 🔁 2026-09-25（**表达式语句丢弃的结果若是"本语句独占的新建对象" ⇒ 就地 −1**）★ 修"接收丢弃"泄漏：
            //   `甲.接收()` 作为**独立表达式语句**（结果被丢弃）时，该结果由 `拥有值转运行时值`
            //   **本调用新建**（base 已核实、计数=1、无别名 ✓）而**无人持有** ⇒ 不释放则每执行一次泄漏 1 ✗
            //   **实测**（`F17_接收丢弃` / `F20_静态载荷接收丢弃`，N=500/4000 ⇒ 文本 502/4002 ✗）
            //   ⚠ 严格白名单（与 `是并发新建返回值` 同源）：仅收"**确定新建、无别名**"的形态；
            //     变量引用 / 字段访问 / 用户函数调用等**可能借用**者一律**不收**（宁可泄漏，绝不误回收）✓
            if 是并发新建返回值(e) {
                if let 操作数::局部变量(槽) = val {
                    发射释放槽(当前块, 局部表, 槽);
                }
            }
        }
        高层表示语句::变量声明 { 名称, 初始值, 类型, 是否模块级, .. } => {
            let val = 转换表达式(初始值, 当前块, 块列表, 块编号, 后续块标识, 局部表, 变量映射, 常量池, 结构体布局, 函数索引映射, 结构体类型索引, 函数签名详情, 全局变量名列表, 匿名函数收集);
            // 接口是引用语义：目标类型为接口型时，右值（结构体/接口句柄）仅复制指针(句柄)，
            // 共享同一实现对象，使接口方法经 thunk(__object 传引用) 原地修改作用于原实例。
            let 目标接口 = 是接口引用类型(类型);
            let 推断类型 = 从表达式推断(初始值);
            let 需要 = !目标接口 && 是复合类型(&推断类型);
            // 🔁 2026-09-22 **槽位级「新建值免拷贝」重试（开关门控）**
            //   历史（2026-09-21）：曾启用后 **8 例门禁回归**，根因是"覆盖释放被放宽 + **接口标签不计数**"
            //     ⇒ `甲 = 单车(0); 可移动 设备 = 甲; 甲 = 单车(1)` 释放旧值 ⇒ **标签悬垂** ✗。
            //   现状：A1 已落地（接口标签 ±1 配对）⇒ 根因已消除；并**再挂 `智语言_帧级释放` 开关**：
            //     ⚠ 2026-09-25 校正：该开关**默认「开」**（值类型.rs::帧级释放启用，2026-09-22 起），
            //     故本特性**默认生效**（原文写「默认关 ⇒ 行为与历史完全一致」已过期）；
            //     仅当显式 `智语言_帧级释放=0` 时才退回历史行为。
            //   实测意义：`点 甲 = 点()` 每轮**不再多造一个副本**（原：新对象 + 深拷贝副本，**原始对象**
            //     留在表达式临时槽 ⇒ 200 轮泄漏 201 个对象 ✗）。
            //   ✅ 2026-09-22 后续：字面量元素已在**构造处**保证独立副本（规范 §4993 源头落地，
            //     见 字面值::数组 分支）⇒ 原先为绕开该缺口而加的 `!类型含接口` **收窄已解除**。
            let 声明新建值 = matches!(初始值, 高层表示表达式::创建结构体 { .. }) || 是复合字面量(初始值);
            // 🔁 2026-09-25（**并发收发/等待类返回值 ⇒ 免拷贝**）★★ 修「通道接收 +1/轮」的根本一刀：
            //   账本证据（`F21_单次收发账本`，N=1）：**每次接收分配 2 个文本、只释放 1 个** ✗
            //     ⇒ `拥有值转运行时值` 新建 1 个 + 前端**深拷贝**再新建 1 个（`需要` 为真，推断类型为`任意`）
            //   而 `接收` 的返回值是 base 已核实的「**本调用新建、无别名**」对象
            //     （`拥有值转运行时值` 逐元素 `分配*`、计数=1 ✓）⇒ **无需深拷贝**（与 `甲 = 点(0)` 免拷贝同款原则）✓
            //   ⇒ 免拷贝后：只 1 次分配、槽**直接持有**该对象 ⇒ 覆盖/弹帧释放即闭环 ✓
            //   ⚠ 门控 `帧级释放启用()` 与既有 `声明新建值` 免拷贝**同开同关**（零回归逃生）✓
            let 免拷贝 = (声明新建值 || 是并发新建返回值(初始值)) && base::值类型::帧级释放启用();
            let 需要_实际 = 需要 && !免拷贝;
            let 源val = val.clone();
            // ⚡按成员身份⚡：含接口成员的复合类型走"逐成员拷贝"，接口成员只复制标签（见 发射深拷贝_类型感知）
            let val = 发射深拷贝_类型感知(当前块, 块列表, 块编号, 局部表, val, &推断类型, 需要_实际, 结构体类型索引);
            // 🆕 M0.5：复合字面量源临时值就地释放（字面量必为新建对象、无别名 ⇒ **且已深拷贝**才可释放）
            //   ⚠ 免拷贝（= 转移）时源临时槽仍是**同一对象**的持有者 ⇒ 不可释放（否则刚转移的对象被回收 ✗）
            // 🔁 2026-09-23（**soak 门禁实测缺陷修复**）：**用户函数调用结果**同理须释放源临时 ——
            //   被调方以"移动"交回所有权（`返回 裸名`）或已为调用方 `+1`（`返回 投影`）
            //   ⇒ 调用点持有一份**自有**引用 ⇒ 已深拷贝入槽后必须 −1（详见 `是用户函数调用` 注释）✓
            释放字面量源(
                当前块,
                局部表,
                &源val,
                // 🔁 2026-09-24（**D1 收尾**）：**并发收发/等待类**内置返回值亦为"本次调用新建的独立对象"
                //   （`是并发新建返回值` ⇒ `拥有值转运行时值` 新建、无别名）⇒ 已深拷贝入槽后须 −1 ✓
                需要_实际
                    && (是复合字面量(初始值)
                        || 是用户函数调用(初始值, 函数签名详情)
                        || 是并发新建返回值(初始值)),
            );
            // ⚠【已回退：槽位级「新建值免拷贝」（2026-09-21 实测回归后撤销）】
            //   曾在 变量声明/赋值 臂启用（源为 `创建结构体`/复合字面量 ⇒ 直接入槽、不深拷贝），
            //   **结构体门禁实测 8 例回归**（13赋值规则 / 14接口功能 / 15值传递引用传递 / 16 / 20 …，双模皆 FAIL）。
            //   根因：免拷贝后「覆盖释放」必须放宽为"新值独立即释放旧值"，而**接口标签不计数**
            //     ⇒ `甲 = 单车(0); 可移动 设备 = 甲; 甲 = 单车(1)` 会释放旧值 ⇒ **标签悬垂** ✗
            //   ⇒ 槽位级免拷贝**必须与「接口 / `任意<接口>` 真实计数 + 撤闸门②」同批落地**（待办·阶段三）。
            //   **已保留的安全部分**：调用实参路径的新建值免拷贝（无"覆盖释放"耦合，已验 169/169 全绿）。
            // 🔁 2026-09-22③（**闸门②粒度细化：整函数禁用 ⇒ 按槽排除**）：
            //   旧行为：声明类型含接口型（含嵌套，如 `数组<接口>`）⇒ **本函数整体**不发射释放。
            //   问题：接口型是常见用法 ⇒ 近乎"整程序零释放"（实测 `111内存接口标签生命周期` 存活 56/56 = 全部存活）。
            //   新行为：**只把该槽排除**（不登记 ⇒ 不参与释放），函数内**其余纯值语义复合槽照常回收**；
            //     判定落在下方「登记」处（`!类型含接口(类型) && !类型含接口(&推断初值)`）。
            //   依据：危险的不是"函数里有接口"，而是"某个槽持有的对象**内含未计数的接口标签**"
            //     （容器元素 / 结构体成员）⇒ 释放该容器会级联 −1 到**共享实例** ⇒ 误回收
            //     （实测：结构体项目 `14接口功能全面验证`/`15值传递引用传递全面验证` 的"接口数组元素·原实例不受影响"）。
            //     ⇒ 精确到**槽**即安全；接口**变量槽**（`可移动 设备 = 车丙`）不受此限（其引用已由
            //       `发射增加引用` 与覆盖释放配对 ✓）。
            // 模块级全局变量声明：写入独立全局存储（索引0保留给异常标志，故 +1 偏移），
            // 不占用局部槽——使其与子函数对该全局的访问（全局变量(gi+1)）一致，跨函数可见。
            // ★§2.4.7 收口（2026-09-19）：必须**同时**满足「语义层标注为模块级声明」——
            //   此前只看名字是否在 `全局变量名列表` 中 ⇒ 函数内 `X = 值`（X 与模块级变量同名，
            //   语义层已判为**隐式声明局部**）仍会写全局槽 ⇒ 模块级被静默误改。
            let 全局索引 = if *是否模块级 { 全局变量名列表.iter().position(|n| n == 名称) } else { None };
            if let Some(gi) = 全局索引 {
                // 🔁 2026-09-24（soak F 修复）：模块级声明**同样先释放旧值**（首次执行 = no-op：槽为零值）✓
                //   （`声明新建` 在下方局部槽分支内定义、此处不可见 ⇒ 内联同款判定）
                if 需要
                    || matches!(初始值, 高层表示表达式::创建结构体 { .. })
                    || 是复合字面量(初始值)
                {
                    发射释放全局槽(当前块, 局部表, gi);
                }
                当前块.指令列表.push(三地址码 { 结果:操作数::无, 操作码:操作码::存储, 操作数1:操作数::全局变量(gi + 1), 操作数2:Some(val), 调试位置:None, 操作数3: None, });
            } else {
                let idx = 局部表.len(); 局部表.push(转换类型(类型)); 变量映射.insert(名称.clone(), idx);
                // 🆕 S2 覆盖释放：同一声明语句在**循环体内重复执行**时，槽内旧值已无人引用 ⇒ 先 −1 旧值。
                //    顺序安全：新值已算完并完成深拷贝（`甲 = 甲` 自引用也已复制为独立对象）⇒ 释放旧值不影响新值。
                //    语义安全：`堆_释放引用` 仅对 `标签_句柄` 生效 ⇒ 首次执行时槽为未初始化（空值标签 0）或标量 ⇒ 自动跳过。
                //    保守边界①：接口相关（目标接口 / 声明类型含接口 / 右值含接口）不释放 —— 接口共享实例无 +1。
                //    安全条件：右值**已发生值语义深拷贝**（`需要`）⇒ 新值是独立对象，旧值独占属于本槽 ⇒ 释放安全。
                //    ⚠ 不可放宽到"未深拷贝的右值"：标量文本等非复合类型直接持有容器元素的句柄（不深拷贝），
                //      此时释放旧值＝误回收容器仍持有的对象（实测曾致 `09 传值默认行为`/`109 遍历数组`/
                //      `23 数组遍历` 三例失败、对账 9→13）。
                // 🔁 2026-09-22 覆盖释放条件**修正**：`新建值`（深拷贝被省略 = 移动）时，槽**同样独占旧值**
                //   ⇒ 必须先 −1 旧值。否则循环体 `点 临时 = 点()` 每轮泄漏一个旧对象
                //   （实测 `112内存循环创建与槽覆盖` 泄漏 660 = 逐轮累积）。
                //   ⚠ 仍排除「借用型槽」：非新建且未深拷贝（如 `文本 s = 列表[1]`）⇒ 槽内是**他人**对象的句柄 ⇒ 不释放。
                let 声明新建 = matches!(初始值, 高层表示表达式::创建结构体 { .. }) || 是复合字面量(初始值);
                // 🔁 2026-09-22⑦（**覆盖释放守卫解除"含接口"项**，单项落地）：旧值为**本槽独占** ——
                //   接口标签已 +1 配平、容器元素按身份拷贝为**独立副本**、结构体接口字段由 `按身份拷贝` +1
                //   ⇒ 覆盖时**必须 −1**，否则旧容器（及其内部元素）**逐轮泄漏**
                //   （实测 `K_泄漏拆分_丙接口数组`：`列`/`副` 声明处无覆盖释放 ⇒ 数组 2/轮 + 元素结构体随之存活 ✓✓）
                // 🆕 2026-09-22（**阶段 1a：文本槽纳入拥有型体系**）
                //   目标模型（方案《命名空间_作用域_内存管理技术方案》§5.3）：
                //     **文本 = 值语义的不可变堆对象** —— 表示上允许共享（`+1`），语义上不可区分
                //     （规范 §2.6.8 文本 `===` 为**值比较** + 文本**不可变**）⇒ 槽可**安全 −1**。
                //   配对（I1/I2）：存储前 `+1` ⟷ 覆盖释放 −1 / 弹帧批量释放 −1。
                //   ⚠ 修正的旧行为：文本（基本型）既不 `+1` 也不登记（"借用约定"）⇒ 循环内每次
                //     对文本变量赋值都**泄漏旧对象**（实测探针 `I_文本赋值_300`：300 轮 ⇒ 存活 **302**，
                //     且**两引擎完全相同** ⇒ 属"两引擎同源同错"，双模门禁查不出）。
                //   ⚠ 门控 `帧级释放启用()`：开关关闭时本批行为**与今日逐字节一致**（零回归逃生）。
                let 推断初值文本 = matches!(从表达式推断(初始值), 类型信息::基本型(基本类型::文本))
                    || matches!(类型, 类型信息::基本型(基本类型::文本));
                let 文本槽 = 推断初值文本 && base::值类型::帧级释放启用();
                // 🔁 2026-09-23（**soak 门禁 C 形状修复**）：**函数类型槽纳入拥有型体系**。
                //   背景：`是复合类型(函数类型) = false` ⇒ 闭包值**既不登记也不覆盖释放** ⇒
                //     循环内 `加法器 = 创建加法器(计数 % 5)` **每轮 +1**（soak 探针 C：1004 → 10004）✗
                //   为什么函数类型也**不能深拷贝**：闭包环境 = 捕获变量集合，深拷贝会把捕获**断开连接**
                //     （闭包必须与其捕获共享同一实例）⇒ 只做**引用计数**，绝不做值拷贝 ✓
                //   配对（I1/I2，与接口标签同法）：
                //     · 右值**确定新建**（闭包字面量 / 返回即转移的调用）⇒ 转移即持有 ⇒ **不 +1**
                //     · 否则视为**别名** ⇒ `+1` ⇒ 覆盖/弹帧 `−1` 三者平衡 ✓
                let 推断初值_函数 = matches!(从表达式推断(初始值), 类型信息::函数类型(_, _))
                    || matches!(类型, 类型信息::函数类型(_, _));
                let 函数槽 = 推断初值_函数 && base::值类型::帧级释放启用();
                // 🔁 2026-09-25（**并发收发/等待类返回值 ⇒ 覆盖释放**）★★ 修「通道收 +1/轮」泄漏：
                //   `收 = 甲.接收()` 的**推断类型 = `任意类型{}`** ⇒ `需要/文本槽/函数槽` 全假 ✗
                //   ⇒ 循环内**每次覆盖**都留下上一轮收到的堆文本（`拥有值转运行时值` **必定新建**，
                //     base 已核实 ⇒ 无别名、槽独占 ✓）⇒ **+1 文本/轮（100% 泄漏）** ✗✗
                //   **实测**（`日志/脚本/临时/soak/`，解释模式，N=500/4000）：
                //     · 仅发送（`F16`）**3/3 平坦** ✓ ⇒ 发送侧正常；· 接收丢弃（`F17`/`F20`）
                //       与接收赋值（`F13`）**均 502→4002** ⇒ 泄漏在**接收侧覆盖** ✓
                //   ⇒ 与 `声明新建`/`文本槽`/`函数槽` **同款原则**：右值是"本槽独占的新建对象" ⇒ 覆盖前必须 −1 ✓
                let 并发新建槽 = 是并发新建返回值(初始值);
                let 应覆盖释放 = 需要 || 声明新建 || 目标接口 || 文本槽 || 函数槽 || 并发新建槽;
                if 应覆盖释放 {
                    发射释放槽(当前块, 局部表, idx);
                }
                // 🔁 2026-09-22④（**接口真实计数 · 阶段三**，两引擎同源）：
                //   条件由 `是复合类型(右值)` 放宽为 **"右值可能携句柄（非标量）"** ——
                //   此前**漏掉"标签 ← 标签"**这一类（`设备乙 = 设备甲`、`可移动 设备 = 某接口参数/容器元素`）：
                //   槽内是**标签别名**却**未 +1** ⇒ 释放该槽 = 误回收仍被他人共享的实例 ✗
                //   （这正是"接口变量槽此前不敢登记"的根因；补齐 +1 后接口槽即可安全登记 ✅，见下方登记处）。
                //   ⚠ 文本（基本型）仍按既有"借用不计数、不登记"约定 ⇒ 不在此放宽。
                let 右值携句柄 = !matches!(从表达式推断(初始值), 类型信息::基本型(_));
                // 🆕 阶段 1a：文本槽**共享 +1**（与覆盖释放 / 弹帧释放配对）
                // 🔁 2026-09-23：**函数槽的别名 +1**（仅当右值**非**确定新建 ⇒ 可能是他人闭包的别名；
                //   若为函数指针则该指令自动 no-op ⇒ 零副作用）✓
                if (目标接口 && !声明新建 && 右值携句柄) || 文本槽
                    || (函数槽 && !确定新建闭包(初始值, 函数签名详情)) {
                    发射增加引用(当前块, 局部表, val.clone());
                }
                当前块.指令列表.push(三地址码 { 结果:操作数::无, 操作码:操作码::存储, 操作数1:操作数::局部变量(idx), 操作数2:Some(val.clone()), 调试位置:None, 操作数3: None, });
                // 🆕 阶段 1a：右值为「**新建文本**」（调用/方法调用/二元运算且结果为文本）⇒ 生产者那份计数
                //   无人持有 ⇒ 就地 −1（治 `转文本()`/拼接 的逐轮泄漏；探针 `I_文本赋值_300` 的泄漏源）。
                //   ⚠ 安全边界：只收"所有权归调用方"的形态；字面量/变量引用/字段/索引访问一律不收（借用）✓
                //   ⚠ 自引用（`s = s`）：源即本槽 ⇒ 禁止释放（否则清空本槽）✓
                let 源自同槽 = matches!(val, 操作数::局部变量(v) if v == idx);
                // 🔁 2026-09-24（**D1 收尾**）：**并发收发/等待类**内置的返回值同样是"本调用新建"
                //   ⇒ 槽已 +1 共享后，生产者那份计数须就地 −1 ✓（治 `115` 的 `文本 204` 一半 ✓）
                // 🆕 2026-10-13（**映射读值的生产者 −1**）：本分支前提 = `文本槽`（存入值**必为文本**）
                //   ⇒ 缺陷C1 的"命中文本即 +1"**必然已发生**（`.获取` 走 `映射安全加载`/`映射加载`；
                //     `地[键]` 走 `索引加载`，且**接收者静态类型是映射** ⇒ 运行期必走映射分支）
                //   ⇒ 与上方槽位 `+1` **严格对偶**：槽持有自己那份 ⇒ 生产者那份须就地 −1（消除重复计数）。
                //   ⚠ 实测依据（探针38）：带类型接收者 `映射<文本,文本> 地` 的 `地[键]` 返回值类型可推断为文本
                //     ⇒ `文本槽=true` ⇒ 本分支命中 ⇒ 修复"每调用泄漏 1"。
                if 文本槽
                    && (是新建文本表达式(初始值)
                        || 是并发新建返回值(初始值)
                        || 是映射读调用(初始值)
                        || 是映射索引读(初始值))
                    && !源自同槽
                {
                    释放字面量源(当前块, 局部表, &val, true);
                }
                // 🆕 引用计数（−1 侧）登记：复合类型局部（赋值/传参已深拷贝 ⇒ 独立对象，
                //    每个声明点独占局部槽、槽不复用 ⇒ 在函数出口释放安全）。
                //    🔁 2026-09-22：**接口型亦登记** —— 其引用已由上方 `发射增加引用` +1 配平（此前"不登记"
                //      是因为标签无 +1、释放会误回收；配对后释放即安全）。
                //    🔁 2026-09-22② **登记判定补全**（实测驱动）：原先只看**声明类型** `类型`，
                //       当声明未标注类型（`临时 = 载荷()`）而类型推断又未回填时 ⇒ **漏登记** ⇒
                //       清单为空 ⇒ 弹帧释放失效（`造一次` 局部表 16、清单 = []，逐轮泄漏 405）。
                //       ⇒ 扩为四选一：接口目标 / 声明类型复合 / **推断初值复合** / **声明即新建复合值**
                //         （后者为"移动"语义：槽直接独占新建对象 ⇒ 属拥有型槽 ✓）。
                let 推断初值 = 从表达式推断(初始值);
                // 🔁 2026-09-22④（**阶段三：按槽登记判定放宽**）：
                //   ① **纯接口型槽**（`可移动 设备 = 车丙` / `设备乙 = 设备甲`）：其引用已由上方
                //      "非新建 ⇒ +1"配平 ⇒ **可安全登记**（出口 −1 平衡，接口实例不再永久泄漏）✅
                //   ② **含接口成员的对象槽**（`数组<接口>` / 结构体含接口字段 / `任意<接口>`）：
                //      · 本次**新建**（字面量 / 构造）⇒ 成员标签由"容器元素/字段存储 +1 约定"计数 ⇒ **登记** ✅；
                //      · 来自**深拷贝**（`副本 = 列表`）⇒ 深拷贝按成员身份**只复制标签、不为成员 +1** ⇒
                //        新容器持有**未计数别名** ⇒ 释放会级联误回收 ⇒ 仍**排除**（保守，绝不误回收）✗
                //   ④ 2026-09-22⑤：排除条件先由"**含接口**（含容器）一刀切"收窄为"结构体直接接口字段"——
                //      依据：容器元素拷贝时**被克隆为独立副本**（规范 §4993/§4996）⇒ 元素是新建对象（计数 1 归容器）
                //      ⇒ 容器槽**可安全释放** ✅
                //   ⑤ 2026-09-22⑥（**阶段三收口：排除彻底解除**）：结构体接口字段的计数**已闭合**——
                //      · `发射按身份拷贝` 结构体分支对接口字段**已发 `增加引用`**（+1，与"宿主结构体级联释放 −1"配对，I1）✓
                //      · 新建路径（`创建结构体` + 字段存储）按"字段存储 +1 约定"计数 ✓
                //      ⇒ **含接口成员的槽亦可安全登记**（不再有任何"含接口 ⇒ 不释放"的特例）✅
                // 🔁 2026-09-23：**函数类型槽亦登记**（其引用已由上方"别名 +1 / 转移持有"配平 ⇒
                //   出口 −1 平衡；函数指针的 −1 自动 no-op ⇒ 零副作用）✓ 修复 soak 探针 C 的 +1/轮 ✓
                let 登记拥有 = 目标接口 || 是复合类型(类型) || 是复合类型(&推断初值) || 声明新建 || 文本槽 || 函数槽
                    // 🔁 2026-09-24（**D1 收尾**）：**并发收发/等待类内置返回值** ⇒ 该槽**直接持有**本次
                    //   调用**新建**的对象（`拥有值转运行时值`，计数=1、无别名）⇒ **转移即持有** ✓
                    //   ⚠ 为什么必须在此登记：`收 = 通道甲.接收()` 的**类型推断不出**（通道值为动态）
                    //     ⇒ `文本槽=false`、`是复合类型=false` ⇒ 该槽**不在任何登记路径**上
                    //     ⇒ 帧出口无 −1 ⇒ 每接收一次泄漏 1 个对象 ✗（`115` 的 `文本 204` ✓✓）
                    //   ⚠ 配对方式（按"类型是否可推断"分流，两侧都平衡）：
                    //     · 类型可推断为文本/复合 ⇒ 由 `文本槽`/`需要_实际` 深拷贝路径配平（见上）✓
                    //     · 类型不可推断（本处）⇒ 槽**不做 +1、不深拷贝** ⇒ 槽独占计数=1
                    //       ⇒ 帧出口 −1 恰好归零 ✓✓（这正是"新建值免拷贝 + 登记"的标准配对）✓
                    //   ⚠ 安全性：右值已核实为**本调用新建**（见 `是并发新建返回值` 事实依据）⇒ 无别名 ⇒ 不误回收 ✓
                    || 是并发新建返回值(初始值);
                // 🆕 2026-10-13（**#15 / E 形态**）：标记"本槽当前值直接来自**映射读**"
                //   （映射读已为命中文本 +1，见缺陷C1）⇒ 供 `返回 <裸变量>` 去重使用。
                if 是映射读调用(初始值) || 是映射索引读(初始值) {
                    当前函数映射读局部.with(|s| { s.borrow_mut().insert(名称.clone()); });
                } else {
                    当前函数映射读局部.with(|s| { s.borrow_mut().remove(名称); });
                }
                if 登记拥有 {
                    当前函数待释放局部.with(|s| s.borrow_mut().push((名称.clone(), idx)));
                }
                // 🆕 阶段 6b：登记槽元数据（**只读记录**；`可能拥有` 与上方登记**同源**，仅便于诊断还原名字）
                登记槽元数据(&名称, idx, 槽声明层级::局部变量, format!("{:?}", 类型), 登记拥有);
            }
        }
        高层表示语句::赋值 { 目标, 值 } => {
            // 🆕 2026-10-13（**#15**）：重赋值 ⇒ "本槽当前值来自映射读"的来源标记**失效**
            //   （保守方向：宁可不省那一次 +1（多持有一份 ⇒ 有界泄漏），绝不少计（悬垂））✓
            if let 高层表示表达式::变量引用 { 名称: 目标名, .. } = 目标 {
                当前函数映射读局部.with(|s| { s.borrow_mut().remove(目标名); });
            }
            // 提取目标类型（用于判断接口引用语义：目标为接口型时不深拷贝）
            let 目标类型 = match 目标 {
                高层表示表达式::变量引用 { 类型, .. } => Some(类型.clone()),
                高层表示表达式::字段访问 { 类型, .. } => Some(类型.clone()),
                _ => None,
            };
            let _目标标签 = match 目标 {
                高层表示表达式::变量引用 { 名称, .. } => format!("变量引用({})", 名称),
                高层表示表达式::字段访问 { 对象, 字段名, 字段索引, .. } => {
                    let 对象标签 = match 对象.as_ref() {
                        高层表示表达式::变量引用 { 名称, .. } => format!("变量引用({})", 名称),
                        高层表示表达式::创建结构体 { 结构体名, .. } => format!("创建结构体({})", 结构体名),
                        高层表示表达式::字段访问 { 字段名: f, .. } => format!("字段访问({})", f),
                        _ => "其它对象".into(),
                    };
                    format!("字段访问(对象={}, {}, idx={})", 对象标签, 字段名, 字段索引)
                }
                高层表示表达式::成员访问 { .. } => "成员访问".into(),
                高层表示表达式::创建结构体 { 结构体名, .. } => format!("创建结构体({})", 结构体名),
                _ => "其它".into(),
            };
            let val = 转换表达式(值, 当前块, 块列表, 块编号, 后续块标识, 局部表, 变量映射, 常量池, 结构体布局, 函数索引映射, 结构体类型索引, 函数签名详情, 全局变量名列表, 匿名函数收集);
            // 规范 2.3.7：所有类型的变量赋值都是值复制——复合类型右值需深拷贝，
            // 否则多个变量共享同一堆对象（如 乙=甲 后 乙.追加 影响 甲）。与 190 传值参数一致。
            // 但接口是引用语义：目标为接口型时（含 具体结构体→接口变量 适配），
            // 仅复制指针(句柄)共享同一实现对象，使接口方法就地修改作用于原实例。
            let 目标接口 = 目标类型.as_ref().map(是接口引用类型).unwrap_or(false);
            let 推断类型 = 从表达式推断(值);
            let 需要深拷贝 = !目标接口 && 是复合类型(&推断类型);
            // 🔁 2026-09-22 开关门控的「新建值免拷贝」（同 变量声明 臂；理由与历史根因见该处注释）
            //   ✅ 收窄已解除（字面量元素已在构造处独立副本，见 字面值::数组 分支）
            let 赋值新建值 = matches!(值, 高层表示表达式::创建结构体 { .. }) || 是复合字面量(值);
            // 🔁 2026-09-25（**并发收发/等待类返回值 ⇒ 免拷贝**）★ 同声明臂（依据与账本证据见该处注释）✓
            let 需要深拷贝_实际 = 需要深拷贝
                && !((赋值新建值 || 是并发新建返回值(值)) && base::值类型::帧级释放启用());
            let 源val = val.clone();
            // ⚡按成员身份⚡：含接口成员的复合类型走"逐成员拷贝"，接口成员只复制标签
            let val = 发射深拷贝_类型感知(当前块, 块列表, 块编号, 局部表, val, &推断类型, 需要深拷贝_实际, 结构体类型索引);
            // 🆕 M0.5：复合字面量源临时值就地释放（同上；赋值形态 `目标 = [..]`；免拷贝时不可释放）
            // 🔁 2026-09-23：**用户函数调用结果**同理（同声明臂；`目标 = 造一次(计数)` 形态）✓
            释放字面量源(
                当前块,
                局部表,
                &源val,
                需要深拷贝_实际 && (是复合字面量(值) || 是用户函数调用(值, 函数签名详情)),
            );
            // ⚠【已回退：槽位级「新建值免拷贝」】同 变量声明 臂 —— 实测 8 例门禁回归
            //   （根因：覆盖释放被放宽 + **接口标签不计数** ⇒ `甲 = 新车(); 标签 = 甲; 甲 = 新值` 释放旧值致标签悬垂），
            //   必须与「接口 / `任意<接口>` 真实计数 + 撤闸门②」同批落地。
            // 🔁 2026-09-22③（闸门②细化）：**不再**因"接口赋值"禁用整个函数 ——
            //   接口**变量槽**的新引用已由 `发射增加引用`（+1）与覆盖释放（旧值 −1）配对 ⇒ 其释放是平衡的；
            //   真正危险的是"内含**未计数**接口标签的容器"（结构体成员 / 容器元素），
            //   已由**声明侧按槽排除**（`含接口对象 ⇒ 不登记`）兜住 ✓。
            match 目标 {
                高层表示表达式::变量引用 { 名称, .. } => {
                    // 模块级全局变量：写入独立全局存储（全局变量表索引0保留给异常标志，故 +1 偏移）。
                    // 此前误用 局部变量(idx)，导致写进当前函数自身 frame，跨函数调用修改丢失。
                    // ★§2.4.7：`本模块.X`（模块级访问的限定名，由 解析本模块成员 产出）需**回退裸名**查全局 ——
                    //   全局表以裸名登记；读取侧已有同款回退，此处在**赋值目标**侧补齐（否则 `本模块.X = 值` 会两头落空）。
                    // ★ A3 修复（2026-09-28）：写路径与读路径同口径 —— 别名映射归一后**精确**定位，
                    //   仅保留 `本模块.`（入口专用标记）的确定性折算（见读路径同款注释）。
                    let 归一后写 = {
                        let mut 当前 = 名称.clone();
                        for _ in 0..32 {
                            let 表 = crate::降级::类型转换::展开别名映射
                                .get_or_init(|| std::sync::Mutex::new(std::collections::HashMap::new()))
                                .lock()
                                .unwrap();
                            match 表.get(&当前).cloned() {
                                Some(全名) if 全名 != 当前 => 当前 = 全名,
                                _ => break,
                            }
                        }
                        当前
                    };
                    let 全局位 = 全局变量名列表.iter().position(|n| n == &归一后写)
                        .or_else(|| 归一后写.strip_prefix("本模块.").and_then(|裸| 全局变量名列表.iter().position(|n| n == 裸)));
                    if let Some(gi) = 全局位 {
                        // 🔁 2026-09-24（soak F 修复）：**全局槽覆盖写前释放旧值**（详见 `发射释放全局槽`）。
                        //   门控与局部槽一致：新值为**独立对象**（复合已深拷贝 / 赋值即新建）才释放；
                        //   文本 / 接口 / 函数标签的全局槽无 +1 配平 ⇒ 跳过（保守泄漏，绝不误回收）✓
                        //   （`赋值新建` 在本臂更靠下的局部槽分支内定义、此处不可见 ⇒ 内联同款判定）
                        if 是复合类型(&推断类型)
                            && (需要深拷贝
                                || matches!(值, 高层表示表达式::创建结构体 { .. })
                                || 是复合字面量(值))
                        {
                            发射释放全局槽(当前块, 局部表, gi);
                        }
                        当前块.指令列表.push(三地址码 { 结果:操作数::无, 操作码:操作码::存储, 操作数1:操作数::全局变量(gi + 1), 操作数2:Some(val), 调试位置:None, 操作数3: None, });
                    } else if let Some(&idx) = 变量映射.get(名称) {
                        // 传引用形参赋值：经 间接存储 写回调用方变量（其局部槽位持有 值::局部引用）
                        if 当前函数引用名映射.with(|m| m.borrow().get(名称).copied()) == Some(idx) {
                            当前块.指令列表.push(三地址码 { 结果:操作数::无, 操作码:操作码::间接存储, 操作数1:操作数::局部变量(idx), 操作数2:Some(val), 调试位置:None, 操作数3: None, });
                        } else {
                            // 🆕 S2 覆盖释放：赋值覆盖旧值 ⇒ 先 −1 旧值（循环体重复赋值是内存增长的主要来源）。
                            //    条件：非接口目标、右值与目标类型均不含接口（接口共享无 +1 ⇒ 释放会误回收）。
                            // 🔁 2026-09-22 覆盖释放：① 接口目标**也**允许（其引用已由下方 +1 配平）；
                            //   ② **新建值**（深拷贝被省略 = 移动）时槽同样独占旧值 ⇒ 必须 −1 旧值（治循环泄漏）。
                            let 赋值新建 = matches!(值, 高层表示表达式::创建结构体 { .. }) || 是复合字面量(值);
                            // 🆕 2026-09-22（**阶段 1a**：已登记的**文本槽**参与同一配对）
                            //   声明处已 `+1` ⇒ 覆盖写 `−1` 旧值、弹帧 `−1` 末值 ⇒ 三者平衡（I1/I2）。
                            //   ⚠ 仅对**已登记**槽生效（形参 / 传引用形参 / 模块级全局不登记 ⇒ 保持旧行为）✓
                            let 文本已登记槽 = {
                                let 文本型 = matches!(推断类型, 类型信息::基本型(基本类型::文本))
                                    || matches!(目标类型.as_ref(), Some(类型信息::基本型(基本类型::文本)));
                                文本型 && base::值类型::帧级释放启用()
                                    && 当前函数待释放局部.with(|s| s.borrow().iter().any(|(_, i)| *i == idx))
                            };
                            // 🔁 2026-09-23（**soak 门禁实测缺陷修复**）：**已登记的复合槽一律覆盖释放旧值**。
                            //   原则：**登记即"本槽自持一份引用"** —— 登记只发生在四种来源（深拷贝 / 移动 /
                            //   接口标签 +1 / 文本 +1）⇒ **覆盖写前必须 −1**（I2 配对，与弹帧释放同源）。
                            //   原条件 `是复合类型 && (需要深拷贝 || 赋值新建)` **漏掉"值来自函数/方法调用"**：
                            //   调用结果以**移动**语义进槽（既非深拷贝、也非字面量新建）⇒ 条件全假 ⇒
                            //   循环内 `载体 = 造一次(计数)` **每轮泄漏 1 个根对象 + 其级联子对象** ✗
                            //   实测（soak 探针 A，双引擎数值相同 ⇒ 前端同源）：小N=1000 存活 2007 →
                            //   大N=10000 存活 20007 ⇒ **+2/轮**（V3 换成数组 ⇒ +1/轮 = 仅根对象）✓ 自洽
                            let 复合已登记槽 = 是复合类型(&推断类型)
                                && 当前函数待释放局部.with(|s| s.borrow().iter().any(|(_, i)| *i == idx));
                            // 🔁 2026-09-23（**soak 门禁 C 形状修复**）：**函数类型槽**（闭包环境）同理。
                            //   ⚠ 必须用「**已登记**」作门：形参 / `传引用`形参 / 模块级全局**不登记**
                            //     ⇒ 它们是**借用槽**（不拥有）⇒ 既不 −1 也不 +1（否则过度释放）✗
                            let 函数已登记槽 = {
                                let 函数型 = matches!(推断类型, 类型信息::函数类型(_, _))
                                    || matches!(目标类型.as_ref(), Some(类型信息::函数类型(_, _)));
                                函数型 && base::值类型::帧级释放启用()
                                    && 当前函数待释放局部.with(|s| s.borrow().iter().any(|(_, i)| *i == idx))
                            };
                            // 🔁 2026-09-25（**并发收发/等待类返回值 ⇒ 覆盖释放**）★ 同声明臂：
                            //   `收 = 甲.接收()`（推断类型 `任意类型{}` ⇒ `是复合类型` 为假）在**赋值形态**下
                            //   同样漏覆盖释放 ⇒ 循环内逐轮泄漏收到的堆文本 ✗（实测见声明臂同位注释）✓
                            let 并发新建已登记槽 = 是并发新建返回值(值)
                                && 当前函数待释放局部.with(|s| s.borrow().iter().any(|(_, i)| *i == idx));
                            if 目标接口 || 复合已登记槽 || 函数已登记槽
                                || (是复合类型(&推断类型) && (需要深拷贝 || 赋值新建)) || 文本已登记槽
                                || 并发新建已登记槽 {
                                发射释放槽(当前块, 局部表, idx);
                            }
                            // 🔁 2026-09-22④（阶段三，同声明臂）：接口目标槽的**标签别名一律 +1**
                            //   （含"标签 ← 标签"）。与 `覆盖释放(目标接口 亦允许)` 成对 ⇒ 接口槽计数闭合 ✅
                            // 🔁 2026-09-23：函数槽的**别名 +1**（右值非确定新建 ⇒ 可能是他人闭包别名）✓
                            if (目标接口 && !赋值新建 && !matches!(推断类型, 类型信息::基本型(_))) || 文本已登记槽
                                || (函数已登记槽 && !确定新建闭包(值, 函数签名详情)) {
                                发射增加引用(当前块, 局部表, val.clone());
                            }
                            当前块.指令列表.push(三地址码 { 结果:操作数::无, 操作码:操作码::存储, 操作数1:操作数::局部变量(idx), 操作数2:Some(val.clone()), 调试位置:None, 操作数3: None, });
                            // 🆕 阶段 1a：新建文本源就地 −1（同声明臂；自引用 `s = s` 跳过 ⇒ 不清空本槽）
                            let 源自同槽 = matches!(val, 操作数::局部变量(v) if v == idx);
                            if 文本已登记槽 && 是新建文本表达式(值) && !源自同槽 {
                                释放字面量源(当前块, 局部表, &val, true);
                            }
                        }
                    }
                }
                高层表示表达式::字段访问 { 对象, 字段索引, 位置, .. } => {
                    let obj_op = if let 高层表示表达式::变量引用 { 名称, .. } = 对象.as_ref() {
                        if let Some(&idx) = 变量映射.get(名称) {
                            // ⚡双模式⚡ by-ref 形参：局部槽位持有 值::局部引用 / 引用单元，
                            // 字段存储前须 间接加载 取真实对象（与读取路径 line 406 对称），
                            // 否则会把值写入引用单元/局部引用而非结构体本身（编译模式 by-ref 失效）。
                            if 当前函数引用局部.with(|s| s.borrow().contains(&idx)) {
                                let 解引用 = 局部表.len(); 局部表.push(底层表示类型::整数64);
                                当前块.指令列表.push(三地址码 { 结果:操作数::局部变量(解引用), 操作码:操作码::间接加载, 操作数1:操作数::局部变量(idx), 操作数2:None, 调试位置:None, 操作数3: None });
                                操作数::局部变量(解引用)
                            } else {
                                操作数::局部变量(idx)
                            }
                        } else {
                            转换表达式(对象, 当前块, 块列表, 块编号, 后续块标识, 局部表, 变量映射, 常量池, 结构体布局, 函数索引映射, 结构体类型索引, 函数签名详情, 全局变量名列表, 匿名函数收集)
                        }
                    } else {
                        转换表达式(对象, 当前块, 块列表, 块编号, 后续块标识, 局部表, 变量映射, 常量池, 结构体布局, 函数索引映射, 结构体类型索引, 函数签名详情, 全局变量名列表, 匿名函数收集)
                    };
                    // 🔁 2026-09-22⑧（**字段覆盖写：释放旧字段值**）：结构体对**字段值**持有一份计数
                    //   （base `堆_字段存储` 对写入值 +1）⇒ 覆盖写时**旧值的那份引用必须 −1**，否则旧值
                    //   （尤其接口标签指向的实例 / 复合容器）**永久存活**（实测 `K_泄漏拆分_乙接口字段`：
                    //   `盒.设备 = 车` 每轮泄漏 1 个结构体 —— `箱()` 的默认接口字段旧值从未释放 ✓✓）
                    //   ⚠ 标量字段：`堆_释放引用` 只对 `标签_句柄` 生效 ⇒ 自动跳过，无条件发射安全 ✓
                    //   ⚠ 释放后写空值（"释放即写空值"约定）⇒ 消除陈旧句柄（否则对账报悬垂噪声）。
                    // 🔁 2026-09-22⑧（**字段覆盖写：释放旧字段值** —— **收窄到「接口 / `任意<接口>`」字段**，单项落地）
                    //   依据（配对关系，I1）：**接口字段**由接口赋值路径持有**一份计数引用**
                    //     —— 接口是"标签"语义，字段存的是标签句柄，`字段存储` 对其 +1（与"宿主结构体级联释放 −1"配对）；
                    //     ⇒ 覆盖写时旧标签的这份引用**必须 −1**，否则旧标签指向的实例**永久存活**
                    //     （实测 `K_泄漏拆分_乙接口字段`：`盒.设备 = 车` 每轮泄漏 1 个结构体 —— `箱()` 的默认接口字段
                    //      旧值（`单车(0)`）从未释放 ✓✓）
                    //   ⚠⚠ **为什么只收「接口」、不含「复合（数组/映射/结构体）」**：
                    //     上一轮把"复合"一并纳入时，**单项落地即令 `115内存并发任务通道边界` 双模 FAIL**
                    //     （`无效句柄` = 过度释放）⇒ 实测证伪「复合字段的旧值也被 +1」这一前提
                    //     （并发/任务路径上的复合字段可能持**未计数/借用**句柄）✗
                    //     ⇒ 因此**只对接口字段**释放旧值（接口路径的 +1 已在 `发射增加引用`/`字段存储` 两侧成对 ✓）。
                    //   ⚠ 释放后**写空值**（"释放即写空值"约定）⇒ 消除陈旧句柄（否则对账报悬垂噪声）。
                    let 写入推断 = 从表达式推断(值);
                    // 🔁 2026-09-22⑧补（**判定改为「字段声明类型是接口」**）：仅看**写入值**类型不够 ——
                    //   典型形态 `盒.设备 = 车`（`车` 是**具体结构体**，隐式适配到接口字段）⇒ 写入值推 not 接口型，
                    //   但其**字段声明类型**是接口 ⇒ 该字段仍是"标签语义"（旧标签必须 −1）。
                    //   查 `结构体字段类型表`（按 对象类型 + 字段索引）；查不到（外部/未登记类型）⇒ 保守不释放 ✓
                    let 字段是接口 = match 从表达式推断(对象) {
                        类型信息::结构体(名, _) => {
                            let 裸名 = 名.rsplit('.').next().unwrap_or(名.as_str()).to_string();
                            结构体字段类型表.with(|s| {
                                let 表 = s.borrow();
                                表.get(&名).or_else(|| 表.get(&裸名))
                                    .and_then(|列| 列.get(*字段索引))
                                    .map(|(_, t)| 是接口引用类型(t))
                                    .unwrap_or(false)
                            })
                        }
                        _ => false,
                    };
                    if 字段是接口 || 是接口引用类型(&写入推断) {
                        let 旧 = 局部表.len(); 局部表.push(底层表示类型::整数64);
                        当前块.指令列表.push(三地址码 { 结果: 操作数::局部变量(旧), 操作码: 操作码::字段加载, 操作数1: obj_op.clone(), 操作数2: Some(操作数::立即整数(*字段索引 as i64 + 1)), 调试位置: None, 操作数3: None });
                        发射释放槽(当前块, 局部表, 旧);
                        当前块.指令列表.push(三地址码 { 结果: 操作数::无, 操作码: 操作码::存储, 操作数1: 操作数::局部变量(旧), 操作数2: Some(操作数::立即空值), 调试位置: None, 操作数3: None });
                    }
                    当前块.指令列表.push(三地址码 { 结果:obj_op.clone(), 操作码:操作码::字段存储, 操作数1:obj_op, 操作数2:Some(操作数::立即整数(*字段索引 as i64 + 1)), 调试位置:Some(位置.clone()), 操作数3: Some(val.clone()) });
                    // ⚡RC 平衡（2026-09-21）⚡ base `堆_字段存储` 对**写入值**做 +1（字段获得一份引用），
                    //   而本语句另持有一份「深拷贝产生的新临时值」（`需要深拷贝` 时 val 必为全新临时）⇒
                    //   必须在此 −1，否则该对象计数**永久虚高 1** ⇒ 下一次写入（如 `甲.车.移动(x)` 内
                    //   `自身.速度 = …`）会触发 `堆_写入前复制` 的 COW 分离：修改落到新副本，而字段仍指旧对象
                    //   ⇒ 变异丢失（实测 `甲.车 = 单车(100); 甲.车.移动(83)` 读回 100 而非 83，双模一致）。
                    //   仅释放**深拷贝产生的临时值**（本次新建、无别名 ⇒ 安全）；非深拷贝路径（标量/接口引用）不动。
                    if 需要深拷贝 { 释放字面量源(当前块, 局部表, &val, true); }
                    // 🔁 2026-09-22 精确补齐（**第二次尝试**，上次用 `需要深拷贝` 作门控 ⇒ 免拷贝路径上
                    //   同一操作数被 −1 两次 ⇒ 12 例双模回归 ✗）：
                    //   字段/容器存储的 base 实现对**写入值** +1 ⇒ 本语句另持有的「**源新建临时**」须 −1，
                    //   否则 `自身.字段 = []`（**结构体复合类型默认字段**的构造路径）每轮泄漏 1 个容器
                    //   （实测 G 探针：500 轮 ⇒ 不可达 501 ✗；对照 F（纯标量字段）⇒ 2 ✓）。
                    //   ⚠ 门控必须是 `需要深拷贝_实际`：免拷贝（转移）时 `val == 源val`，上面那行已 −1 一次，
                    //     此处再 −1 即重复释放 ✗。
                    if 需要深拷贝_实际 && 是新建值(值) { 释放字面量源(当前块, 局部表, &源val, true); }
                    // ⚠【已回退 2026-09-22】曾在此补齐「**字面量源临时** −1」（治 `自身.字段 = []` 每轮泄漏），
                    //   但实测 **12 例双模回归**（79值引用传递 / 总泛型验证 / 总任意类型 等）⇒ **已撤销**。
                    //   保留的发现（下批用最小探针定位真因）：
                    //     · `114内存基线千轮循环创建` 存活 1019（≈1 对象/轮）：**结构体默认字段为复合类型**时逐轮泄漏 ✗；
                    //     · `F_循环新建泄漏_取证`（无复合默认字段）仅 2 ⇒ 泄漏点与该路径强相关。
                }
                // 嵌套容器左值（如 外层["层1"]["内"] = 值 / 列表[0] = 值）：HIR 表示为 调用{映射加载|数组加载}，
                // 委托 发射字段接收者写回 统一写回（映射_store/数组_store），治嵌套映射/数组就地写回缺口。
                // 单源（2026-08-30）：容器加载判定由 标准库元数据表 的 是容器加载 标记派生
                高层表示表达式::调用 { 函数名, .. } if crate::标准库元数据::是容器加载调用(函数名) => {
                    发射字段接收者写回(目标, val.clone(), 当前块, 块列表, 块编号, 后续块标识, 局部表, 变量映射, 常量池, 结构体布局, 函数索引映射, 结构体类型索引, 函数签名详情, 全局变量名列表, 匿名函数收集);
                    // ⚡RC 平衡（2026-09-21）⚡ 容器元素存储（`列表[i] = 值` / `映射[键] = 值`）的 base 实现
                    //   同样对**写入值** +1（容器元素获得一份引用）。本语句另持有的「深拷贝临时值」须 −1，
                    //   否则计数虚高 ⇒ 后续 `列表[i].变异方法()` 触发 COW 分离而丢失修改（实测 85→4）。
                    if 需要深拷贝 { 释放字面量源(当前块, 局部表, &val, true); }
                    // 🔁 2026-09-22 精确补齐（**第二次尝试**，上次用 `需要深拷贝` 作门控 ⇒ 免拷贝路径上
                    //   同一操作数被 −1 两次 ⇒ 12 例双模回归 ✗）：
                    //   字段/容器存储的 base 实现对**写入值** +1 ⇒ 本语句另持有的「**源新建临时**」须 −1，
                    //   否则 `自身.字段 = []`（**结构体复合类型默认字段**的构造路径）每轮泄漏 1 个容器
                    //   （实测 G 探针：500 轮 ⇒ 不可达 501 ✗；对照 F（纯标量字段）⇒ 2 ✓）。
                    //   ⚠ 门控必须是 `需要深拷贝_实际`：免拷贝（转移）时 `val == 源val`，上面那行已 −1 一次，
                    //     此处再 −1 即重复释放 ✗。
                    if 需要深拷贝_实际 && 是新建值(值) { 释放字面量源(当前块, 局部表, &源val, true); }
                    // 🔁 2026-09-22 同上：**字面量源临时**亦须 −1（否则 `列表[i] = []` 每轮泄漏 1 个）
                    //   ⚠ 必须与「已发生深拷贝」同门控：未深拷贝时源临时是**转移**给字段/容器的持有者
                    //     ⇒ 释放它 = 误回收刚转移的对象（实测：漏此门控致 12 例双模回归）
                    if 需要深拷贝 { 释放字面量源(当前块, 局部表, &源val, 是复合字面量(值)); }
                }
                _ => {}
            }
        }
        高层表示语句::条件语句 { 分支列表, 否则分支 } => {
            if 分支列表.is_empty() { return; }
            // 🆕 引用计数闸门：出现分支 ⇒ 本函数不发射释放（分支内声明的槽在部分返回路径上未赋值）
            当前函数含嵌套控制流.with(|f| *f.borrow_mut() = true);
            let 结束块标识 = *块编号; *块编号 += 1;
            let 否则块标识 = if 否则分支.is_some() { let id = *块编号; *块编号 += 1; id } else { 结束块标识 };
            let mut 所有分支块标识 = Vec::new(); let mut 所有条件操作数 = Vec::new();
            for (条件, _) in 分支列表.iter() {
                当前条件可释放临时.with(|s| s.borrow_mut().clear());
                let 条件操作数 = 转换表达式(条件, 当前块, 块列表, 块编号, 后续块标识, 局部表, 变量映射, 常量池, 结构体布局, 函数索引映射, 结构体类型索引, 函数签名详情, 全局变量名列表, 匿名函数收集);
                所有条件操作数.push(条件操作数);
                // 🆕 2026-10-13（**#13 收窄版**）：条件求值结束 ⇒ 释放登记的**文本返回**调用结果计数
                释放条件可释放临时(当前块, 局部表);
                let 分支块标识 = *块编号; *块编号 += 1; 所有分支块标识.push(分支块标识);
            }
            for (i, (_, 体)) in 分支列表.iter().enumerate() {
                let 分支块标识 = 所有分支块标识[i];
                let _下一个 = if i + 1 < 分支列表.len() { 所有分支块标识[i + 1] } else { 否则块标识 };
                let mut 分支体块 = 基本块 { 异常目标: 取当前异常目标(), 标识符: 分支块标识, 指令列表: vec![], 终止指令: 终止指令::无条件跳转(结束块标识) };
                // 🆕 分支体作用域：进入时快照、退出时恢复 ⇒ 分支内新声明的名字在分支外不可见；
                //   分支内同名显式声明（遮蔽）在分支外恢复外层绑定。
                let 分支外层映射 = 变量映射.clone();
                for s in 体 { 转换语句(s, &mut 分支体块, 块列表, 块编号, 局部表, 变量映射, 常量池, 结构体布局, 函数索引映射, 结构体类型索引, 函数签名详情, 全局变量名列表, 匿名函数收集, 结束块标识); }
                *变量映射 = 分支外层映射;
                if !matches!(分支体块.终止指令, 终止指令::无条件跳转(_) | 终止指令::返回(_)) { 分支体块.终止指令 = 终止指令::无条件跳转(结束块标识); }
                块列表.push(分支体块);
            }
            if let Some(否则体) = 否则分支 {
                let mut 否则基本块 = 基本块 { 异常目标: 取当前异常目标(), 标识符: 否则块标识, 指令列表: vec![], 终止指令: 终止指令::无条件跳转(结束块标识) };
                // 🆕 否则体作用域：同分支体
                let 否则外层映射 = 变量映射.clone();
                for s in 否则体 { 转换语句(s, &mut 否则基本块, 块列表, 块编号, 局部表, 变量映射, 常量池, 结构体布局, 函数索引映射, 结构体类型索引, 函数签名详情, 全局变量名列表, 匿名函数收集, 结束块标识); }
                *变量映射 = 否则外层映射;
                if !matches!(否则基本块.终止指令, 终止指令::无条件跳转(_) | 终止指令::返回(_)) { 否则基本块.终止指令 = 终止指令::无条件跳转(结束块标识); }
                块列表.push(否则基本块);
            }
            // ⚠️⚡双模式⚡: 必须显式捕获「首个条件块」的标识符。
            // 此前用 `块编号 - 条件数` 反推，但 后续块标识 在下方 line 447 先占用了 块编号，
            // 导致反推值比真实首个条件块大 1 —— 入口块被错误跳转到「后续块」，
            // 整个 如果 分支块（含 条件跳转）成为不可达死代码。这会让 如果/否则
            // 在解释模式与编译模式双双失效（永远走跳过分支）。现改为在生成首个条件块时直接记录。
            let mut 首个条件块标识: Option<usize> = None;
            for i in 0..所有条件操作数.len() {
                let 条件块标识 = *块编号; *块编号 += 1;
                if i == 0 { 首个条件块标识 = Some(条件块标识); }
                let 真分支 = 所有分支块标识[i];
                let 假分支 = if i + 1 < 所有分支块标识.len() { *块编号 } else { 否则块标识 };
                let 条件基本块 = 基本块 { 异常目标: 取当前异常目标(), 标识符: 条件块标识, 指令列表: vec![], 终止指令: 终止指令::条件跳转 { 条件: 所有条件操作数[i].clone(), 真分支, 假分支 } };
                块列表.push(条件基本块);
            }
            let 续延块标识 = *块编号; *块编号 += 1;
            let 结束基本块 = 基本块 { 异常目标: 取当前异常目标(), 标识符: 结束块标识, 指令列表: vec![], 终止指令: 终止指令::无条件跳转(续延块标识) };
            块列表.push(结束基本块);
            let 第一个条件块 = 首个条件块标识.unwrap_or(结束块标识);
            当前块.终止指令 = 终止指令::无条件跳转(第一个条件块);
            块列表.push(std::mem::replace(当前块, 基本块 { 异常目标: 取当前异常目标(), 标识符: 续延块标识, 指令列表: vec![], 终止指令: if 后续块标识 == usize::MAX { 终止指令::返回(None) } else { 终止指令::无条件跳转(后续块标识) } }));
        }
        高层表示语句::循环语句 { 条件, 循环体, 步进 } => {
            let 条件块 = *块编号; *块编号 += 1; let 体块 = *块编号; *块编号 += 1; let 结束块 = *块编号; *块编号 += 1;
            let 后续块 = *块编号; *块编号 += 1;
            let 步进块标识 = if 步进.is_some() { let id = *块编号; *块编号 += 1; Some(id) } else { None };
            let 继续目标 = 步进块标识.unwrap_or(条件块);
            // 「始终」出口完备化：记录进入循环时的始终层数，供 跳出/继续 计算需穿越的始终层数。
            let 入循环层数 = 始终层栈.with(|s| s.borrow().len());
            let mut 条件基本块 = 基本块 { 异常目标: 取当前异常目标(), 标识符: 条件块, 指令列表: vec![], 终止指令: 终止指令::条件跳转 { 条件:操作数::无, 真分支:体块, 假分支:结束块 } };
            let cond_op = 转换表达式(条件, &mut 条件基本块, 块列表, 块编号, 后续块标识, 局部表, 变量映射, 常量池, 结构体布局, 函数索引映射, 结构体类型索引, 函数签名详情, 全局变量名列表, 匿名函数收集);
            条件基本块.终止指令 = 终止指令::条件跳转 { 条件: cond_op, 真分支: 体块, 假分支: 结束块 };
            let mut 体基本块 = 基本块 { 异常目标: 取当前异常目标(), 标识符: 体块, 指令列表: vec![], 终止指令: 终止指令::无条件跳转(继续目标) };
            // 🆕 引用计数闸门：出现循环 ⇒ 本函数不发射释放（循环体内声明的槽可能未赋值/已跨迭代覆盖）
            当前函数含嵌套控制流.with(|f| *f.borrow_mut() = true);
            // 本层循环入栈（规范 §2.5.3：跳出/继续 的目标 = 最内层循环）。
            // ⚠ 唯一入口：push 在 循环体/步进 转换之前、pop 在其后；其它地方不得直接 push/pop。
            循环栈.with(|s| s.borrow_mut().push(循环层 { 继续目标, 结束块, 入循环始终层数: 入循环层数 }));
            // 🆕 循环体作用域：进入时快照、退出时恢复 ⇒ 循环体内新声明的名字在循环外不可见。
            //   注意：循环变量本身由**反糖的 `语句序列`**在当前作用域声明（在循环体之外）⇒ 不受此处恢复影响，
            //   这正是本轮把反糖容器从 `代码块` 改为 `语句序列` 的原因（否则循环外引用会取到垃圾占位值）。
            let 体外层映射 = 变量映射.clone();
            for s in 循环体 { 转换语句(s, &mut 体基本块, 块列表, 块编号, 局部表, 变量映射, 常量池, 结构体布局, 函数索引映射, 结构体类型索引, 函数签名详情, 全局变量名列表, 匿名函数收集, 继续目标); }
            *变量映射 = 体外层映射;
            if !matches!(体基本块.终止指令, 终止指令::无条件跳转(_)) { 体基本块.终止指令 = 终止指令::无条件跳转(继续目标); }
            块列表.push(体基本块);
            if let Some(步进语句) = 步进 {
                let mut 步进块基本块 = 基本块 { 异常目标: 取当前异常目标(), 标识符: 步进块标识.unwrap(), 指令列表: vec![], 终止指令: 终止指令::无条件跳转(条件块) };
                转换语句(&*步进语句, &mut 步进块基本块, 块列表, 块编号, 局部表, 变量映射, 常量池, 结构体布局, 函数索引映射, 结构体类型索引, 函数签名详情, 全局变量名列表, 匿名函数收集, 继续目标);
                if !matches!(步进块基本块.终止指令, 终止指令::无条件跳转(_)) { 步进块基本块.终止指令 = 终止指令::无条件跳转(条件块); }
                块列表.push(步进块基本块);
            }
            循环栈.with(|s| { s.borrow_mut().pop(); });
            let 结束基本块 = 基本块 { 异常目标: 取当前异常目标(), 标识符: 结束块, 指令列表: vec![], 终止指令: 终止指令::无条件跳转(后续块) };
            块列表.push(条件基本块); 块列表.push(结束基本块);
            当前块.终止指令 = 终止指令::无条件跳转(条件块);
            块列表.push(std::mem::replace(当前块, 基本块 { 异常目标: 取当前异常目标(), 标识符: 后续块, 指令列表: vec![], 终止指令: if 后续块标识 == usize::MAX { 终止指令::返回(None) } else { 终止指令::无条件跳转(后续块标识) } }));
        }
        高层表示语句::跳出语句(_) => {
            if let Some(层) = 取最内循环层() {
                // 「始终」出口完备化：目标循环之外还夹着始终层时，先跑完始终再跳出。
                let 本层数 = 始终层栈.with(|s| s.borrow().len());
                if 本层数 > 层.入循环始终层数 && 发射非局部退出(当前块, 本层数 - 层.入循环始终层数, 层.结束块) {
                    // 终止指令已改写（先跑始终链，再跳结束块）
                } else {
                    当前块.终止指令 = 终止指令::无条件跳转(层.结束块);
                }
            } else {
                // 🔒 不变量：语法层已保证 跳出/继续 必有外层循环（见 解析语句 的 在循环体内 校验）。
                //    到此仍缺循环层 = 校验层被绕过（编译器内部缺陷）→ 开发期立即炸；
                //    发布期退化为「终止当前函数」，确保结果是确定的 —— 绝不静默继续执行
                //    （静默 = 循环不退出 / 后续语句继续跑 / `循环 真:` 死循环）。
                debug_assert!(false, "跳出 无外层循环：语法层出口校验不变量被破坏");
                当前块.终止指令 = 终止指令::返回(None);
            }
        }
        高层表示语句::继续语句(_) => {
            if let Some(层) = 取最内循环层() {
                let 本层数 = 始终层栈.with(|s| s.borrow().len());
                if 本层数 > 层.入循环始终层数 && 发射非局部退出(当前块, 本层数 - 层.入循环始终层数, 层.继续目标) {
                    // 终止指令已改写（先跑始终链，再跳继续目标）
                } else {
                    当前块.终止指令 = 终止指令::无条件跳转(层.继续目标);
                }
            } else {
                debug_assert!(false, "继续 无外层循环：语法层出口校验不变量被破坏");
                当前块.终止指令 = 终止指令::返回(None);
            }
        }
        高层表示语句::返回语句(Some(e)) => {
            let val = 转换表达式(e, 当前块, 块列表, 块编号, 后续块标识, 局部表, 变量映射, 常量池, 结构体布局, 函数索引映射, 结构体类型索引, 函数签名详情, 全局变量名列表, 匿名函数收集);
            // 🆕 引用计数（move 语义）：`返回 名称` 把该局部整体移出 ⇒ 该槽不得在出口释放（所有权交给调用方）。
            //    🔁 2026-09-22 **帧级释放关键修正**：其余表达式**不再"清空整张清单 + 置闸门①"**。
            //    —— 旧行为的后果（实测铁证）：
            //       `当前函数待释放局部` 同时是「拥有型槽索引」的**唯一来源**，一旦被 `clear()`，
            //       **该函数的弹帧批量释放完全失效** ⇒ 系统性泄漏：
            //         · `I_弹帧释放探针`：被调函数内创建复合局部 200 次 ⇒ 存活 **405**（对照：入口内创建 200 次 ⇒ 8）
            //         · 前端 dump：`造一次`（局部表 16）拥有型槽 = **[]**（连"含循环"的也一律为空）
            //       根因即本分支：`返回 临时.编号` 这类**投影返回**（字段/索引/方法/调用…）一律清空清单。
            //    —— 新行为（精确、两侧守恒）：
            //       ① 裸变量 ⇒ 记 `已移出`（move：所有权交给调用方，该槽不释放）；
            //       ② 其余表达式 ⇒ 先对返回值 `增加引用`（**为调用方计数一份**）：
            //          投影返回（`甲.字段`/`甲[下标]`/成员/枚举成员…）的句柄可能与某个**拥有型槽对象同体**，
            //          调用方持有一份计数后，弹帧释放再 −1 各拥有型槽即**两侧守恒**
            //          （子对象由调用方持有 ✓、容器被回收 ✓）；标量值 `增加引用` 为 no-op ✓ 无副作用；
            //       ③ **不置闸门①** ⇒ 清单得以保留（这是让 L1 弹帧释放真正生效的关键）。
            //    —— 安全边界（未放宽）：含**嵌套控制流 / 接口用法 / 本函数创建闭包**的函数，
            //       仍由 `函数转换.rs` 的 `可释放` 闸门把清单**置空** ⇒ 宁可泄漏、绝不误回收。
            match e {
                高层表示表达式::变量引用 { 名称, .. } => {
                    当前函数已移出名称.with(|s| { s.borrow_mut().insert(名称.clone()); });
                    // 🔁 2026-09-24（**`返回 <值传递形参>` 过度释放修复**）★
                    //   值传递形参 = callee 的**自有副本**；`返回 原` 把该副本交给调用方，
                    //   但实测该对象在返回前后**仍被释放**（原因未逐行定位，双模一致）⇒ 调用方悬垂 ✗
                    //   ⇒ 依铁律「宁可泄漏，绝不误回收」：此处**为调用方 +1**（与"投影返回 +1"同构 ✓）。
                    //   · 标量/空值：`增加引用` 本就是 no-op ⇒ 无副作用 ✓
                    //   · `传引用` 形参：**不属于**集合 ⇒ 不收（借用别名，实测本已正常 ✓）
                    //   · 代价：若该副本实际未被释放 ⇒ 每调用一次**泄漏 1**（保守，安全方向）✓
                    // 🆕 2026-10-12 **缺陷B 补修**：`返回 <裸变量>` 的 +1 从「仅值传递形参」
                    //   推广到「**任何非标量变量**」。证据（探针26 B12，双模一致）：
                    //     `局部 = 地.获取(键); 返回 局部` ⇒ 调用方仍拿到**无效句柄**。
                    //   局部槽虽记 `已移出`（本函数不再 −1），但该对象仍被释放一次（源容器/参数副本侧）
                    //   ⇒ 与 2026-09-24「值传递形参返回仍被释放」是同一现象，同一处置。
                    //   标量（整数/小数/逻辑/空值）纯值不携句柄 ⇒ 跳过（`增加引用` 本就是 no-op）。
                    let 推断名称 = 从表达式推断(e);
                    let 名称标量 = matches!(
                        &推断名称,
                        类型信息::基本型(基本类型::整数)
                            | 类型信息::基本型(基本类型::小数)
                            | 类型信息::基本型(基本类型::逻辑)
                            | 类型信息::空值
                    );
                    // 🆕 2026-10-13（**#15 / E 形态**，与 #13 同构）：该裸变量的值**直接来自映射读**
                    //   ⇒ 读取处那份 +1（缺陷C1）**已经是调用方的那份计数** ⇒ 此处不再重复 +1。
                    //   ⚠ 仅限文本（`当前函数返回文本()`）：复合类型读取处不会 +1 ⇒ 去重即误回收（272 反例）。
                    //   ⚠ 来源标记在**赋值语句**处一律失效 ⇒ 只有"声明即读、未被重赋值"才去重 ✓
                    let 映射读来源 = 当前函数返回文本()
                        && 当前函数映射读局部.with(|s| s.borrow().contains(名称));
                    // 🆕 2026-10-13（**#18 泄漏②**，账本实证）：返回**拥有型槽**（`当前函数待释放局部` 内）
                    //   时**不再重复 +1** —— 恢复本分支 1413-1414 的"**move**"原意：
                    //   该槽**持有自有计数**（`+1` 或**深拷贝独立对象**，如 `任意 盒.获取(键)` 因
                    //   `推断初值=任意类型` 走深拷贝 ⇒ 槽自有 1 份），`已移出` 即把这份**移交给调用方**
                    //   ⇒ 再加一份就是**双重计数** ⇒ 调用方只 −1 一次 ⇒ 每调用泄漏 1。
                    //   ⚠ 保守边界**不变**：**非**拥有型槽（借用值，如 #15 的 `未推断` 映射读局部）
                    //     槽本身**没有**自有计数 ⇒ 此处 +1 是调用方唯一保护 ⇒ **照旧 +1**（缺陷B 原意）✓
                    //   ⚠ 形参不在此列（`当前函数待释放局部` 只收**声明的局部**）⇒ 值传递形参返回
                    //     仍按缺陷B 补修 +1（原缺陷不复现）✓
                    let 拥有型槽 = 当前函数待释放局部
                        .with(|s| s.borrow().iter().any(|(n, _)| n == 名称));
                    if !名称标量 && !映射读来源 && !拥有型槽 {
                        发射增加引用(当前块, 局部表, val.clone());
                    }
                }
                _ => {
                    // ② 仅为**可能携句柄**的返回值计数，且**该计数必须能被配平**：
                    //    · 标量返回（整数/小数/逻辑/空值）⇒ `增加引用` 本就是 no-op，且**不应**阻拦
                    //      弹帧释放（`返回 临时.编号` 这类正是泄漏主源：探针 405 → 6 的关键）；
                    //    · 本函数已被闸门判"不释放"（或清单为空）⇒ 计数无人配平 ⇒ 跳过（避免幽灵计数）。
                    let 推断 = 从表达式推断(e);
                    // 标量判定：整数/小数/逻辑/空值 ⇒ 纯值、不携句柄 ⇒ 跳过（`增加引用` 本就是 no-op，
                    //   跳过更关键的是**不阻拦弹帧释放** —— `返回 临时.编号` 正是泄漏主源）。
                    // ⚠ **文本例外**：文本是**堆对象**，可能被容器元素/结构体字段**借用**（非复合类型不深拷贝）
                    //   ⇒ 若投影返回文本而不计数，父对象被弹帧释放后调用方句柄会**悬垂** ⇒ 归入"需计数"。
                    let 标量返回 = match &推断 {
                        类型信息::基本型(基本类型::文本) => false,
                        类型信息::基本型(_) => true,
                        _ => false,
                    };
                    // 🆕 2026-10-13（**#13 收窄版**）：映射读值已在**读取处** +1（缺陷C1，仅文本）
                    //   ⇒ 若本函数返回文本，则此处**不再重复计数**（移动语义；由调用方条件边界 −1 配平）。
                    //   ⚠ 仅限文本：复合类型读取处不会 +1 ⇒ 去重即误回收（272 红灯反例）。
                    // 🆕 2026-10-13（**索引形态**）：`返回 地[键]` 与"接收者静态类型是映射"的索引读
                    //   同样已由读取处 +1（C1 的映射分支）⇒ 一并去重（判据见 `是映射索引读`）。
                    if !标量返回
                        && !((是映射读调用(e) || 是映射索引读(e)) && 当前函数返回文本())
                    {
                        发射增加引用(当前块, 局部表, val.clone());
                    }
                }
            }
            // 「始终」出口完备化：处于始终链内时先把返回值暂存 + 登记待办 → 跑完整条始终链
            // → 由「统一返回块」执行真正的 返回（等价 Java finally）。
            let 层数 = 始终层栈.with(|s| s.borrow().len());
            if 层数 > 0 {
                // 始终体内 `返回` 覆盖待传播异常（其余位置本已为 0，复位无害）。
                复位重抛标志以取消异常(当前块);
                let 推断 = 从表达式推断(e);
                let 槽类型 = match 推断 {
                    类型信息::未推断 | 类型信息::推断错误 => 底层表示类型::整数64,
                    t => 转换类型(&t),
                };
                let 暂存 = 确保返回暂存槽(局部表, 槽类型);
                当前块.指令列表.push(三地址码 { 结果:操作数::无, 操作码:操作码::存储, 操作数1:操作数::局部变量(暂存), 操作数2:Some(val.clone()), 调试位置:None, 操作数3: None, });
                let 统一返回块 = 当前函数退出槽.with(|s| s.borrow().as_ref().map(|c| c.统一返回块).unwrap_or(usize::MAX));
                if 统一返回块 != usize::MAX && 发射非局部退出(当前块, 层数, 统一返回块) {
                    return;
                }
            }
            当前块.终止指令 = 终止指令::返回(Some(val));
        }
        高层表示语句::返回语句(None) => {
            // 「始终」出口完备化：处于始终链内时改走待办退出（跑完整条始终链后由落点块生效）。
            // ⚠ 旧实现把 返回(None) 归一成「跳始终块」，导致裸返回只跑 finally 而【不再返回】——
            //   本机制修正该缺陷（裸返回同样纳入待办，最终由统一裸返回块执行 返回）。
            //
            // 【初始化方法特判已移除（2026-09-21 · A2 收口）】此前初始化方法内 `返回`（无值）被改写为
            //   「返回 自身」，以规避"用户写的 返回 跳过语义层合成的 `返回 自身` 使实例被置空值"。
            //   现 初始化 = 普通方法、**无返回值**（实例由创建表达式产出，构造处不从其返回值取句柄）
            //   ⇒ 无值 `返回` 就是无值返回，与其他函数**完全同源**，不再需要任何特判。
            let 层数 = 始终层栈.with(|s| s.borrow().len());
            if 层数 > 0 {
                复位重抛标志以取消异常(当前块);
                let 裸返回块 = 当前函数退出槽.with(|s| s.borrow().as_ref().map(|c| c.统一裸返回块).unwrap_or(usize::MAX));
                if 裸返回块 != usize::MAX && 发射非局部退出(当前块, 层数, 裸返回块) {
                    return;
                }
            }
            当前块.终止指令 = 终止指令::返回(None);
        }
        高层表示语句::代码块(语句列表) => {
            // 🆕 引用计数闸门：出现独立代码块 ⇒ 本函数不发射释放（块内声明的槽可能未赋值）
            当前函数含嵌套控制流.with(|f| *f.borrow_mut() = true);
            // 🆕 块作用域（局部快照实现，无需 thread_local 栈）：
            //   进入时快照外层映射，块退出后恢复 ⇒ ① 块内新声明的名字在块外不可见；
            //   ② 块内同名显式声明（遮蔽）在块外恢复外层绑定（P2 目标）。
            //   注意：`return` 只出现在本 match 的其它分支，本分支 for 之后无早退 ⇒ 恢复必然执行。
            let 外层映射 = 变量映射.clone();
            for s in 语句列表 {
                转换语句(s, 当前块, 块列表, 块编号, 局部表, 变量映射, 常量池, 结构体布局, 函数索引映射, 结构体类型索引, 函数签名详情, 全局变量名列表, 匿名函数收集, 后续块标识);
            }
            *变量映射 = 外层映射;
        }
        高层表示语句::语句序列(语句列表) => {
            // 🆕 **纯容器**（语义层反糖打包用，如 `循环 计数 = 1..N` / `遍历`）：**不引入作用域** ⇒
            //   只顺序转换，**不做映射快照/恢复**。反糖产生的循环/遍历变量声明必须留在当前作用域，
            //   否则循环外的引用会取到垃圾占位值（实测铁证：`计数=函数#-65536`）。
            for s in 语句列表 {
                转换语句(s, 当前块, 块列表, 块编号, 局部表, 变量映射, 常量池, 结构体布局, 函数索引映射, 结构体类型索引, 函数签名详情, 全局变量名列表, 匿名函数收集, 后续块标识);
            }
        }
        // ════════════════════════════════════════════════════════════════════════
        // ⚡方案B（2026-09-04）异常语义契约（前端单源，双后端机械消费）
        // 本前端把「捕获/异常/始终」语义完整编码进 LIR 显式控制流，双后端只消费、不重造：
        //   1) 每个基本块携带静态 `异常目标`（危险区→捕获(异常处理块)、异常区→收尾(本层始终块)、
        //      始终区/传播区/续延区→外层目标或无）——异常派发决策由此单源（字节码异常表段 / 编译器静态跳转）。
        //   2) 抛出 / 传播异常: 置「待处理异常」标志（VM=异常激活 / 编译器=base 待处理）后按块静态目标派发。
        //      二者派发语义完全相同，仅语义差别：抛出=发起新异常；传播异常=续抛既有异常（重抛）。
        //   3) finally 流（前端发射，权威）: 危险块→(异常则跳 catch)→catch→始终块→查询重抛标志
        //      →为 1 则跳 传播块(置位重抛标志) 否则跳 续延块。★每层 catch 入口【必须】复位重抛标志(复位重抛标志 opcode)。
        //   4) 派发规则（双后端一致，真相源 = base 双信号）：
        //      捕获=跳 catch/stub（入口 复位重抛标志 吞 / 置位重抛标志 传播）+保留载荷；
        //      收尾=置位重抛标志（两模同调 base 智语言_设置待重抛 + 智语言_清除待处理：真实异常转入
        //           「待重抛」，防 finally 体内调用注入检查误拦——X2 截断根因）+跳始终块；
        //      无=退帧/早返回（跨函数由调用点所在块静态目标接管）。
        //      ★异常状态单源(方案C2/C2.1): 原「全局变量(0) 内存格副本」通道已废除，改用专用 opcode
        //       查询/复位/置位重抛标志——base 双信号职责分离（待处理=真实异常注入检查 / 待重抛=finally
        //       外传判定，不可合并），两模直调 base 同一函数，消除解释/编译双载体分歧(X1/X2A 根因)。
        //   5) 历史双运行时状态机（VM 当前finally块/异常处理栈、base 智语言_派发异常 栈）已删除；
        //      双执行载体差异（VM 查表 vs 编译器静态生成）仍存在，但决策数据单源 = 本标注。
        // ════════════════════════════════════════════════════════════════════════
        高层表示语句::异常控制 { 危险块, 异常块, 始终块, 存在异常块 } => {
            let 捕获块标识 = *块编号; *块编号 += 1;
            let 异常处理块标识 = *块编号; *块编号 += 1;
            let 始终块标识 = *块编号; *块编号 += 1;
            let 传播块标识 = *块编号; *块编号 += 1;
            let 续延块标识 = *块编号; *块编号 += 1;
            // 「始终」出口完备化：本层非局部退出派发块（点表非空时才实体化）+ 本层「待办站点」隐藏槽
            let 派发块标识 = *块编号; *块编号 += 1;
            let 本层站点槽 = 局部表.len(); 局部表.push(底层表示类型::整数64);
            let 危险块前块数 = 块列表.len();
            // 「始终」出口完备化：入栈本层（危险/异常区内的非局部退出需穿越本层始终）。
            // 始终体降级前会先弹栈 —— 故始终体内的非局部退出走的是「外层链」（不会重复穿越本层）。
            始终层栈.with(|s| s.borrow_mut().push(始终层 { 始终块: 始终块标识, 站点槽: 本层站点槽, 点表: Vec::new() }));
            // 🆕 方案B S4：不再发射 设置异常处理（异常派发已静态化：块 异常目标 → 字节码异常表段）。
            let 外层异常目标 = 取当前异常目标();
            压当前异常目标(异常目标::捕获(异常处理块标识));
            // 捕获块：危险区首块（复位重抛标志；handler 由 异常目标 静态承担）
            // 🆕 方案C2：复位 由显式 opcode 承担（两模同一 base 函数），不再借道 全局变量(0) 伪变量。
            // 「始终」出口完备化：危险块入口同时清本层待办站点（同一异常控制在循环内被反复进入时不残留旧站点）。
            let mut 危险基本块 = 基本块 { 异常目标: 取当前异常目标(), 标识符: 捕获块标识, 指令列表: vec![
                三地址码 { 结果:操作数::无, 操作码:操作码::复位重抛标志, 操作数1:操作数::无, 操作数2:None, 操作数3:None, 调试位置:None },
                三地址码 { 结果:操作数::无, 操作码:操作码::存储, 操作数1:操作数::局部变量(本层站点槽), 操作数2:Some(操作数::立即整数(0)), 调试位置:None, 操作数3:None },
            ], 终止指令: 终止指令::无条件跳转(始终块标识) };
            // 🆕 异常控制**整体**一个作用域（危险/异常/始终 三段**共享**，不得各自为作用域）：
            //   依据：「危险块中声明的资源、始终块中释放」是常见且正确的用法 ⇒ 若三段各自恢复，
            //   始终块会找不到危险块声明的名字。⇒ 仅在此处进入前快照、三段转换完后统一恢复。
            let 异常控制外层映射 = 变量映射.clone();
            for s in 危险块 {
                转换语句(s, &mut 危险基本块, 块列表, 块编号, 局部表, 变量映射, 常量池, 结构体布局, 函数索引映射, 结构体类型索引, 函数签名详情, 全局变量名列表, 匿名函数收集, 始终块标识);
            }
            // 🆕 方案B S4：不再发射 弹出异常处理（无动态注册栈可弹）；危险块成功路径直接跳始终块。
            // ⚠ 危险区若以裸「返回」收尾（如 `捕获: … 返回`），此处终止指令 = 返回(None)：
            //   与下方修正循环同一口径，先归一到「跳始终块」（始终块执行完再决定续延/传播）。
            //   曾把等价断言直接写在这里 → 「返回收尾的捕获块」降级即 panic
            //   （2026-09-14 实测：精准测试案例 32/33 崩于本行，退出码 101）。
            if let 终止指令::返回(None) = &危险基本块.终止指令 {
                危险基本块.终止指令 = 终止指令::无条件跳转(始终块标识);
            }
            // 归一后合法收尾只剩两种：跳转（正常落回始终块）或带值返回（由其自身目标退出，属已知语义缺口）。
            debug_assert!(matches!(危险基本块.终止指令, 终止指令::无条件跳转(_) | 终止指令::返回(_)));
            // 偏差A-嵌套：体内部递归生成的内层异常块须排在本层 危险基本块 之后（但本层 catch/finally/传播 之前），
            // 使编译期 try 栈按控制流嵌套正确反映——本层 设置异常处理 先入栈，内层块随之，本层 catch 最后入栈。
            // 原先「插入到 危险块前块数」会让内层 续延块 因递归 insert 意外落在最前、破坏顺序。故用 split_off
            // 把内层块整体提取出来，再按 [本层危险块, 内层块, (后续本层catch等)] 重排。
            let 内层块 = 块列表.split_off(危险块前块数);
            块列表.push(危险基本块);
            块列表.extend(内层块);
            for i in 危险块前块数..块列表.len() {
                let 块 = &mut 块列表[i];
                if let 终止指令::返回(None) = &块.终止指令 { 块.终止指令 = 终止指令::无条件跳转(始终块标识); }
            }
            // 🆕 方案B S1：危险区结束 → 弹栈；压入异常区目标（异常区内异常 → 本层始终块）。
            弹当前异常目标();
            压当前异常目标(异常目标::收尾(始终块标识));
            let 异常块前块数 = 块列表.len();
            // 异常处理块：清除异常标志，执行异常代码，跳转始终块
            // 偏差A：重抛标志初值——有 catch(存在异常块)清0(吞)，无 catch 置1(始终后向上传播)
            // 有 catch(存在异常块) → 复位(吞)；无 catch 的 stub 层 → 置位(始终后继续向上传播)。
            let 入口标志操作码 = if *存在异常块 { 操作码::复位重抛标志 } else { 操作码::置位重抛标志 };
            let mut 异常基本块 = 基本块 { 异常目标: 取当前异常目标(), 标识符: 异常处理块标识, 指令列表: vec![
                三地址码 { 结果:操作数::无, 操作码:入口标志操作码, 操作数1:操作数::无, 操作数2:None, 操作数3:None, 调试位置:None },
            ], 终止指令: 终止指令::无条件跳转(始终块标识) };
            // 「始终」出口完备化：异常被本层（或其祖先）捕获 → 作废所有在途待办退出。
            // 否则外层始终块出口会把「已被异常覆盖的返回/跳出」当作有效待办派发出去。
            let 全部在途槽: Vec<usize> = 始终层栈.with(|s| s.borrow().iter().map(|l| l.站点槽).collect());
            for 槽 in 全部在途槽 {
                异常基本块.指令列表.push(三地址码 { 结果:操作数::无, 操作码:操作码::存储, 操作数1:操作数::局部变量(槽), 操作数2:Some(操作数::立即整数(0)), 调试位置:None, 操作数3:None });
            }
            for s in 异常块 {
                转换语句(s, &mut 异常基本块, 块列表, 块编号, 局部表, 变量映射, 常量池, 结构体布局, 函数索引映射, 结构体类型索引, 函数签名详情, 全局变量名列表, 匿名函数收集, 始终块标识);
            }
            if !matches!(异常基本块.终止指令, 终止指令::无条件跳转(_) | 终止指令::返回(_) | 终止指令::切换 { .. }) { 异常基本块.终止指令 = 终止指令::无条件跳转(始终块标识); }
            块列表.push(异常基本块);
            for i in 异常块前块数..块列表.len() {
                let 块 = &mut 块列表[i];
                if let 终止指令::返回(None) = &块.终止指令 { 块.终止指令 = 终止指令::无条件跳转(始终块标识); }
            }
            // 🆕 方案B S1：异常区结束 → 弹栈；压入始终区目标 = 外层（始终块内异常替换后向外传播）。
            弹当前异常目标();
            压当前异常目标(外层异常目标);
            // 「始终」出口完备化：弹本层 —— 始终体内的非局部退出只穿越【外层】始终链
            // （本层始终正在执行，不应被重复穿越）。
            let 本层始终 = 始终层栈.with(|s| s.borrow_mut().pop()).unwrap_or(始终层 { 始终块: 始终块标识, 站点槽: 本层站点槽, 点表: Vec::new() });
            // 始终块：执行始终代码，然后查询重抛标志决定是否重新传播异常。
            // 🆕 方案C2：查询指令置于【本块末尾、紧邻 条件跳转】——读的是 base 外部调用结果，
            //    Cranelift 无法常量折叠「有副作用的外部调用」，故即使结果被 SSA 化也必然正确；
            //    这正是取代「全局数据区内存格副本」的底气所在：副本的失同步才是 X1/X2A 的根因，
            //    「SSA 会提升局部变量」只是当初采用副本的表层理由（现由外部调用天然免疫）。
            let mut 始终基本块 = 基本块 { 异常目标: 取当前异常目标(), 标识符: 始终块标识, 指令列表: vec![], 终止指令: 终止指令::无条件跳转(续延块标识) };
            for s in 始终块 {
                转换语句(s, &mut 始终基本块, 块列表, 块编号, 局部表, 变量映射, 常量池, 结构体布局, 函数索引映射, 结构体类型索引, 函数签名详情, 全局变量名列表, 匿名函数收集, 续延块标识);
            }
            // 🆕 异常控制整体作用域退出：恢复进入前的映射（三段内声明的名字在异常控制之外不可见；
            //   块内同名显式声明遮蔽后在此恢复外层绑定）。此后本分支只生成三地址码，不再转换语句。
            *变量映射 = 异常控制外层映射;
            let 重抛临时 = 局部表.len(); 局部表.push(底层表示类型::整数64);
            始终基本块.指令列表.push(三地址码 { 结果:操作数::局部变量(重抛临时), 操作码:操作码::查询重抛标志, 操作数1:操作数::无, 操作数2:None, 操作数3:None, 调试位置:None });
            // 「始终」出口完备化：始终链跑完后的出口三分支（异常优先于任何在途待办退出）——
            //   ① 重抛标志=1 → 传播块  ② 本层站点槽≠0 → 派发块（切换点表）  ③ 否则 → 续延块。
            // 无在途待办点时保持原两分支（不产出派发块，避免不可达块）。
            if 本层始终.点表.is_empty() {
                始终基本块.终止指令 = 终止指令::条件跳转 { 条件: 操作数::局部变量(重抛临时), 真分支: 传播块标识, 假分支: 续延块标识 };
            } else {
                始终基本块.终止指令 = 终止指令::条件跳转 { 条件: 操作数::局部变量(重抛临时), 真分支: 传播块标识, 假分支: 派发块标识 };
            }
            // 注意：条件跳转是 始终块 的有意终止指令（按重抛标志决定传播/派发），不可被兜底覆写
            if !matches!(始终基本块.终止指令, 终止指令::无条件跳转(_) | 终止指令::返回(_) | 终止指令::条件跳转 { .. } | 终止指令::切换 { .. }) { 始终基本块.终止指令 = 终止指令::无条件跳转(续延块标识); }
            块列表.push(始终基本块);
            // 「始终」出口完备化：派发块 —— 按本层点表把在途待办站点搬到「内层外传 / 本层落点」；
            // 未命中（含站点槽=0）→ 续延块（默认分支）。用既有 `终止指令::切换`（双后端已接线）。
            if !本层始终.点表.is_empty() {
                块列表.push(基本块 { 异常目标: 取当前异常目标(), 标识符: 派发块标识, 指令列表: vec![], 终止指令: 终止指令::切换 { 值: 操作数::局部变量(本层站点槽), 分支表: 本层始终.点表.clone(), 默认分支: 续延块标识 } });
            }
            // 🆕 方案B S1：始终区结束 → 弹栈（恢复外层目标；传播/续延块构造读栈顶 = 外层目标）。
            弹当前异常目标();
            // 传播块：重新抛出异常（finally 标记为需传播时触发）；同步作废全部在途待办退出
            let mut 传播基本块 = 基本块 { 异常目标: 取当前异常目标(), 标识符: 传播块标识, 指令列表: vec![], 终止指令: 终止指令::无条件跳转(续延块标识) };
            传播基本块.指令列表.push(三地址码 { 结果:操作数::无, 操作码:操作码::存储, 操作数1:操作数::局部变量(本层站点槽), 操作数2:Some(操作数::立即整数(0)), 调试位置:None, 操作数3:None });
            let 传播清槽: Vec<usize> = 始终层栈.with(|s| s.borrow().iter().map(|l| l.站点槽).collect());
            for 槽 in 传播清槽 {
                传播基本块.指令列表.push(三地址码 { 结果:操作数::无, 操作码:操作码::存储, 操作数1:操作数::局部变量(槽), 操作数2:Some(操作数::立即整数(0)), 调试位置:None, 操作数3:None });
            }
            传播基本块.指令列表.push(三地址码 { 结果:操作数::无, 操作码:操作码::传播异常, 操作数1:操作数::无, 操作数2:None, 调试位置:None, 操作数3: None, });
            块列表.push(传播基本块);
            // 入口跳转
            当前块.终止指令 = 终止指令::无条件跳转(捕获块标识);
            块列表.push(std::mem::replace(当前块, 基本块 { 异常目标: 取当前异常目标(), 标识符: 续延块标识, 指令列表: vec![], 终止指令: if 后续块标识 == usize::MAX { 终止指令::返回(None) } else { 终止指令::无条件跳转(后续块标识) } }));
        }
        高层表示语句::抛出语句(表达式, 位置) => {
            // 🆕 引用计数闸门③（防御性，为将来放宽闸门到多基本块函数预置保险）：
            //    出现 `抛出` ⇒ 本函数整体不发射释放。依据：异常出口（抛出/传播）会跳过函数末尾块，
            //    若在异常出口前释放「抛出值所引用的对象」或「异常处理器仍要用的对象」⇒ 悬垂。
            //    当前该闸门**不改变任何行为**：含 `抛出` 的函数其块终止指令是 `抛出` 而非 `返回`，
            //    末尾块后置扫描本就命中不到 ⇒ 本就不发射。此处置位只为多块放宽后仍安全。
            当前函数含嵌套控制流.with(|f| *f.borrow_mut() = true);
            match 表达式 {
                Some(e) => {
                    // 抛出 异常错误("…")：求值异常对象，经 操作码::抛出 抛出
                    let 临时 = 转换表达式(e, 当前块, 块列表, 块编号, 后续块标识, 局部表, 变量映射, 常量池, 结构体布局, 函数索引映射, 结构体类型索引, 函数签名详情, 全局变量名列表, 匿名函数收集);
                    // 🆕 方案C2：置位重抛标志（供始终块检测是否需要重新传播异常）——只置标志，不构造/覆盖异常对象
                    当前块.指令列表.push(三地址码 { 结果:操作数::无, 操作码:操作码::置位重抛标志, 操作数1:操作数::无, 操作数2:None, 操作数3:None, 调试位置:None });
                    当前块.指令列表.push(三地址码 { 结果: 操作数::无, 操作码: 操作码::抛出, 操作数1: 临时, 操作数2: None, 操作数3: None, 调试位置: Some(位置.clone()) });
                }
                None => {
                    // 裸抛出：重新抛出当前异常，经 操作码::传播异常
                    // 🆕 方案C2：置位重抛标志（供始终块检测是否需要重新传播异常）——取代旧 全局(0) 伪变量存储
                    当前块.指令列表.push(三地址码 { 结果:操作数::无, 操作码:操作码::置位重抛标志, 操作数1:操作数::无, 操作数2:None, 操作数3:None, 调试位置:None });
                    当前块.指令列表.push(三地址码 { 结果: 操作数::无, 操作码: 操作码::传播异常, 操作数1: 操作数::无, 操作数2: None, 操作数3: None, 调试位置: None });
                }
            }
        }
    }
}


/// 本函数**声明返回类型是否为文本**（线程局部，逐函数写入）。
fn 当前函数返回文本() -> bool {
    当前函数返回类型.with(|s| matches!(s.borrow().as_ref(), Some(类型信息::基本型(基本类型::文本))))
}

/// 判定 `返回` 的表达式是否为「**从映射读值**」的确定形态：`.获取(键)` 与 `映射[键]`
/// 降级后均为 `调用 { 函数名: "映射安全加载" | "映射加载" }`（单源：`表达式分析` 方法表）。
fn 是映射读调用(e: &高层表示表达式) -> bool {
    matches!(e, 高层表示表达式::调用 { 函数名, .. }
        if 函数名 == "映射安全加载" || 函数名 == "映射加载")
}

/// 判定 `返回`/声明右值为「**索引读**（`容器[键]`）且**接收者静态类型是映射**」形态。
/// 依据（可证、两侧对齐）：
///   · 语义层把**所有**索引访问统一脱糖为 `调用{函数名:"索引加载"}`（`表达式分析.rs`：运行时按堆实际类型分发）
///     ⇒ 前端只能靠**接收者静态类型**区分数组读 / 映射读；
///   · 缺陷C1 的运行期 +1 **恰好只对"堆实际是映射"生效**（`堆_索引加载` 的映射分支；数组分支明确不加）
///     ⇒ "静态类型是映射" ⟹ "该次读取必然 +1" ✓ 判据与运行期一一对齐。
/// ⚠ 保守边界：`任意` / 未推断 / 数组 ⇒ 一律**不收**（宁可有界泄漏，绝不减掉不存在的计数 ⇒ 悬垂）✓
fn 是映射索引读(e: &高层表示表达式) -> bool {
    match e {
        高层表示表达式::调用 { 函数名, 实参列表, .. } if 函数名 == "索引加载" => {
            matches!(实参列表.first().map(从表达式推断), Some(类型信息::映射(_, _)))
        }
        _ => false,
    }
}

/// 释放**不写空值**：仅发射 `释放引用`（−1），保持槽内句柄不变。
/// 不复用 `发射释放槽`：后者会**写空值**（其前提是"紧随新值 `存储`"），条件内临时不满足该前提。
fn 发射释放不置空(当前块: &mut 基本块, 局部表: &mut Vec<底层表示类型>, 槽: usize) {
    let 临时 = 局部表.len();
    局部表.push(底层表示类型::整数64);
    当前块.指令列表.push(三地址码 {
        结果: 操作数::局部变量(临时),
        操作码: 操作码::释放引用,
        操作数1: 操作数::局部变量(槽),
        操作数2: None,
        调试位置: None,
        操作数3: None,
    });
}

/// 释放「本条件内登记的**文本**返回调用结果」持有的那份计数（**一次**；账本：副本 1 + 读取 1
/// − 返回侧已去重 ⇒ 副本消亡后剩 1 ⇒ 此处 −1 归零）。
fn 释放条件可释放临时(当前块: &mut 基本块, 局部表: &mut Vec<底层表示类型>) {
    let 槽列表 = 当前条件可释放临时.with(|s| std::mem::take(&mut *s.borrow_mut()));
    for 槽 in 槽列表 {
        if 槽 < 局部表.len() {
            发射释放不置空(当前块, 局部表, 槽);
        }
    }
}

/// 枚举运行期「成员标签」= `(类型身份 << 20) | (成员索引 + 1)`。
///
/// 🆕 2026-10-12（修：枚举类型身份缺失）★ 此前标签只有 `成员索引 + 1`，而运行期枚举载体是纯数组
/// `[标签, 数据…]`、**完全不含类型身份** ⇒ 实测 `颜色.红色 == 方向.上` 为**真**（跨枚举类型、同序号成员
/// 被判相等，双模一致），且枚举值无法作键（`值转键` 只看到数组 ⇒ 抛「键类型无效」，与静态白名单放行不一致）。
///
/// 修法要点（为什么这样最小且正确）：
///   · **判等/匹配的既有路径一字不改** —— 构造侧与判等侧都调用本函数算标签，运行时仍只读 `[0]`：
///     常量与常量、常量与 `数组加载[0]` 两条比较路径此前已验证可用，本次只改标签**取值**；
///   · 类型身份取**枚举名**的 40 位稳定散列（FNV-1a 截断）⇒ 同一枚举名恒同值、不同枚举名几乎必不同；
///     身份粒度与结构体一致（`结构体类型索引` 同样按名），故两侧无需新增参数传递；
///   · 低 20 位放成员号（+1），成员上限 1_048_575（远超实际需求），与类型身份互不干扰。
pub fn 枚举成员标签(枚举名: &str, 成员索引: usize) -> i64 {
    let mut 散列: u64 = 0xcbf2_9ce4_8422_2325; // FNV-1a 64 位偏移基准
    for 字节 in 枚举名.as_bytes() {
        散列 ^= *字节 as u64;
        散列 = 散列.wrapping_mul(0x0000_0100_0000_01b3); // FNV-1a 64 位质数
    }
    let 类型身份 = (散列 & 0x0F_FFFF_FFFF) as i64; // 低 40 位
    (类型身份 << 20) | ((成员索引 as i64 + 1) & 0xF_FFFF)
}

fn 表达式结构体名(e: &高层表示表达式) -> Option<String> {
    match e {
        高层表示表达式::变量引用 { 类型, .. }
        | 高层表示表达式::字段访问 { 类型, .. }
        | 高层表示表达式::方法调用 { 类型, .. }
        | 高层表示表达式::调用 { 类型, .. }
        | 高层表示表达式::二元运算 { 类型, .. }
        | 高层表示表达式::枚举成员访问 { 类型, .. }
        | 高层表示表达式::成员访问 { 类型, .. } => {
            if let 类型信息::结构体(名, _) = 类型 { Some(名.clone()) } else { None }
        }
        高层表示表达式::创建结构体 { 结构体名, .. } => Some(结构体名.clone()),
        _ => None,
    }
}

/// 判断类型是否为「复合值」（运行时以堆句柄表示，传值需深拷贝）：
/// 数组 / 映射 / 结构体 / 任意类型。
/// 注意：接口型**不属于**复合值——接口是引用语义，运行时以指针(句柄)表示，
/// 赋值/传参只复制指针(共享同一实现对象)，绝不深拷贝对象本身，
/// 否则接口方法经 thunk(__object 传引用) 原地修改只作用于副本，原实例不变。
fn 是复合类型(类型: &类型信息) -> bool {
    matches!(类型,
        类型信息::数组(_)
        | 类型信息::映射(_, _)
        | 类型信息::结构体(_, _)
        | 类型信息::任意类型 { .. }
    )
}

/// 🆕 引用计数闸门辅助：类型（**含嵌套**）是否含接口型 —— `接口` / `数组<接口>` / `映射<K,接口>` /
/// 可空包装 `任意<…接口…>`。
/// 依据：接口是引用语义，只复制句柄共享同一实现对象，而当前实现**不为共享 +1** ⇒
/// 任何涉及接口句柄的共享路径都可能被释放指令误回收（实测结构体项目 14/15/20 用例因此失败）。
/// ⇒ 凡声明类型含接口型的函数，整体禁用释放发射（宁可泄漏，绝不误回收）。
pub(crate) fn 类型含接口(类型: &类型信息) -> bool {
    match 类型 {
        类型信息::接口型(_) => true,
        类型信息::数组(内层) => 类型含接口(内层),
        类型信息::映射(甲, 乙) => 类型含接口(甲) || 类型含接口(乙),
        // 可空接口包装 `任意<…接口…>`：其成员可持有接口句柄（引用语义、不 +1）⇒ 同样计入闸门。
        类型信息::任意类型 { 约束范围, .. } => 约束范围.iter().any(类型含接口),
        _ => false,
    }
}

/// ★单源★ 该类型是否具有「接口引用语义」——`接口型` **或 可空接口包装 `任意<…直接接口型成员…>`**。
///
/// 规范依据：《智语言编程规范》§4836-4844「赋值完整规则」——接口「**复制标签**」（引用语义，
/// 经接口方法修改应作用于原实例，§4772 / §4834）。可空包装 `任意<接口|空值>` 是规范要求的
/// 「可空接口字段/变量」表达形式，**包装不得改变被包装类型的语义** ⇒ 同样按「复制标签」处理：
/// 声明 / 赋值 / 传参 / 字段读写均**不得深拷贝**（只复制句柄）。
///
/// 注：仅认「**直接**接口型成员」，不含 `任意<数组<接口>>` 之类——容器仍按值语义深拷贝
/// （与 `数组<接口>` 的既有语义一致）。
///
/// ⚠ 历史说明：2026-09-21 之前本判定曾因「≥2 字段结构体下 `临时 = 实例.任意接口字段; 临时.变异方法()`
///   退化为 0」而回退。现已查明该现象的真根因是**引用计数虚高触发 COW 误分离**（接口来源的字段存储
///   合法产生 count=2 ⇒ 写入被 `堆_写入前复制` 分离、新句柄未写回 ⇒ 修改丢失），而非本判定本身。
///   该根因已通过 **COW 退役**（`值类型.rs::堆_写入前复制_已锁定` 恒等化：值语义隔离改由降级层
///   「存储即深拷贝」构造性承担）彻底消除 ⇒ 本判定可以安全放开。
/// 🆕 2026-09-22 **只读检视型系统函数**：参数**仅被读取**、绝不存储 / 不共享 ⇒ 调用点对其**复合类型实参
///   ​**跳过值语义深拷贝**（拷贝纯属浪费，且**拷贝副本无人释放** ⇒ 逐调用泄漏）。
///
/// 实测（`K_泄漏拆分_己只调接口方法.智`）：接口分发适配函数 `__接口分发_<接口>_<方法>` 每次调用都要
///   `取结构体类型索引(__对象)`；该调用对 `__对象`（结构体）发了深拷贝，而 thunk 是**生成的中间代码**、
///   其**拥有型槽清单为空** ⇒ 副本**无人 −1** ⇒ **每个接口方法调用泄漏 1 个结构体副本**（1000 轮 × 2 调用 ⇒ 结构体 2000）。
///
/// ⚠ 收录标准（不得放宽）：**函数体内只读参数**（查类型、查长度等）。任何会**存储/返回/共享**实参的系统函数
///   （如 `数组追加`、`索引存储`、`字段存储`）**绝不可**加入本表 —— 否则会引入跨槽别名（违反值语义隔离）。
pub(crate) fn 是只读检视系统函数(名: &str) -> bool {
    // 🔬 临时探针（env `智语言_只读检视诊断`，降级期每个调用点打印一次 ⇒ 输出有界）：
    //   确认"调用实参深拷贝判定是否咨询了本函数、以及实际函数名是什么"。
    if std::env::var("智语言_只读检视诊断").is_ok() {
        eprintln!("[只读检视查询] 函数名={}", 名);
    }
    // ⚠ 用**子串匹配**而非全等：调用点的函数名可能是限定名（`模块.取结构体类型索引`）或经重写 ✗
    //   （上一版用 `matches!(全等)` 未生效 —— thunk 里仍发出 `深度复制`，即名称未全等命中）
    ["取结构体类型索引", "取结构体类型名称", "数组长度", "文本长度", "映射长度", "容器长度",
     // 🔁 2026-09-25（**转换类内置同样是"只读检视"**）★★ 修「通道接收 +1 文本/轮」的**最终根因**：
     //   **LIR 证据**（`智语言_LIR诊断=启动程序` 跑 `F13_通道收发分解`，接收循环体）：
     //     接收结果入 `收` 后，`转整数(收)` 的**任意类型实参**被发 `深度复制` 作隔离副本 ⇒
     //     而该副本**全程无 `释放引用`** ⇒ **每轮泄漏 1 个文本** ✗（探针 N=500/4000 ⇒ 文本 502/4002）
     //   **为什么安全**：转换类内置**只读取**实参（不存储 / 不返回 / 不共享 ⇒ 符合本函数上方收录标准 ✓）
     //     ⇒ 免拷贝后仅传句柄，语义不变 ✓（`转文本` 同时是"结果必新建"白名单项，两者用途不同、互不冲突 ✓）
     "转整数", "转小数", "转文本", "转逻辑", "任意转文本"]
        .iter()
        .any(|k| 名.contains(k))
}

pub(crate) fn 是接口引用类型(类型: &类型信息) -> bool {
    match 类型 {
        类型信息::接口型(_) => true,
        类型信息::任意类型 { 约束范围, .. } => {
            约束范围.iter().any(|t| matches!(t, 类型信息::接口型(_)))
        }
        _ => false,
    }
}

/// 🆕 2026-08-29 FFI 数组：判定某外部函数的某形参是否为「数组形参」（形参数组元素C类型≠0）。
/// 跨模块限定名先剥模块前缀（与 当前外部函数集 的裸名回退一致）。
fn 是外部数组形参(函数名: &str, 形参索引: usize) -> bool {
    当前外部函数数组形参.with(|s| {
        let 映射 = s.borrow();
        if let Some(集) = 映射.get(函数名) {
            return 集.contains(&形参索引);
        }
        if let Some(裸名) = 函数名.rsplit('.').next() {
            if 裸名 != 函数名 {
                if let Some(集) = 映射.get(裸名) {
                    return 集.contains(&形参索引);
                }
            }
        }
        false
    })
}

/// 若需要（传值复合参数），发射 深度复制 opcode 产生全新副本，返回新临时操作数；
/// 否则原样返回操作数。用于函数按值传参时隔离调用方与被调方的复合值。
fn 发射深拷贝(局部表: &mut Vec<底层表示类型>, 指令列表: &mut Vec<三地址码>, op: 操作数, 需要: bool) -> 操作数 {
    if 需要 {
        let tmp = 局部表.len();
        局部表.push(底层表示类型::整数64);
        指令列表.push(三地址码 {
            结果: 操作数::局部变量(tmp),
            操作码: 操作码::深度复制,
            操作数1: op,
            操作数2: None,
            调试位置: None,
            操作数3: None,
        });
        操作数::局部变量(tmp)
    } else {
        op
    }
}

// ══════════════════════════════════════════════════════════════════════════════
//  ⚡双模式⚡ 值语义深拷贝「按成员身份」（2026-09-21）
//
//  【规范依据】§4772 / §4834：接口 = **复制标签** —— 标签贴在**同一个实例**上，
//    经标签修改作用于原实例。⇒ 值语义深拷贝遇到 **接口 / `任意<接口>` 成员**时必须
//    **只复制标签**，**绝不克隆被指对象**。
//
//  【缺陷（实测，双模一致）】`base::堆_深拷贝` 是**通用递归克隆**——它只看句柄，
//    看不见"这个句柄是标签还是值" ⇒ `乙 = 甲`（甲含 `可移动 设备` 字段）会把接口指向的
//    单车实例**一起克隆** ⇒ `乙.设备.移动(70)` 改的是克隆体，`甲.设备` 仍为 10（应为 70）。
//
//  【设计】**只有"确实含引用语义成员"的复合类型才走慢路径**，其余保持通用 `深度复制`
//    （行为与既往逐字节一致）⇒ 回归面最小、性能不受影响。
//    · 结构体：按字段类型逐一展开（字段数为静态常量，**无需循环**）—— 本次已修正
//    · 数组 / 映射：**待办 Stage 1b**（逐元素展开需循环；当前退回通用深拷贝
//      ⇒ 其**接口元素**仍会被克隆，属已知残余，见 阶段一 后续批次）
// ══════════════════════════════════════════════════════════════════════════════

/// 该类型（沿成员/元素链递归）是否含「引用语义」—— 接口 / `任意<接口>`。
/// `已访问` 用于自引用结构体（`结构体 S(数组<S> 子)`）的终止，避免无限递归。
fn 类型含引用语义成员(类型: &类型信息, 已访问: &mut HashSet<String>) -> bool {
    if 是接口引用类型(类型) { return true; }
    match 类型 {
        类型信息::结构体(名, _) => {
            let 裸名 = 名.rsplit('.').next().unwrap_or(名.as_str()).to_string();
            if !已访问.insert(裸名.clone()) { return false; }
            let 字段列表 = 结构体字段类型表.with(|s| {
                let 表 = s.borrow();
                表.get(名).or_else(|| 表.get(&裸名)).cloned()
            });
            match 字段列表 {
                Some(列表) => 列表.iter().any(|(_, t)| 类型含引用语义成员(t, 已访问)),
                None => false,
            }
        }
        类型信息::数组(内层) => 类型含引用语义成员(内层, 已访问),
        类型信息::映射(甲, 乙) => 类型含引用语义成员(甲, 已访问) || 类型含引用语义成员(乙, 已访问),
        类型信息::任意类型 { 约束范围, .. } => 约束范围.iter().any(|t| 类型含引用语义成员(t, 已访问)),
        _ => false,
    }
}

// 【已移除】`含直接接口字段`（阶段三过渡期判定）——2026-09-22⑥ 起**阶段三收口**：
//   结构体接口字段的 +1 已由 `发射按身份拷贝` 结构体分支闭合、容器元素为独立副本、
//   接口变量槽由"标签别名 +1"配平 ⇒ "含接口 ⇒ 不登记"的特例**全部解除** ⇒ 该判定函数不再需要。

/// ★单源★ 容器写入的**目标位置类型**：数组 ⇒ **元素类型**；映射 ⇒ **值类型**；其它/未知 ⇒ `None`。
///
/// ⚠ **容器元素恒为「独立副本」**（规范 §4993-5001 明文）：
///   「`列表 = [车甲, 车乙]` ⇒ **复制数据** —— 槽位是车甲、车乙的**独立副本**；
///     `列表[1].速度` 变为 55，而 `车甲.速度` 不变 ⇒ **槽位和车甲互不影响**」。
///   ⇒ **容器写入/复制一律按值语义复制元素对象**，**不因元素类型是接口而改为"复制标签"**。
///   （2026-09-21 曾误按"接口 ⇒ 复制标签"放开容器写入元素，致 `14接口功能全面验证` D 段回归 —— 已纠正。）
/// 用途：供 `发射容器身份拷贝` 判定元素身份（接口元素 ⇒ 克隆对象；其余 ⇒ 递归按身份）。
fn 容器元素类型(容器类型: &类型信息) -> Option<类型信息> {
    match 容器类型 {
        类型信息::数组(内层) => Some((**内层).clone()),
        类型信息::映射(_, 值) => Some((**值).clone()),
        _ => None,
    }
}

/// ★单源★ 值语义深拷贝（**类型感知**入口）—— 所有"值语义存储点"统一走此函数。
///   · 接口 / `任意<接口>`  ⇒ **只复制标签**（不拷贝，返回原操作数）
///   · 不需要拷贝         ⇒ 原样返回
///   · 不含引用语义成员    ⇒ 通用 `深度复制`（**快路径，行为与既往完全一致**）
///   · 含引用语义成员      ⇒ 「**按身份**」递归拷贝（结构体逐成员 / **容器逐元素**）
///
/// ⚠ 需要 `当前块/块列表/块编号`：容器的「按身份拷贝」必须展开**循环**（块级结构），
///   而不仅是往指令列表追加 —— 否则无法表达"逐元素拷贝"。
fn 发射深拷贝_类型感知(
    当前块: &mut 基本块,
    块列表: &mut Vec<基本块>,
    块编号: &mut usize,
    局部表: &mut Vec<底层表示类型>,
    op: 操作数,
    类型: &类型信息,
    需要: bool,
    结构体类型索引: &HashMap<String, usize>,
) -> 操作数 {
    if 是接口引用类型(类型) { return op; }
    if !需要 { return op; }
    if !类型含引用语义成员(类型, &mut HashSet::new()) {
        return 发射深拷贝(局部表, &mut 当前块.指令列表, op, true);
    }
    发射按身份拷贝(当前块, 块列表, 块编号, 局部表, op, 类型, 结构体类型索引)
}

/// ★单源★「按元素身份」复制**容器**（数组 / 映射）—— 逐元素展开为**循环**。
///
/// 为什么必须有：容器整体复制（`乙 = 甲`、实参传递、字段存储…）若走通用 `深度复制`，会把**元素**
///   （尤其是接口 / `任意<接口>` 元素）指向的实例一并克隆 ⇒ 标签不再共享（实测
///   `数组<可移动> 甲; 数组<可移动> 乙 = 甲; 乙[1].移动(70)` ⇒ `甲[1]` 仍 0，应为 70）。
///   规范 §4836-4844：「数组 → 复制数据 / 接口 → 复制标签」⇒ 容器复制**必须逐元素按身份决定拷贝与否**。
///
/// 实现：结果容器 = 新建空容器；按下标（数组，1 起）/ 按键（映射，先取「所有键」）遍历源容器，
///   逐元素处理（**接口元素 ⇒ 克隆对象**（独立副本，规范 §4993-5001）；结构体 ⇒ 逐成员按身份；容器 ⇒ 再展开一层循环）
///   后存入结果容器 ⇒ 与"容器元素恒为独立副本"**同一规则、无第二套语义**。
fn 发射容器身份拷贝(
    当前块: &mut 基本块,
    块列表: &mut Vec<基本块>,
    块编号: &mut usize,
    局部表: &mut Vec<底层表示类型>,
    源: 操作数,
    容器类型: &类型信息,
    结构体类型索引: &HashMap<String, usize>,
) -> 操作数 {
    // 循环结构 ⇒「闸门①」（含嵌套控制流 ⇒ 整函数不发射释放），与 `循环语句` 降级同源。
    当前函数含嵌套控制流.with(|f| *f.borrow_mut() = true);
    let (键槽类型, 值类型) = match 容器类型 {
        类型信息::数组(内层) => ((**内层).clone(), (**内层).clone()),
        类型信息::映射(键, 值) => ((**键).clone(), (**值).clone()),
        _ => return 发射深拷贝(局部表, &mut 当前块.指令列表, 源, true),
    };
    let 是映射 = matches!(容器类型, 类型信息::映射(_, _));
    // 结果容器 = 新建空容器（与复合字面量「创建数组 / 创建映射」同源 ⇒ 单一真相）
    let 结果 = 局部表.len(); 局部表.push(底层表示类型::指针);
    当前块.指令列表.push(三地址码 {
        结果: 操作数::局部变量(结果), 操作码: 操作码::调用,
        操作数1: 操作数::函数引用(if 是映射 { base::标准库索引::创建映射 } else { base::标准库索引::创建数组 }),
        操作数2: None, 调试位置: None, 操作数3: None,
    });
    // 遍历序列：数组 = 自身；映射 = 先取「所有键」（数组）再按键取值。
    let 遍历序列 = if 是映射 {
        let 键数组 = 局部表.len(); 局部表.push(底层表示类型::指针);
        当前块.指令列表.push(三地址码 {
            结果: 操作数::局部变量(键数组), 操作码: 操作码::映射所有键,
            操作数1: 源.clone(), 操作数2: None, 调试位置: None, 操作数3: None,
        });
        操作数::局部变量(键数组)
    } else { 源.clone() };
    // 下标（规范：数组索引从 1 开始）
    let 下标 = 局部表.len(); 局部表.push(底层表示类型::整数64);
    当前块.指令列表.push(三地址码 {
        结果: 操作数::局部变量(下标), 操作码: 操作码::加载,
        操作数1: 操作数::立即整数(1), 操作数2: None, 调试位置: None, 操作数3: None,
    });
    let 条件块 = *块编号; *块编号 += 1;
    let 体块 = *块编号; *块编号 += 1;
    let 结束块 = *块编号; *块编号 += 1;
    // ── 条件块：下标 ≤ 序列长度 ──
    let mut 条件基本块 = 基本块 { 异常目标: 取当前异常目标(), 标识符: 条件块, 指令列表: vec![], 终止指令: 终止指令::无条件跳转(结束块) };
    let 长度 = 局部表.len(); 局部表.push(底层表示类型::整数64);
    条件基本块.指令列表.push(三地址码 {
        结果: 操作数::局部变量(长度), 操作码: 操作码::数组长度,
        操作数1: 遍历序列.clone(), 操作数2: None, 调试位置: None, 操作数3: None,
    });
    let 条件槽 = 局部表.len(); 局部表.push(底层表示类型::整数64);
    条件基本块.指令列表.push(三地址码 {
        结果: 操作数::局部变量(条件槽), 操作码: 操作码::小于等于,
        操作数1: 操作数::局部变量(下标), 操作数2: Some(操作数::局部变量(长度)), 调试位置: None, 操作数3: None,
    });
    条件基本块.终止指令 = 终止指令::条件跳转 { 条件: 操作数::局部变量(条件槽), 真分支: 体块, 假分支: 结束块 };
    // ── 体块：取元素 →（递归按身份拷贝）→ 存入结果（+1 侧由存储类 opcode 承担） → 下标+1 → 回边 ──
    let mut 体基本块 = 基本块 { 异常目标: 取当前异常目标(), 标识符: 体块, 指令列表: vec![], 终止指令: 终止指令::无条件跳转(条件块) };
    let 元素 = 局部表.len(); 局部表.push(转换类型(&键槽类型));
    体基本块.指令列表.push(三地址码 {
        结果: 操作数::局部变量(元素), 操作码: 操作码::数组加载,
        操作数1: 遍历序列.clone(), 操作数2: Some(操作数::局部变量(下标)), 调试位置: None, 操作数3: None,
    });
    if 是映射 {
        let 原值 = 局部表.len(); 局部表.push(转换类型(&值类型));
        体基本块.指令列表.push(三地址码 {
            结果: 操作数::局部变量(原值), 操作码: 操作码::容器获取,
            操作数1: 源.clone(), 操作数2: Some(操作数::局部变量(元素)), 调试位置: None, 操作数3: None,
        });
        // 元素身份：接口元素 ⇒ **克隆对象**（独立副本）；其余 ⇒ 递归按身份
        let 拷贝值 = if 是接口引用类型(&值类型) {
            发射深拷贝(局部表, &mut 体基本块.指令列表, 操作数::局部变量(原值), true)
        } else {
            发射深拷贝_类型感知(&mut 体基本块, 块列表, 块编号, 局部表, 操作数::局部变量(原值), &值类型, true, 结构体类型索引)
        };
        let 新容器 = 局部表.len(); 局部表.push(底层表示类型::指针);
        体基本块.指令列表.push(三地址码 {
            结果: 操作数::局部变量(新容器), 操作码: 操作码::映射存储,
            操作数1: 操作数::局部变量(结果), 操作数2: Some(操作数::局部变量(元素)), 操作数3: Some(拷贝值), 调试位置: None,
        });
        体基本块.指令列表.push(三地址码 { 结果: 操作数::无, 操作码: 操作码::存储, 操作数1: 操作数::局部变量(结果), 操作数2: Some(操作数::局部变量(新容器)), 调试位置: None, 操作数3: None });
    } else {
        // 元素身份：接口元素 ⇒ **克隆对象**（独立副本，规范 §4993-5001）；其余 ⇒ 递归按身份
        let 拷贝元素 = if 是接口引用类型(&值类型) {
            发射深拷贝(局部表, &mut 体基本块.指令列表, 操作数::局部变量(元素), true)
        } else {
            发射深拷贝_类型感知(&mut 体基本块, 块列表, 块编号, 局部表, 操作数::局部变量(元素), &值类型, true, 结构体类型索引)
        };
        let 新容器 = 局部表.len(); 局部表.push(底层表示类型::指针);
        体基本块.指令列表.push(三地址码 {
            结果: 操作数::局部变量(新容器), 操作码: 操作码::数组追加,
            操作数1: 操作数::局部变量(结果), 操作数2: Some(拷贝元素.clone()), 调试位置: None, 操作数3: None,
        });
        体基本块.指令列表.push(三地址码 { 结果: 操作数::无, 操作码: 操作码::存储, 操作数1: 操作数::局部变量(结果), 操作数2: Some(操作数::局部变量(新容器)), 调试位置: None, 操作数3: None });
        // 🔁 2026-09-22⑨（同数组字面量，单项落地）：容器对写入值 +1 ⇒ 本处**逐元素克隆出的独立副本**必须 −1
        //   （否则"接口数组身份拷贝"每次复制都泄漏一个元素副本 —— `K_泄漏拆分_丙接口数组` 结构体 1/轮的另一半 ✓）
        释放字面量源(&mut 体基本块, 局部表, &拷贝元素, true);
    }
    let 新下标 = 局部表.len(); 局部表.push(底层表示类型::整数64);
    体基本块.指令列表.push(三地址码 {
        结果: 操作数::局部变量(新下标), 操作码: 操作码::加法,
        操作数1: 操作数::局部变量(下标), 操作数2: Some(操作数::立即整数(1)), 调试位置: None, 操作数3: None,
    });
    体基本块.指令列表.push(三地址码 { 结果: 操作数::无, 操作码: 操作码::存储, 操作数1: 操作数::局部变量(下标), 操作数2: Some(操作数::局部变量(新下标)), 调试位置: None, 操作数3: None });
    // ── 收尾：循环前代码接条件块；条件块/体块入列；**出口块成为新的当前块**（调用方继续在此追加） ──
    当前块.终止指令 = 终止指令::无条件跳转(条件块);
    块列表.push(std::mem::replace(当前块, 基本块 { 异常目标: 取当前异常目标(), 标识符: 结束块, 指令列表: vec![], 终止指令: 终止指令::返回(None) }));
    块列表.push(条件基本块);
    块列表.push(体基本块);
    操作数::局部变量(结果)
}

/// 「按身份」递归拷贝（仅当类型**确实含引用语义成员**时进入）。
/// 结构体：`创建结构体` 新实例 ⇒ 逐字段 字段加载 → （递归/标签） → 字段存储。
/// 容器：见 `发射容器身份拷贝`（逐元素循环）。
fn 发射按身份拷贝(
    当前块: &mut 基本块,
    块列表: &mut Vec<基本块>,
    块编号: &mut usize,
    局部表: &mut Vec<底层表示类型>,
    op: 操作数,
    类型: &类型信息,
    结构体类型索引: &HashMap<String, usize>,
) -> 操作数 {
    if 是接口引用类型(类型) { return op; }   // 引用语义：标签原样复制
    match 类型 {
        类型信息::结构体(名, _) => {
            let 裸名 = 名.rsplit('.').next().unwrap_or(名.as_str()).to_string();
            let 字段列表 = 结构体字段类型表.with(|s| {
                let 表 = s.borrow();
                表.get(名).or_else(|| 表.get(&裸名)).cloned()
            });
            let 字段列表 = match 字段列表 {
                Some(列) => 列,
                // 无布局信息（外部/导入类型未登记）⇒ 退回通用深拷贝（保守）
                None => return 发射深拷贝(局部表, &mut 当前块.指令列表, op, true),
            };
            let 类型索引 = 结构体类型索引.get(名).or_else(|| 结构体类型索引.get(&裸名)).copied().unwrap_or(0) as i64;
            let 新 = 局部表.len(); 局部表.push(底层表示类型::指针);
            当前块.指令列表.push(三地址码 {
                结果: 操作数::局部变量(新), 操作码: 操作码::创建结构体,
                操作数1: 操作数::立即整数(类型索引), 操作数2: None, 调试位置: None, 操作数3: None,
            });
            for (i, (_, 字段类型)) in 字段列表.iter().enumerate() {
                let 槽位 = (i + 1) as i64;
                let v = 局部表.len(); 局部表.push(转换类型(字段类型));
                当前块.指令列表.push(三地址码 {
                    结果: 操作数::局部变量(v), 操作码: 操作码::字段加载,
                    操作数1: op.clone(), 操作数2: Some(操作数::立即整数(槽位)),
                    调试位置: None, 操作数3: None,
                });
                // 值语义成员 ⇒ 递归拷贝；接口成员 ⇒ 只复制标签（`发射深拷贝_类型感知` 内部自会区分）
                let 子需要 = !是接口引用类型(字段类型) && 是复合类型(字段类型);
                let v2 = 发射深拷贝_类型感知(
                    当前块, 块列表, 块编号, 局部表, 操作数::局部变量(v), 字段类型, 子需要, 结构体类型索引,
                );
                // 🔁 2026-09-22 接口成员复制 = **新持有一份标签引用** ⇒ +1
                //   （与宿主对象级联释放时的 −1 配对；缺它则"−1 无中生有"⇒ 撤闸门后误回收）
                if 是接口引用类型(字段类型) {
                    发射增加引用(当前块, 局部表, v2.clone());
                }
                当前块.指令列表.push(三地址码 {
                    结果: 操作数::局部变量(新), 操作码: 操作码::字段存储,
                    操作数1: 操作数::局部变量(新), 操作数2: Some(操作数::立即整数(槽位)),
                    操作数3: Some(v2), 调试位置: None,
                });
            }
            操作数::局部变量(新)
        }
        // 数组 / 映射：**逐元素按身份拷贝**（循环展开；Stage 1b，2026-09-21 收口）
        类型信息::数组(_) | 类型信息::映射(_, _) => {
            发射容器身份拷贝(当前块, 块列表, 块编号, 局部表, op, 类型, 结构体类型索引)
        }
        // `任意<…>` / 枚举等：无「元素身份」可区分 ⇒ 通用深拷贝（保持既有行为）
        _ => 发射深拷贝(局部表, &mut 当前块.指令列表, op, true),
    }
}

/// ⚡双模式⚡ 闭包自由变量分析：返回闭包体内实际引用的、既非自身形参也非闭包内声明局部变量的名字集合。
/// 只捕获真正用到的自由变量（而非作用域内全部局部），使闭包函数签名、创建闭包的捕获数、间接调用 dispatch 三者严格一致。
///
/// ★ 2026-10-02（**F33 订正**）：原文写「嵌套匿名函数独立分析、其自由变量**不向上传播**」✗ ——
///   该说法只在"内层 λ 能越过外层去取"时成立，而**闭包环境是扁平的**（内层 λ 在**外层 λ 的帧内**创建）
///   ⇒ 内层所需的一切**必须能从外层帧取到** ⇒ 外层**必须替内层捕获**（见 `收集表达式中的自由变量`
///   的 `匿名函数` 分支 ✓）。旧实现把内层自由变量**算完即丢** ✗ ⇒ 最小复现 V1「λ 体内定义 λ + 内层
///   捕获顶层局部」读成 **空值** ✗（双模一致 ✗）。修复后仍只捕获真正用到的名字 ✓ 不会过度捕获 ✓。
fn 收集闭包自由变量(函数体: &[高层表示语句], 自身参数: &[String], 已知局部: &HashSet<String>) -> HashSet<String> {
    let mut 局部 = 已知局部.clone();
    let mut 自由 = HashSet::new();
    for 语句 in 函数体 {
        收集语句中的自由变量(语句, 自身参数, &mut 局部, &mut 自由);
    }
    自由.retain(|名| !自身参数.contains(名) && !已知局部.contains(名));
    自由
}

fn 收集语句中的自由变量(语句: &高层表示语句, 自身参数: &[String], 局部: &mut HashSet<String>, 自由: &mut HashSet<String>) {
    match 语句 {
        高层表示语句::变量声明 { 名称, 初始值, .. } => {
            局部.insert(名称.clone());
            收集表达式中的自由变量(初始值, 自身参数, 局部, 自由);
        }
        高层表示语句::赋值 { 目标, 值 } => {
            收集表达式中的自由变量(目标, 自身参数, 局部, 自由);
            收集表达式中的自由变量(值, 自身参数, 局部, 自由);
        }
        高层表示语句::表达式语句(e) => 收集表达式中的自由变量(e, 自身参数, 局部, 自由),
        高层表示语句::条件语句 { 分支列表, 否则分支 } => {
            for (条件, 分支) in 分支列表 {
                收集表达式中的自由变量(条件, 自身参数, 局部, 自由);
                let mut 分支局部 = 局部.clone();
                for s in 分支 { 收集语句中的自由变量(s, 自身参数, &mut 分支局部, 自由); }
            }
            if let Some(分支) = 否则分支 {
                let mut 分支局部 = 局部.clone();
                for s in 分支 { 收集语句中的自由变量(s, 自身参数, &mut 分支局部, 自由); }
            }
        }
        高层表示语句::循环语句 { 条件, 循环体, 步进 } => {
            收集表达式中的自由变量(条件, 自身参数, 局部, 自由);
            let mut 体局部 = 局部.clone();
            for s in 循环体 { 收集语句中的自由变量(s, 自身参数, &mut 体局部, 自由); }
            if let Some(s) = 步进 { 收集语句中的自由变量(s, 自身参数, 局部, 自由); }
        }
        高层表示语句::返回语句(Some(e)) => 收集表达式中的自由变量(e, 自身参数, 局部, 自由),
        高层表示语句::异常控制 { 危险块, 异常块, 始终块, 存在异常块: _ } => {
            for s in 危险块 { 收集语句中的自由变量(s, 自身参数, 局部, 自由); }
            for s in 异常块 { 收集语句中的自由变量(s, 自身参数, 局部, 自由); }
            for s in 始终块 { 收集语句中的自由变量(s, 自身参数, 局部, 自由); }
        }
        高层表示语句::抛出语句(Some(e), _) => 收集表达式中的自由变量(e, 自身参数, 局部, 自由),
        高层表示语句::代码块(b) => {
            let mut 块局部 = 局部.clone();
            for s in b { 收集语句中的自由变量(s, 自身参数, &mut 块局部, 自由); }
        }
        // 🆕 语句序列无作用域 ⇒ 与父作用域共用同一局部集合（不 clone）
        高层表示语句::语句序列(b) => {
            for s in b { 收集语句中的自由变量(s, 自身参数, 局部, 自由); }
        }
        _ => {}
    }
}

fn 收集表达式中的自由变量(表达式: &高层表示表达式, 自身参数: &[String], 局部: &mut HashSet<String>, 自由: &mut HashSet<String>) {
    match 表达式 {
        高层表示表达式::变量引用 { 名称, .. } => {
            if !自身参数.contains(名称) && !局部.contains(名称) {
                自由.insert(名称.clone());
            }
        }
        高层表示表达式::调用 { 函数名, 实参列表, .. } => {
            // 被调名也可能是外层的函数变量（类型没写成函数签名时走按名调用）；
            // 不是外层局部变量的名字会在生成捕获列表时被滤掉。
            if !自身参数.contains(函数名) && !局部.contains(函数名) {
                自由.insert(函数名.clone());
            }
            for a in 实参列表 { 收集表达式中的自由变量(a, 自身参数, 局部, 自由); }
        }
        高层表示表达式::间接调用 { 目标, 实参列表, .. } => {
            收集表达式中的自由变量(目标, 自身参数, 局部, 自由);
            for a in 实参列表 { 收集表达式中的自由变量(a, 自身参数, 局部, 自由); }
        }
        高层表示表达式::方法调用 { 对象, 实参列表, .. } => {
            收集表达式中的自由变量(对象, 自身参数, 局部, 自由);
            for a in 实参列表 { 收集表达式中的自由变量(a, 自身参数, 局部, 自由); }
        }
        高层表示表达式::字段访问 { 对象, .. } => 收集表达式中的自由变量(对象, 自身参数, 局部, 自由),
        高层表示表达式::成员访问 { 对象, .. } => 收集表达式中的自由变量(对象, 自身参数, 局部, 自由),
        高层表示表达式::枚举成员访问 { 数据, .. } => {
            for d in 数据 { 收集表达式中的自由变量(d, 自身参数, 局部, 自由); }
        }
        高层表示表达式::二元运算 { 左侧, 右侧, .. } => {
            收集表达式中的自由变量(左侧, 自身参数, 局部, 自由);
            收集表达式中的自由变量(右侧, 自身参数, 局部, 自由);
        }
        高层表示表达式::隐式转换 { 源表达式, .. } => 收集表达式中的自由变量(源表达式, 自身参数, 局部, 自由),
        高层表示表达式::创建结构体 { 实参列表, .. } => {
            for a in 实参列表 { 收集表达式中的自由变量(a, 自身参数, 局部, 自由); }
        }
        高层表示表达式::字面值(字面, _) => match 字面 {
            高层表示字面值::数组(元素, _) => {
                for e in 元素 { 收集表达式中的自由变量(e, 自身参数, 局部, 自由); }
            }
            高层表示字面值::映射(键值对) => {
                for (k, v) in 键值对 {
                    收集表达式中的自由变量(k, 自身参数, 局部, 自由);
                    收集表达式中的自由变量(v, 自身参数, 局部, 自由);
                }
            }
            _ => {}
        },
        高层表示表达式::匿名函数(f) => {
            // ★ 2026-10-02（**F33 修复**）：原实现「独立分析其自由变量，不向上传播」✗ ——
            //   且**把分析结果直接丢弃** ✗✗（`收集闭包自由变量` 有返回值，原为临时 `HashSet` ✓）。
            //   **缺陷**（最小复现 V1，双模一致 ✗）：`λ 体内再定义 λ`，内层 λ 读取"外层之外的变量"⇒
            //     因外层闭包**未捕获**该名字 ⇒ 内层 λ 创建时从外层帧取到 **空值** ✗
            //     （随后 `转文本(空值)` 抛「空值不能参与类型转换」，报错位置落在输出语句 ⇒ 易误导 ✓）。
            //   **为什么必须传播**：闭包环境是**扁平**的（`堆数据::闭包环境` 只存本层捕获 ✓），
            //     内层 λ 是在**外层 λ 的帧内**创建的 ⇒ 它需要的一切只能来自外层帧 ✓
            //     ⇒ 外层必须**替内层捕获**所有"内层要用、但外层自己也不定义"的名字 ✓。
            //   **实现**：取内层自由变量，滤掉本层形参/局部后并入本层自由集 ✓
            //     —— 仍只捕获**真正用到**的名字 ✓，零捕获的嵌套 λ 不受影响（集合为空 ✓，实测 V4 ✓）。
            let 嵌套参数: Vec<String> = f.形参列表.iter().map(|(n, _)| n.clone()).collect();
            let 内层自由 = 收集闭包自由变量(&f.函数体, &嵌套参数, &HashSet::new());
            for 名 in 内层自由 {
                if !自身参数.contains(&名) && !局部.contains(&名) {
                    自由.insert(名);
                }
            }
        }
        _ => {}
    }
}

/// ⚡双模式⚡ 变异写回单一真相：判定某操作是否「返回新堆句柄且须写回接收者字段」。
/// 覆盖「全局函数调用路径」(opcode) 与「方法调用路径」(方法名后缀)，未来新增变异方法只改此一处，
/// 990/1017/1355 三处共用，杜绝分叉维护复发同类缺陷（如接口接收者变异写回缺口）。
fn 是字段变异写回(函数名: &str, 码: &操作码) -> bool {
    use 操作码::*;
    let 按操作码 = matches!(码,
        &映射存储 | &映射删除 | &映射清空
        | &数组追加 | &数组插入 | &数组删除 | &数组存储
        | &数组清空 | &数组反转 | &数组排序
        // 2026-08-15 通用容器方法（运行时分派）同属变异操作，需写回接收者
        | &容器插入 | &容器删除 | &容器清空
    );
    // 方法调用路径：用方法名后缀匹配，天然覆盖 映射.插入/数组.插入/接口数组.插入 等任意接收者类型，
    // 无需枚举结构体名（治接口接收者缺口 C）。
    // 注意：`.取末尾` 故意不在此列——其返回值是「弹出的元素」而非「变异后的接收者句柄」，
    // 若走写回会把弹出元素误写成接收者变量（如 `末位=数学分.取末尾()` 令 数学分 从数组变成整数），
    // 且数组为原地修改（COW 共享=1 时句柄不变、共享>1 时 堆操作 内部已生成新句柄并就地弹出），
    // 接收者变量持有的句柄始终指向已弹出的数组，无需写回。
    let 按方法名 = 函数名.ends_with(".插入") || 函数名.ends_with(".删除") || 函数名.ends_with(".清空")
        || 函数名.ends_with(".追加") || 函数名.ends_with(".排序") || 函数名.ends_with(".反转")
        || 函数名.ends_with(".替换");
    // ══════════════════════════════════════════════════════════════════════════════
    // ✅ **已闭环（2026-09-24 实测复核）** —— 原「已知缺口」（2026-09-20 定位）**已修复** ✓
    //   复现件 `测试/2项目类测试/结构体测试项目/缺陷复现/F4_初始化内嵌套字段用户方法不生效.智`
    //   双模（解释 + 编译）均输出 `内名=[张三]` ✓ ⇒ 该形态已生效。
    //   ⚠ 下面保留**历史记录**仅作机制说明；其中"**勿按返回值类型简单放开**"**仍然成立** ✓
    //   ⚠ 纪律：**引用本条前必须实测复核**（历史标注曾长期滞后于修复 ⇒ 已误导过盘点）✓
    // ── 历史记录（2026-09-20 定位）──
    //   本表**只覆盖容器变异方法名**，不含**用户自定义结构体方法** ⇒ 如下写法会丢失修改：
    //     `初始化(): 自身.内.设名(名)      // ✗ 不生效（内层的 COW 新句柄被丢弃）`
    //   实测四场景对照（`日志/脚本/临时/复现_初始化内嵌套调用分步诊断.智`）：
    //     · `初始化()` 内 `自身.直接字段 = 值`            ✓ 生效
    //     · `初始化()` 内 `自身.嵌套字段.用户方法(...)`    ✗ **不生效**（本条缺口）
    //     · **普通方法**内 `自身.嵌套字段.用户方法(...)`    ✓ 生效（COW 引用计数=1 时原地修改，属**巧合**）
    //     · **外部** `实例.嵌套字段.用户方法(...)`          ✓ 生效（同上）
    //   规避写法（规范内、已验证 `验证_显式写回可规避.智`）：取局部 → 调方法 → **显式写回字段**
    //     `临时 = 自身.内` / `临时.设名(名)` / `自身.内 = 临时`   ⇒ 生效 ✓
    //   ❌ **不能**简单改为「方法返回值为结构体/容器 ⇒ 一律写回接收者」：
    //      `和 = 左 + 右`（运算符重载路由到 `左.加法(右)`，返回**新对象**且**不修改 `左`**）
    //      若按返回类型写回，会把 `左` 覆盖成 `和` ⇒ **破坏运算符重载语义** ✗✗
    //   ✅ 正确修复方向：需精确判定「该方法是否修改了 `自身`」（分析方法体是否含对 `自身.字段` 的写入，
    //      并传递闭包到其调用的其它方法），在语义层标记后由降级层查表 ⇒ 属**独立课题**，另行设计。
    // ══════════════════════════════════════════════════════════════════════════════
    // ③ 标准库元数据表（单源，2026-08-30）：新增变异方法只需在注册表标记 是变异方法，无需再改本函数。
    //    三者分工：①按操作码 覆盖已降级的容器指令；②按方法名后缀 覆盖任意接收者类型
    //    （含用户结构体/接口，无法用标准库表穷举）；③覆盖标准库内部名。
    let 按元数据表 = crate::标准库元数据::是变异方法名(函数名);
    // 【④「用户自定义变异方法写回」已彻底移除（2026-09-21 · COW 退役）】
    //   历史脉络：曾登记「方法体含 `自身.字段 = …`」的用户方法（`高层表示节点.rs::用户变异方法集`），
    //   试图比照容器变异方法把「新句柄」写回接收者字段。实测**行不通**：用户变异方法**无返回值**
    //   ⇒ 写回会把接收者字段覆盖成 `空值`（`未捕获异常: 空值不能参与类型转换`）。
    //   当时的"可行方向"是让方法把自身句柄传出来（类比 A2 的 `返回 自身`）——**现已被证明为错误方向**。
    //
    //   ★真根因（2026-09-21 实证定位）：`初始化()` 内 `自身.内.设名(名)` 失效**与"写回"无关**，
    //     而是**引用计数虚高触发 COW 误分离**（接口/字段来源的存储合法产生 count>1 ⇒ 写入被
    //     `堆_写入前复制` 分离，新句柄无人写回 ⇒ 修改丢失）。
    //   ⇒ **COW 退役后**（值语义隔离由降级层「存储即深拷贝」**构造性**承担：写入一律原地、
    //     句柄恒不变），**整族问题不存在**：经字段/元素/嵌套链调用用户变异方法**全部原地生效**，
    //     既不需要"写回"、也不需要"方法返回自身"。
    //   回归守护：`测试/2项目类测试/结构体测试项目/源码/105嵌套字段调用用户变异方法.智`。
    按操作码 || 按方法名 || 按元数据表
}

/// ⚡双模式⚡ 把变异结果 ret 写回接收者字段/数组元素。
/// 接收者可为：①多级 字段访问（自身.数据.子项）②数组下标（列表[0]）③接口数组/映射元素。
/// 递归解多级 字段访问 到 (根对象, 最终字段槽位) 发射单条 字段存储；数组下标走 数组存储。
/// 单一真相，替代 990/1017/1355 三处分叉代码；变量引用接收者不走此路径（由首参原始索引路径处理）。
#[allow(clippy::too_many_arguments)]
fn 发射字段接收者写回(
    接收者: &高层表示表达式,
    新句柄: 操作数,
    当前块: &mut 基本块,
    块列表: &mut Vec<基本块>,
    块编号: &mut usize,
    后续块标识: usize,
    局部表: &mut Vec<底层表示类型>,
    变量映射: &mut HashMap<String, usize>,
    常量池: &mut Vec<常量值>,
    结构体布局: &HashMap<String, Vec<(String, 底层表示类型)>>,
    函数索引映射: &mut HashMap<String, usize>,
    结构体类型索引: &HashMap<String, usize>,
    函数签名详情: &HashMap<String, (usize, Vec<Option<高层表示表达式>>, Vec<参数传递方式>, Vec<类型信息>)>,
    全局变量名列表: &[String],
    匿名函数收集: &mut Vec<(usize, 底层表示函数)>,
) {
    match 接收者 {
        // 多级 字段访问：递归解 对象 得根对象操作数，本层发射 字段存储(根, 字段槽位+1, 新句柄)
        高层表示表达式::字段访问 { 对象, 字段索引, .. } => {
            let 对象操作数 = 转换表达式(
                对象, 当前块, 块列表, 块编号, 后续块标识, 局部表, 变量映射, 常量池,
                结构体布局, 函数索引映射, 结构体类型索引, 函数签名详情, 全局变量名列表, 匿名函数收集,
            );
            let 字段槽位 = *字段索引 as i64 + 1;
            当前块.指令列表.push(三地址码 {
                结果: 操作数::无, 操作码: 操作码::字段存储,
                操作数1: 对象操作数, 操作数2: Some(操作数::立即整数(字段槽位)),
                操作数3: Some(新句柄), 调试位置: None,
            });
        }
        // 嵌套容器接收者（列表[0].插入 / 外层["层1"]["内"] = 值）：HIR 表示为 调用{数组加载|映射加载}。
        // 需递归解嵌套：若 外层 本身也是 加载 调用，先在本层写入 新值，再把当前层句柄写回 外层；
        // 否则直接 store(外层, 键, 新值)。否则嵌套映射写回链不完整（只改了 load 出来的副本）。
        高层表示表达式::调用 { 函数名, 实参列表, .. } if crate::标准库元数据::是容器加载调用(函数名) => {
            let 对象表达式 = 实参列表.get(0).unwrap();
            let 键表达式 = 实参列表.get(1).unwrap();
            let 对象HIR: &高层表示表达式 = 对象表达式;
            // 单源（2026-08-30）：容器加载判定由 标准库元数据表 的 是容器加载 标记派生
            let 是嵌套 = matches!(对象HIR, 高层表示表达式::调用 { 函数名: f, .. } if crate::标准库元数据::是容器加载调用(f));
            // 统一写回码：2026-08-15 起容器[键] 写回一律走 索引存储（base 运行时按堆实际类型分发），
            // 消除「数组加载→数组_store / 映射_load→映射_store」的写回码错配（裸标注映射误用数组_store 静默无操作）。
            let 存储码 = 操作码::索引存储;
            if 是嵌套 {
                // 中间层句柄 H = 加载(外层, 层键)：H 是 映射_load(对象, 中间键) 的结果
                let 中间句柄 = 转换表达式(
                    对象表达式, 当前块, 块列表, 块编号, 后续块标识, 局部表, 变量映射, 常量池,
                    结构体布局, 函数索引映射, 结构体类型索引, 函数签名详情, 全局变量名列表, 匿名函数收集,
                );
                let 键操作数 = 转换表达式(
                    键表达式, 当前块, 块列表, 块编号, 后续块标识, 局部表, 变量映射, 常量池,
                    结构体布局, 函数索引映射, 结构体类型索引, 函数签名详情, 全局变量名列表, 匿名函数收集,
                );
                // 先在本层写入 新值 到 H 的 键
                当前块.指令列表.push(三地址码 {
                    结果: 操作数::无, 操作码: 存储码,
                    操作数1: 中间句柄.clone(), 操作数2: Some(键操作数),
                    操作数3: Some(新句柄.clone()), 调试位置: None,
                });
                // 再把 改后的 H 递归写回 外层 的 层键（完整写回链）
                发射字段接收者写回(对象HIR, 中间句柄, 当前块, 块列表, 块编号, 后续块标识, 局部表, 变量映射, 常量池, 结构体布局, 函数索引映射, 结构体类型索引, 函数签名详情, 全局变量名列表, 匿名函数收集);
            } else {
                let 对象操作数 = 转换表达式(
                    对象表达式, 当前块, 块列表, 块编号, 后续块标识, 局部表, 变量映射, 常量池,
                    结构体布局, 函数索引映射, 结构体类型索引, 函数签名详情, 全局变量名列表, 匿名函数收集,
                );
                let 键操作数 = 转换表达式(
                    键表达式, 当前块, 块列表, 块编号, 后续块标识, 局部表, 变量映射, 常量池,
                    结构体布局, 函数索引映射, 结构体类型索引, 函数签名详情, 全局变量名列表, 匿名函数收集,
                );
                当前块.指令列表.push(三地址码 {
                    结果: 操作数::无, 操作码: 存储码,
                    操作数1: 对象操作数, 操作数2: Some(键操作数),
                    操作数3: Some(新句柄), 调试位置: None,
                });
            }
        }
        _ => {} // 变量引用/字面量接收者不在此写回
    }
}

pub fn 转换表达式(
    表达式: &高层表示表达式, 当前块: &mut 基本块, 块列表: &mut Vec<基本块>, 块编号: &mut usize, 后续块标识: usize, 局部表: &mut Vec<底层表示类型>,
    变量映射: &mut HashMap<String, usize>, 常量池: &mut Vec<常量值>,
    结构体布局: &HashMap<String, Vec<(String, 底层表示类型)>>,
    函数索引映射: &mut HashMap<String, usize>,
    结构体类型索引: &HashMap<String, usize>,
    函数签名详情: &HashMap<String, (usize, Vec<Option<高层表示表达式>>, Vec<参数传递方式>, Vec<类型信息>)>,
    全局变量名列表: &[String],
    匿名函数收集: &mut Vec<(usize, 底层表示函数)>,
) -> 操作数 {
    match 表达式 {
        高层表示表达式::字面值(字面值, _) => match 字面值 {
            高层表示字面值::整数(v) => 操作数::立即整数(*v),
            高层表示字面值::小数(v) => 操作数::立即小数(*v),
            高层表示字面值::文本(v) => { let idx = 常量池.len(); 常量池.push(常量值::文本(v.clone())); 操作数::字符串常量(idx) }
            高层表示字面值::逻辑(v) => 操作数::立即逻辑(*v),
            高层表示字面值::空值 => 操作数::立即空值,
            高层表示字面值::数组(元素, _) => {
                // 🆕 引用计数闸门：数组字面量内含「接口型元素」（如 `数组<接口> 列表 = [接口值, …]`）
                //    ⇒ 元素是接口句柄（共享实例、当前实现不为共享 +1）⇒ 本函数整体不发射释放，
                //    避免误回收仍被接口/接口数组元素持有的原实例（实测结构体项目 14/15 用例因此失败）。
                for e in 元素 {
                    if 是接口引用类型(&从表达式推断(e)) {
                        当前函数含接口用法.with(|f| *f.borrow_mut() = true);
                    }
                }
                let arr_idx = 局部表.len(); 局部表.push(底层表示类型::指针);
                当前块.指令列表.push(三地址码 { 结果:操作数::局部变量(arr_idx), 操作码:操作码::调用, 操作数1:操作数::函数引用(base::标准库索引::创建数组), 操作数2:None, 调试位置:None, 操作数3: None, });
                for elem in 元素 {
                    // 🔁 2026-09-24（**soak R 修复**）：保留**源元素操作数**（供随后释放"自有右值源临时"用）✓
                    let 源元素 = 转换表达式(elem, 当前块, 块列表, 块编号, 后续块标识, 局部表, 变量映射, 常量池, 结构体布局, 函数索引映射, 结构体类型索引, 函数签名详情, 全局变量名列表, 匿名函数收集);
                    // ⚡规范 §4993⚡：**容器元素是独立副本**（"数组创建时：复制数据，槽位是独立副本"），
                    //   **不因元素类型是接口而改为共享**。
                    //   ⚠ 此前该隔离**靠"声明处对字面量整体深拷贝"附带满足** ⇒ 一旦启用「新建值免拷贝」
                    //     即暴露为共享（实测：`103接口标签与值语义并存` ②③ 3 条断言失败、`14` D 段 3 条失败）。
                    //   ⇒ 在**构造处**即复制：接口元素**克隆对象**（通用 `发射深拷贝`）；
                    //     含接口成员的复合元素走**按身份拷贝**（`发射深拷贝_类型感知`：数据复制、成员仍为标签）。
                    let 元素类型 = 从表达式推断(elem);
                    let elem_op = if 是接口引用类型(&元素类型) {
                        发射深拷贝(局部表, &mut 当前块.指令列表, 源元素.clone(), true)
                    } else {
                        发射深拷贝_类型感知(
                            当前块, 块列表, 块编号, 局部表, 源元素.clone(), &元素类型,
                            是复合类型(&元素类型), 结构体类型索引,
                        )
                    };
                    let new_arr = 局部表.len(); 局部表.push(底层表示类型::指针);
                    当前块.指令列表.push(三地址码 { 结果:操作数::局部变量(new_arr), 操作码:操作码::数组追加, 操作数1:操作数::局部变量(arr_idx), 操作数2:Some(elem_op.clone()), 调试位置:None, 操作数3: None, });
                    当前块.指令列表.push(三地址码 { 结果:操作数::无, 操作码:操作码::存储, 操作数1:操作数::局部变量(arr_idx), 操作数2:Some(操作数::局部变量(new_arr)), 调试位置:None, 操作数3: None, });
                    // 🔁 2026-09-22⑨（**写入值临时副本释放**）：容器对写入值 **+1**（base `数组追加` 约定），
                    //   而本处另持有"**构造处复制出的独立副本**" ⇒ 必须 −1，否则该副本**计数永久虚高 1** ⇒ 逐轮泄漏
                    //   （实测 `K_泄漏拆分_丙接口数组`：结构体 **2/轮** = 字面量元素副本 + 身份拷贝元素副本 ✓✓）
                    //   ⚠ 仅在**确实发生复制**时释放（接口元素 / 复合元素）；标量 / 文本元素无副本 ⇒ 跳过 ✓
                    if 是接口引用类型(&元素类型) || 是复合类型(&元素类型) {
                        释放字面量源(当前块, 局部表, &elem_op, true);
                        // 🔁 2026-09-24（**soak R 重放：D1 落地后**）：上方只释放"**构造处复制出的副本**"；
                        //   元素表达式为**调用方自持的自有右值**（`是新建值`：创建结构体 / 复合字面量）时，
                        //   **源临时也须 −1** ✗（否则逐轮泄漏：R 形状实测 **+4/轮** = 2 源临时结构体
                        //   + 各自 `数据：数组<整数> = []` 默认字段数组 ✓✓）
                        //   ⚠ **此前回退的真正原因已定位并修复**：先前在**并发用例**出现 `悬垂(拥有型)=4` ✗，
                        //     根因不是本处释放本身，而是 **D1「任务在途值记账」缺失**（对象随任务交接移入
                        //     任务帧，而**交接处未 +1** ⇒ 调用方的合法 −1 变成"过度释放"）✓
                        //     现 base `并发启动任务` 已"**接收方自持 +1 / 任务结束 −1**"（§18.81）⇒
                        //     任务异步读取期间由任务侧引用兜底 ⇒ 本处释放安全 ✓✓
                        //   ⚠ 门控与 K/M/N 同款：只收"**确定自有**"的右值；变量引用 / 字段 / 索引访问一律不收 ✓
                        if 是新建值(elem) {
                            释放字面量源(当前块, 局部表, &源元素, true);
                        }
                    }
                }
                操作数::局部变量(arr_idx)
            }
            高层表示字面值::映射(键值对) => {
                // 🔁 2026-09-22③（闸门②细化）：**不再**因"映射字面量含接口型值"禁用整个函数
                //   （同数组字面量：容器槽已由声明侧 `类型含接口<映射<K,接口>>` 排除 ⇒ 不登记不释放）。
                let map = 局部表.len(); 局部表.push(底层表示类型::指针);
                // ⚠ 2026-09-20 单一真相收敛：`函数引用(7)` 是内联魔数，改为具名常量
                //   `base::标准库索引::创建映射`（= 7，见 基础功能/src/标准库索引.rs:14），
                //   与 标准库元数据.rs:566 的「创建映射」条目**同源**，
                //   避免索引调整时"改了元数据忘了降级层"的静默错配。
                当前块.指令列表.push(三地址码 { 结果:操作数::局部变量(map), 操作码:操作码::调用, 操作数1:操作数::函数引用(base::标准库索引::创建映射), 操作数2:None, 调试位置:None, 操作数3: None, });
                for (键, 值) in 键值对 {
                    let k = 转换表达式(键, 当前块, 块列表, 块编号, 后续块标识, 局部表, 变量映射, 常量池, 结构体布局, 函数索引映射, 结构体类型索引, 函数签名详情, 全局变量名列表, 匿名函数收集);
                    // 🔁 2026-09-24（**soak S 修复**）：与数组字面量同法 —— 保留**源值操作数**供"自有右值"释放 ✓
                    let 源值 = 转换表达式(值, 当前块, 块列表, 块编号, 后续块标识, 局部表, 变量映射, 常量池, 结构体布局, 函数索引映射, 结构体类型索引, 函数签名详情, 全局变量名列表, 匿名函数收集);
                    // ⚡规范 §4993⚡：**映射值同样是独立副本**（"复制数据"），与数组字面量同规则
                    //   （键为标量/文本 ⇒ 不需要复制）。缺此复制时，该隔离只能靠"声明处对字面量整体深拷贝"
                    //   附带满足 ⇒ 一旦启用「新建值免拷贝」即暴露为共享
                    //   （实测：`20数组映射与结构体接口组合` F 段 `映射<文本,汽车> 车房 = {"a": 车3}` ⇒ 改车房[a] 串改 车3 ✗）。
                    let 值类型 = 从表达式推断(值);
                    // ⏸ **"新建值免拷贝"（(a) 半）已实测并回退（2026-09-24）** ✗ —— **重要负面结论**：
                    //   · 动机（账本证据 `T3_单轮账本`）：副本对象残留 1 ⇒ 结构体值 **100% 泄漏** ✗；
                    //     `映射存储` 对**新建**子对象也 `+1`（而 base 注记"新建子对象 = 移动，不 +1"）
                    //     ⇒ 理论上"免拷贝 + 释放源一次"即可闭环 ✓
                    //   · **实测**：soak **S/T 形状确实转为完全平坦**（存活差 **= 0**，双引擎 ✓✓）
                    //     **但** `总网络模块全面测试`（解释）**稳定出现 `悬垂(拥有型)=2`** ✗（3/3 次复现 ✓），
                    //     且**撤掉"(b) 释放既有复合副本"后仍为 2** ✗ ⇒ **与释放门无关** ✗
                    //   ⇒ **结论：该网络用例的形态"依赖存在独立副本"** —— 一旦映射值改为与源**同一对象**，
                    //     即有对象被**两次 −1**（源侧 −1 + 映射/级联一侧 −1）⇒ 悬垂 ✓
                    //   ⇒ 换言之：**`总网络模块全面测试` 是映射字面量类修复的"拦截器"**（4 次尝试全被它拦下 ✓✓）
                    // ⇒ 依铁律「**宁可泄漏，绝不误回收**」**回退** ✓（恢复"深拷贝 + 只释放源临时"已验证状态 ✓）
                    // ☆ **下一步（唯一正确顺序）**：先用账本工具定位**该拦截器形态的具体配对**
                    //   （谁持有、谁 −1、为何缺 `+1`）⇒ 解决后再放开字面量侧优化 ✓
                    // 🔁 2026-09-24（**S 副本侧正解落地：新建值免拷贝**）★★ —— 由账本证据 + 被调方白名单共同成立 ✓
                    //   **账本证据**（`T3_单轮账本`）：构造处深拷贝产生的"副本"对象与容器 `+1` 后**残留 1**
                    //     ⇒ 结构体值 **100% 泄漏** ✗（分段归因：映射/结构体 全量增长 ✓）。
                    //   **机理**：`映射存储` 对**新建**子对象也 `+1`（而 base 注记"新建子对象 = **移动**，不 `+1`"）
                    //     ⇒ 故对**新建值**应**免拷贝**（直接以源入容器 ✓ 无别名 ⇒ 隔离天然满足 ✓）+ 前端
                    //       释放**源**一次（抵消该 `+1` ✓）⇒ 计数 1→2→1→0 **闭环** ✓✓
                    //   **为什么此前"免拷贝"一度不安全**：`总网络模块全面测试` 稳定 `悬垂=2` ✗ ——
                    //     根因**不在本处**，而在**实参释放缺少"被调方白名单"**（未知内置会把实参**移动**进
                    //     自有结构体 ⇒ 调用点再释放 = 多释放 ✗）✓；该门补齐后本配置**实测 `悬垂=0`** ✓✓
                    //   · **既有复合**（变量/字段 ⇒ 有别名）⇒ 仍走深拷贝（隔离必需 ✓）；其副本**已释放** ✓
                    //     ✅ **已闭环（2026-09-24 实测复核）**：原注"副本暂不释放（残余窄缺口）"**已过时** ——
                    //       紧接其下的分支即 `else if 是复合类型 && !是接口引用类型 ⇒ 释放副本 v` ✓；
                    //       且 soak 形状 S（映射含结构体值）/T（嵌套字面量）**实测完全平坦**（差=0 双引擎）✓
                    //   · **接口** ⇒ 复制标签 ⇒ 不释放 ✓（标签别名不计数 ✓）
                    let 免拷贝_新建 = 是新建值(值) && !是接口引用类型(&值类型);
                    let v = if 免拷贝_新建 {
                        源值.clone()
                    } else if 是接口引用类型(&值类型) {
                        发射深拷贝(局部表, &mut 当前块.指令列表, 源值.clone(), true)
                    } else {
                        发射深拷贝_类型感知(
                            当前块, 块列表, 块编号, 局部表, 源值.clone(), &值类型,
                            是复合类型(&值类型), 结构体类型索引,
                        )
                    };
                    // ⚡双模式⚡: 映射存储约定与数组追加对称：
                    //   操作数1=映射句柄(取0), 操作数2=键(取1), 操作数3=值(取2)，结果写入新临时变量后 STORE 回 map。
                    //   此前误把 键/值 放在 操作数1/2 且丢失映射句柄，导致运行时 堆_映射存储(映射,键,值) 收不到映射而返回空值。
                    let new_map = 局部表.len(); 局部表.push(底层表示类型::指针);
                    当前块.指令列表.push(三地址码 { 结果:操作数::局部变量(new_map), 操作码:操作码::映射存储, 操作数1:操作数::局部变量(map), 操作数2:Some(k), 操作数3: Some(v.clone()), 调试位置:None, });
                    当前块.指令列表.push(三地址码 { 结果:操作数::无, 操作码:操作码::存储, 操作数1:操作数::局部变量(map), 操作数2:Some(操作数::局部变量(new_map)), 调试位置:None, 操作数3: None, });
                    // 🔁 2026-09-24（**soak S 重放：D1 落地后**）：与数组字面量**完全同款**的两次 −1 ✓
                    //   ① **构造处复制出的副本**：容器对写入值 `+1`（`映射存储` 与 `数组追加` **同构**，
                    //      已核实 `堆_映射存储` 确实 `引用计数加一(&值)` ✓）⇒ 本处持有的副本必须 −1 ✗
                    //   ② **自有右值的源临时**（`是新建值`）⇒ 亦须 −1 ✗
                    //   （S 形状实测 **+8/轮** = 2 源临时结构体 + 2 源临时字段数组 + 2 副本结构体 + 2 副本字段数组 ✓✓）
                    //   ⚠ 与 R 同因：此前回退是 **D1 缺失**所致（非本处释放本身）⇒ 现 D1 已落地（§18.81）✓
                    //   ⚠ 仅在**确实发生复制**（接口 / 复合值）时；标量 / 文本值无副本 ⇒ 跳过 ✓
                    if 是接口引用类型(&值类型) || 是复合类型(&值类型) {
                        // 🔁 2026-09-24（**soak S 缺口收窄：只释放「自有右值源临时」**）★
                        // 事实（专项**最小复现件** `日志/脚本/临时/soak/T_映射字面量作实参.智` +
                        //   四段二分，见 §18.90）：
                        //   · **源临时释放**（本处）：在独立复现件与**网络用例**下**均安全** ✓✓
                        //     —— 源临时是本字面量**现场新建**（`是新建值`）⇒ 无论"构造处副本"是否为独立对象，
                        //        释放它都**恰好一次**：
                        //          · 副本确为独立对象 ⇒ 源归零（无人再持有 ✓）✓
                        //          · 拷贝为 **no-op**（源即副本）⇒ 该对象已被 `映射存储` `+1`
                        //            ⇒ 释放一份后仍留一份**归映射持有** ✓✓
                        //   · **构造处副本释放**（曾与上者同开）**不安全** ✗：两半同开时 `总网络模块全面测试`
                        //     （**解释**）报 `悬垂(拥有型)=4` ⇒ 属**双重释放**（该形态下"副本"与"源"为
                        //     **同一对象**）⇒ 副本释放与源释放**必须互斥** ✓
                        //     ⚠ 待办：需在降级层取得"**深拷贝是否真产生新对象**"的可靠判据（静态类型不足以判定
                        //       —— 实测同一 `复合` 类型在不同形态下分别为"真拷贝"与"no-op"）⇒ 判定就绪后方可开启 ✓
                        //   · 效果：映射字面量场景泄漏由 **2/轮 → 1/轮**（复现件实测 `映射 2002 → 1001`）✓
                        //
                        // 🔁 2026-09-24（**S 副本侧落地：按"拷贝是否可靠"分流**）★ —— 收窄已进一步放开：
                        //   **为什么此前两侧不能同开**：必有形态使 `发射深拷贝_类型感知` 成为 **no-op**
                        //     （副本 === 源）⇒ 两份 −1 ⇒ **误回收** ✗（四段二分：仅两侧同开时网络用例悬垂=4 ✓）
                        //   **根因**：值类型为 **`任意类型`**（静态不可判定 ✗）时无法生成具体拷贝代码
                        //     ⇒ 该函数**原样返回**（保守回退）⇒ 副本与源**同一对象** ✓
                        //   **正解（静态可判定 ✓）**：
                        //     · **接口引用类型** ⇒ 拷贝 = "复制标签 + `增加引用`"（计数已配平 ✓）⇒ 两次释放安全 ✓
                        //     · **具体复合类型**（数组/映射/结构体：类型已知 ⇒ 生成**真拷贝** ✓）⇒ 两次释放安全 ✓
                        //     · **`任意类型`**（拷贝可能 no-op ✗）⇒ **只释放源临时** ✓
                        //       （`映射存储` 已 `+1` ⇒ 释放一份后仍留一份**归映射持有** ✓ 恰好平衡 ✓）
                        // 🔁 2026-09-24（**S 副本侧：按"拷贝是否可靠"分流，第二次修正**）★
                        //   **第一次尝试被否定**：按 `是接口引用类型 || (是复合类型 && !任意类型)` 放开
                        //     ⇒ 网络用例仍 `悬垂(拥有型)=4` ✗ ⇒ 命中的**不是** `任意类型` ✗
                        //   **根因（读 `发射深拷贝_类型感知` 自身文档取证 ✓）**：该函数有两条 **no-op 分支**：
                        //     · **接口 / `任意<接口>` ⇒ "只复制标签"（返回原操作数）** ✗← **本次命中项** ✓
                        //     · `!需要` ⇒ 原样返回 ✗
                        //   ⇒ 对**接口值**：map 路径的"副本"与"源"**同一对象**，且**标签复制不计数**
                        //     （接口标签约定）⇒ 计数 = 源 1 + `映射存储` +1 = **2** ⇒ 两次 −1 ⇒ **0（悬垂）** ✗✓
                        //   ⇒ **正解**：只有**具体复合类型**（数组/映射/结构体 ⇒ 走"快路径真拷贝"或
                        //     "按身份拷贝"，均**产生独立且被计数的副本** ✓）才可两次释放；
                        //     **接口 / `任意<接口>`**（拷贝 = 同对象标签）⇒ **只释放源临时** ✓
                        // 🔁 2026-09-24（**两侧各释放恰好一次** ✓）：与上方"免拷贝_新建"配对 ✓
                        //   · **新建值**（已免拷贝 ⇒ `v` 与 `源值` 同一对象）⇒ 释放**源**一次 ✓
                        //   · **既有复合**（`v` = 独立副本、仅前端持有 ✓）⇒ 释放**副本**一次 ✓
                        //     ⚠ 此前 attempt 3 把本条判为不安全 ✗，但**账本已证真正元凶是"实参释放缺被调方
                        //       白名单"**（属**另一条代码路径**：`网络.获取(url, {选项})` 的实参释放 ✗）
                        //       ⇒ 本条**从未被单独证伪** ✓；白名单门落地后放开（实测见下方验收 ✓）
                        //   · **接口** ⇒ 复制标签 ⇒ 不释放 ✓（标签别名不计数 ✓）
                        if 免拷贝_新建 {
                            释放字面量源(当前块, 局部表, &源值, true);
                        } else if 是复合类型(&值类型) && !是接口引用类型(&值类型) {
                            释放字面量源(当前块, 局部表, &v, true);
                        }
                    }
                }
                操作数::局部变量(map)
            }
        },
        高层表示表达式::变量引用 { 名称, .. } => {
            // ★§2.4.7（2026-09-19）：**局部优先**（仅对普通裸名）。
            //   `本模块.X`（限定名，由 `解析本模块成员` 产出）⇒ 跳过本块 ⇒ **强制**走全局存储；
            //   普通裸名 ⇒ **先查局部映射**、未命中再查全局 —— 否则函数内同名局部变量（隐式声明/遮蔽/
            //   循环变量）的读取会被全局表劫持（实测：`07 变量遮蔽` 函数内 `数值 = 20` 后读到模块级 10）。
            //   顶层代码里的裸名引用模块变量时无局部同名 ⇒ 仍会回落到全局 ✓。
            if !名称.starts_with("本模块.") {
                if let Some(&idx) = 变量映射.get(名称) {
                    if 当前函数引用局部.with(|s| s.borrow().contains(&idx)) {
                        let tmp = 局部表.len(); 局部表.push(底层表示类型::整数64);
                        当前块.指令列表.push(三地址码 { 结果:操作数::局部变量(tmp), 操作码:操作码::间接加载, 操作数1:操作数::局部变量(idx), 操作数2:None, 调试位置:None, 操作数3: None, });
                        return 操作数::局部变量(tmp);
                    }
                    let 源类型 = 局部表.get(idx).cloned().unwrap_or(底层表示类型::整数64);
                    let tmp = 局部表.len(); 局部表.push(源类型);
                    当前块.指令列表.push(三地址码 { 结果:操作数::局部变量(tmp), 操作码:操作码::加载, 操作数1:操作数::局部变量(idx), 操作数2:None, 调试位置:None, 操作数3: None, });
                    return 操作数::局部变量(tmp);
                }
            }
            // 模块级全局变量：从独立全局存储读取（索引0保留给异常标志，故 +1 偏移）。
            // 此前误用 局部变量(idx)，跨函数访问取到的是调用方自身 frame 的旧值。
            // ★ A3 修复（2026-09-28）：全局槽定位改为「**精确键 + 别名映射归一**」，并删除
            //   「**任意前缀 → 裸名**」兜底。
            //   【为何删】该兜底把 `甲工具.来源标识` 与 `乙工具.来源标识` 都折算到裸名 `来源标识`
            //     的第一条 ⇒ 不同库同名模块的**全局变量互相覆盖**（函数侧从来没有这种兜底：
            //     `解析函数索引` 自 2026-08-30 起只做 `展开别名映射` 归一，其「去点号/取后缀」猜测
            //     已被明确移除）⇒ 二者口径现已一致 ✓。
            //   【为何仍能覆盖全部合法写法】① 被导入模块内部 ⇒ 语义层直接产出精确键 `M.X` ✓；
            //     ② 别名导入 `甲工具.X` ⇒ 精确键即 `甲工具.X` ✓；
            //     ③ 展开导入的裸名 X ⇒ 语义层登记 `X → {前缀}.X` 映射，此处归一后精确命中 ✓；
            //     ④ 主程序 `本模块.X` 标记 ⇒ 确定性折算为裸名键（`本模块` 是入口文件专用标记，
            //        不存在跨文件歧义）✓。
            let 归一后 = {
                let mut 当前 = 名称.clone();
                for _ in 0..32 {
                    let 表 = crate::降级::类型转换::展开别名映射
                        .get_or_init(|| std::sync::Mutex::new(std::collections::HashMap::new()))
                        .lock()
                        .unwrap();
                    match 表.get(&当前).cloned() {
                        Some(全名) if 全名 != 当前 => 当前 = 全名,
                        _ => break,
                    }
                }
                当前
            };
            let 主程序键 = 归一后
                .strip_prefix("本模块.")
                .map(|裸| 裸.to_string());
            let 全局位置 = 全局变量名列表.iter().position(|n| n == &归一后)
                .or_else(|| 主程序键.as_ref().and_then(|裸| 全局变量名列表.iter().position(|n| n == 裸)));
            if let Some(gi) = 全局位置 {
                let tmp = 局部表.len(); 局部表.push(底层表示类型::整数64);
                当前块.指令列表.push(三地址码 { 结果:操作数::局部变量(tmp), 操作码:操作码::加载, 操作数1:操作数::全局变量(gi + 1), 操作数2:None, 调试位置:None, 操作数3: None, });
                return 操作数::局部变量(tmp);
            }
            if let Some(&idx) = 变量映射.get(名称) {
                // 传引用形参：其局部槽位持有 值::局部引用，读取须走 间接加载
                if 当前函数引用局部.with(|s| s.borrow().contains(&idx)) {
                    let tmp = 局部表.len(); 局部表.push(底层表示类型::整数64);
                    当前块.指令列表.push(三地址码 { 结果:操作数::局部变量(tmp), 操作码:操作码::间接加载, 操作数1:操作数::局部变量(idx), 操作数2:None, 调试位置:None, 操作数3: None, });
                    return 操作数::局部变量(tmp);
                }
                // 普通变量读取：加载临时变量类型须与源变量一致（小数变量→小数64），否则后续按类型分派的运算（如 除法）据 局部变量表 误判为「是整数」而错误计算（parity bug 根因）。
                let 源类型 = 局部表.get(idx).cloned().unwrap_or(底层表示类型::整数64);
                let tmp = 局部表.len(); 局部表.push(源类型);
                当前块.指令列表.push(三地址码 { 结果:操作数::局部变量(tmp), 操作码:操作码::加载, 操作数1:操作数::局部变量(idx), 操作数2:None, 调试位置:None, 操作数3: None, });
                操作数::局部变量(tmp)
            } else {
                // 🔧 容错：尝试从当前结构体的参数槽加载（用于未通过 形参列表 传入的结构体参数）
                // ★F17 修复（2026-10-15）：**从后往前**匹配 —— 结构体布局的槽位顺序是
                //   「**字段在前、参数在后**」（见本文件 `创建结构体` 臂 Step①/③：参数填在
                //   `字段数..字段数+参数数`，实测布局名 `["字段一","字段二","字段三","参数甲","参数乙"]`），
                //   而本路径的目标是取**参数**槽 ⇒ **同名（字段名 == 参数名）时必须命中尾部的参数条目** ✓。
                //   **缺陷（旧版取首个命中）**：命中声明**字段**槽（此时该字段正被 Step③ 写入、尚为空值）
                //   ⇒ 读到空值 ✗。最小复现：`结构体 盒(文本 名称): 文本 名称 = 名称` +
                //   `初始化(): 自身.名称 = 自身.名称 + "-改"` ⇒ 双模一致抛「空值不能参与类型转换」✗。
                if let Some(&自身索引) = 变量映射.get("自身") {
                    for (_sname, fields) in 结构体布局.iter() {
                        for (fi, (fn_, _)) in fields.iter().enumerate().rev() {
                            if fn_ == 名称 {
                                let tmp = 局部表.len(); 局部表.push(底层表示类型::指针);
                                当前块.指令列表.push(三地址码 { 结果:操作数::局部变量(tmp), 操作码:操作码::字段加载, 操作数1:操作数::局部变量(自身索引), 操作数2:Some(操作数::立即整数(fi as i64 + 1)), 调试位置:None, 操作数3: None, });
                                return 操作数::局部变量(tmp);
                            }
                        }
                    }
                }
                操作数::函数引用(解析函数索引(名称, 函数索引映射))
            }
        }
        高层表示表达式::函数引用 { 名称, .. } => 操作数::函数引用(解析函数索引(名称, 函数索引映射)),
        高层表示表达式::二元运算 { 左侧, 运算符, 右侧, 位置, .. } => {
            // F-G1: 枚举相等只比较成员标签（成员索引+1）：枚举成员访问用编译期常量，其他(变量引用等)运行时 数组加载[0]，双模一致（修正 §2.4.2 第2982行 枚举 == 判断）
            if matches!(运算符, 高层表示运算符::等于 | 高层表示运算符::不等于) {
                    let 左类型 = 从表达式推断(左侧);
                    let 右类型 = 从表达式推断(右侧);
                if matches!(左类型, 类型信息::枚举(_)) && matches!(右类型, 类型信息::枚举(_)) {
                    let 左标签 = match 左侧.as_ref() {
                        高层表示表达式::枚举成员访问 { 枚举名, 成员索引, .. } => {
                            操作数::立即整数(枚举成员标签(枚举名, *成员索引))
                        }
                        _ => {
                            let v = 转换表达式(左侧, 当前块, 块列表, 块编号, 后续块标识, 局部表, 变量映射, 常量池, 结构体布局, 函数索引映射, 结构体类型索引, 函数签名详情, 全局变量名列表, 匿名函数收集);
                            let t = 局部表.len(); 局部表.push(底层表示类型::整数64);
                            当前块.指令列表.push(三地址码 { 结果:操作数::局部变量(t), 操作码:操作码::数组加载, 操作数1:v, 操作数2:Some(操作数::立即整数(1)), 调试位置:None, 操作数3:None });
                            操作数::局部变量(t)
                        }
                    };
                    let 右标签 = match 右侧.as_ref() {
                        高层表示表达式::枚举成员访问 { 枚举名, 成员索引, .. } => {
                            操作数::立即整数(枚举成员标签(枚举名, *成员索引))
                        }
                        _ => {
                            let v = 转换表达式(右侧, 当前块, 块列表, 块编号, 后续块标识, 局部表, 变量映射, 常量池, 结构体布局, 函数索引映射, 结构体类型索引, 函数签名详情, 全局变量名列表, 匿名函数收集);
                            let t = 局部表.len(); 局部表.push(底层表示类型::整数64);
                            当前块.指令列表.push(三地址码 { 结果:操作数::局部变量(t), 操作码:操作码::数组加载, 操作数1:v, 操作数2:Some(操作数::立即整数(1)), 调试位置:None, 操作数3:None });
                            操作数::局部变量(t)
                        }
                    };
                    let tmp = 局部表.len(); 局部表.push(底层表示类型::整数64);
                    let 比较码 = if matches!(运算符, 高层表示运算符::等于) { 操作码::等于 } else { 操作码::不等于 };
                    当前块.指令列表.push(三地址码 { 结果:操作数::局部变量(tmp), 操作码:比较码, 操作数1:左标签, 操作数2:Some(右标签), 调试位置:None, 操作数3:None });
                    return 操作数::局部变量(tmp);
                }
            }
            // F3: 自定义等于重载——左操作数是定义了 等于 方法的结构体时，== 降级为 左.等于(右) 方法调用（双模式自动受益）；!= 取反。
            if matches!(运算符, 高层表示运算符::等于 | 高层表示运算符::不等于) {
                if let Some(结构名) = 表达式结构体名(左侧) {
                    if 函数签名详情.contains_key(&format!("{}.等于", 结构名)) {
                        let 方法节点 = 高层表示表达式::方法调用 {
                            对象: 左侧.clone(),
                            结构体名: 结构名.clone(),
                            方法名: "等于".to_string(),
                            实参列表: vec![*右侧.clone()],
                            类型: 类型信息::逻辑类型(),
                        };
                        let 结果 = 转换表达式(&方法节点, 当前块, 块列表, 块编号, 后续块标识, 局部表, 变量映射, 常量池, 结构体布局, 函数索引映射, 结构体类型索引, 函数签名详情, 全局变量名列表, 匿名函数收集);
                        if matches!(运算符, 高层表示运算符::不等于) {
                            let tmp = 局部表.len(); 局部表.push(底层表示类型::整数64);
                            当前块.指令列表.push(三地址码 { 结果:操作数::局部变量(tmp), 操作码:操作码::逻辑非, 操作数1:结果, 操作数2:None, 调试位置:None, 操作数3: None });
                            return 操作数::局部变量(tmp);
                        }
                        return 结果;
                    }
                }
            }
            // G9: 且/或短路求值——右操作数仅在必要时求值（与解释器 VM 条件跳转一致，双模 parity）
            if matches!(运算符, 高层表示运算符::且 | 高层表示运算符::或) {
                let 左操作数 = 转换表达式(左侧, 当前块, 块列表, 块编号, 后续块标识, 局部表, 变量映射, 常量池, 结构体布局, 函数索引映射, 结构体类型索引, 函数签名详情, 全局变量名列表, 匿名函数收集);
                let 右块标识 = *块编号; *块编号 += 1;
                let 常量块标识 = *块编号; *块编号 += 1;
                let 汇合块标识 = *块编号; *块编号 += 1;
                let 结果索引 = 局部表.len(); 局部表.push(底层表示类型::整数64);
                let 左常量 = if matches!(运算符, 高层表示运算符::且) { 0i64 } else { 1i64 };
                let (真分支, 假分支) = if matches!(运算符, 高层表示运算符::且) {
                    (右块标识, 常量块标识)
                } else {
                    (常量块标识, 右块标识)
                };
                当前块.终止指令 = 终止指令::条件跳转 { 条件: 左操作数.clone(), 真分支, 假分支 };
                let mut 右块 = 基本块 { 异常目标: 取当前异常目标(), 标识符: 右块标识, 指令列表: vec![], 终止指令: 终止指令::无条件跳转(汇合块标识) };
                let 右操作数 = 转换表达式(右侧, &mut 右块, 块列表, 块编号, 汇合块标识, 局部表, 变量映射, 常量池, 结构体布局, 函数索引映射, 结构体类型索引, 函数签名详情, 全局变量名列表, 匿名函数收集);
                右块.指令列表.push(三地址码 { 结果:操作数::无, 操作码:操作码::存储, 操作数1:操作数::局部变量(结果索引), 操作数2:Some(右操作数), 调试位置:None, 操作数3:None });
                块列表.push(右块);
                let mut 常量块 = 基本块 { 异常目标: 取当前异常目标(), 标识符: 常量块标识, 指令列表: vec![], 终止指令: 终止指令::无条件跳转(汇合块标识) };
                常量块.指令列表.push(三地址码 { 结果:操作数::无, 操作码:操作码::存储, 操作数1:操作数::局部变量(结果索引), 操作数2:Some(操作数::立即逻辑(左常量 != 0)), 调试位置:None, 操作数3:None });
                块列表.push(常量块);
                块列表.push(std::mem::replace(当前块, 基本块 { 异常目标: 取当前异常目标(), 标识符: 汇合块标识, 指令列表: vec![], 终止指令: if 后续块标识 == usize::MAX { 终止指令::返回(None) } else { 终止指令::无条件跳转(后续块标识) } }));
                return 操作数::局部变量(结果索引);
            }
            let 左 = 转换表达式(左侧, 当前块, 块列表, 块编号, 后续块标识, 局部表, 变量映射, 常量池, 结构体布局, 函数索引映射, 结构体类型索引, 函数签名详情, 全局变量名列表, 匿名函数收集);
            let 右 = 转换表达式(右侧, 当前块, 块列表, 块编号, 后续块标识, 局部表, 变量映射, 常量池, 结构体布局, 函数索引映射, 结构体类型索引, 函数签名详情, 全局变量名列表, 匿名函数收集);
            let 码 = match 运算符 {
                高层表示运算符::加 => 操作码::加法, 高层表示运算符::减 => 操作码::减法, 高层表示运算符::乘 => 操作码::乘法, 高层表示运算符::除 => 操作码::除法,
                高层表示运算符::整除 => 操作码::整除, 高层表示运算符::取余 => 操作码::取余, 高层表示运算符::幂 => 操作码::幂, 高层表示运算符::等于 => 操作码::等于,
                高层表示运算符::不等于 => 操作码::不等于, 高层表示运算符::大于 => 操作码::大于, 高层表示运算符::小于 => 操作码::小于,
                高层表示运算符::大于等于 => 操作码::大于等于, 高层表示运算符::小于等于 => 操作码::小于等于,
                高层表示运算符::实例相等 => 操作码::实例相等, 高层表示运算符::实例不等 => 操作码::实例不等,
                高层表示运算符::且 => 操作码::逻辑与, 高层表示运算符::或 => 操作码::逻辑或,
                高层表示运算符::属于 => 操作码::属于, 高层表示运算符::不属于 => 操作码::不属于,
                高层表示运算符::位与 => 操作码::位与, 高层表示运算符::位或 => 操作码::位或, 高层表示运算符::异或 => 操作码::异或,
                高层表示运算符::位非 => 操作码::位非, 高层表示运算符::左移 => 操作码::左移, 高层表示运算符::右移 => 操作码::右移,
            };
            // ── 结果临时变量类型登记 ──
            // 算术运算（加/减/乘/除/幂）当任一操作数为小数时结果为小数，否则整数；
            // 比较/逻辑/位运算结果恒为整数（逻辑以整数位模式表示）。
            // 此前一律登记为 整数64，导致小数运算结果在局部变量表中被标记为整数，
            // 后续读取（如 返回 该结果）按整数处理，与解释器（运行时按 tag 判定）不一致（parity bug 根因）。
            let 操作数是否小数 = |op: &操作数| -> bool {
                match op {
                    操作数::立即小数(_) => true,
                    操作数::局部变量(i) => matches!(局部表.get(*i), Some(底层表示类型::小数64)),
                    _ => false,
                }
            };
            let 结果类型 = match 码 {
                // ⚡双模式⚡: 除法(/) 自 W 系列语义变更后恒返回小数，与操作数类型无关（整数/整数→小数、整数/小数→小数、小数/小数→小数）。
                // 此前按「任一操作数为小数→小数」推导，导致 7/2 这类 整数/整数 除法被误标为 整数64，
                // 触发两后端寄存器具体化 bug（解释器读到未初始化寄存器=空值，编译模式对应寄存器亦失效），
                // 进而 7/2 == 3.5 等比较失败。此处强制 除法→小数64 为唯一真相。
                操作码::除法 => 底层表示类型::小数64,
                // 取余(%) 跟随操作数类型：任一操作数为小数→小数（运行时 堆_取余 返回非负小数余数），
                // 否则→整数（数学非负余数）。此前误归入 `_ => 整数64`，致 5.5 % 2 被标整数64、
                // 小数余数 1.5 按整数槽存放→位模式损坏（与 翻译执行器.rs 记录结果类型 双模同修）。
                操作码::加法 | 操作码::减法 | 操作码::乘法 | 操作码::幂 | 操作码::取余 => {
                    if 操作数是否小数(&左) || 操作数是否小数(&右) { 底层表示类型::小数64 } else { 底层表示类型::整数64 }
                }
                // 整除(%%) 恒返回整数（与操作数类型无关）
                _ => 底层表示类型::整数64,
            };
            let tmp = 局部表.len(); 局部表.push(结果类型);
            let 调试位置 = if matches!(&码, 操作码::除法|操作码::整除|操作码::取余) { Some(位置.clone()) } else { None };
            let 指令 = 三地址码 { 结果:操作数::局部变量(tmp), 操作码:码, 操作数1:左.clone(), 操作数2:Some(右.clone()), 调试位置, 操作数3: None };
            当前块.指令列表.push(指令);
            // 🆕 2026-09-22（**阶段 1a-2**）：消费后释放"**确定新建**"的操作数**临时槽**（引用计数闭环）
            //   背景（实测）：`结果 = "锚" + 转文本(计数)` 中，**内层 `转文本`** 的临时槽此前无人 −1
            //     ⇒ 每轮泄漏 1 个文本。探针 `I_字面量循环_300`：修复前 604 → 阶段 1a 后 **303**
            //     ⇒ 残留 301 恰为"内嵌临时"（1/轮，两引擎相同）。
            //   ⚠ **安全边界（与阶段 1a 红线同源）**：
            //     ① 只释放判定为"**确定新建**"的操作数（白名单：`+` 拼接 / 文本转换类标准库，
            //        见 `是新建文本表达式`）；字面量/变量/字段/索引/方法调用/用户函数一律**不释放**（借用）✓
            //     ② **只做二元运算操作数**，**不做调用实参** —— 被调方可能按"借用"把文本存入
            //        容器/模块全局变量（那些路径不一定 +1）⇒ 在调用点释放会悬垂 ✗（宁可泄漏）
            //     ③ 只在操作数是**局部槽**时释放（立即值/常量无槽可放）✓
            //   ⚠ 顺序：必须在**消费该操作数的指令之后**（指令已读取其值）✓
            //   ⚠ 左/右为**同一槽**时只释放一次（避免双 −1）✓
            let 左槽 = if let 操作数::局部变量(v) = &左 { Some(*v) } else { None };
            let 右槽 = if let 操作数::局部变量(v) = &右 { Some(*v) } else { None };
            if 是新建文本表达式(左侧) {
                if let Some(v) = 左槽 {
                    if Some(v) != 右槽 { 发射释放槽(当前块, 局部表, v); }
                }
            }
            if 是新建文本表达式(右侧) {
                if let Some(v) = 右槽 { 发射释放槽(当前块, 局部表, v); }
            }
            操作数::局部变量(tmp)
        }
        高层表示表达式::调用 { 函数名, 实参列表, 类型, 位置 } => {
            // 全局函数（名称唯一，不重载）：签名详情直接取自 函数签名详情
            let mut 完整实参: Vec<高层表示表达式> = 实参列表.clone();
            let (形参数量, 默认值列表) = if let Some(&(n, ref d, _, _)) = 函数签名详情.get(函数名.as_str()) {
                (n, d.clone())
            } else { (0, vec![]) };
            while 完整实参.len() < 形参数量 {
                let 缺失位置 = 完整实参.len();
                if let Some(Some(默认表达式)) = 默认值列表.get(缺失位置) {
                    完整实参.push(默认表达式.clone());
                } else {
                    break; // 无默认值，不再填充
                }
            }
            // ── 任务专用操作码（文档 5.7.2）：并发.启动任务/并发.批量等待 —— 直接发射专用指令而非CALL
            // 性能优化：参照 Go 编译器的做法，任务调度操作不经过 CALL 开销，直接映射为 VM 专用 opcode
            if crate::标准库元数据::是零开销发射(&函数名) {
                // ── 单源（2026-08-30 彻底单源重构）：opcode 选择（含「按实参个数」重载）
                //    由 标准库元数据表 派生，取代此处硬编码 match。
                let 任务操作码 = crate::标准库元数据::查操作码(函数名, 完整实参.len())
                    .expect("并发.启动任务/批量等待 必须在标准库元数据表注册专用操作码");
                let 参数操作数 = if !完整实参.is_empty() {
                    转换表达式(&完整实参[0], 当前块, 块列表, 块编号, 后续块标识, 局部表, 变量映射, 常量池, 结构体布局, 函数索引映射, 结构体类型索引, 函数签名详情, 全局变量名列表, 匿名函数收集)
                } else { 操作数::立即空值 };
                let 参数操作数2 = if 完整实参.len() >= 2 {
                    Some(转换表达式(&完整实参[1], 当前块, 块列表, 块编号, 后续块标识, 局部表, 变量映射, 常量池, 结构体布局, 函数索引映射, 结构体类型索引, 函数签名详情, 全局变量名列表, 匿名函数收集))
                } else { None };
                let ret = 局部表.len(); 局部表.push(底层表示类型::空值);
                当前块.指令列表.push(三地址码 { 结果:操作数::局部变量(ret), 操作码:任务操作码, 操作数1:参数操作数.clone(), 操作数2:参数操作数2, 调试位置:None, 操作数3: None, });
                // 🔁 2026-09-24（**D1：任务启动实参记账**）★ —— 配 base「**接收方自持 +1 / 结束 −1**」的正解：
                //   ① **base 侧**：`并发启动任务` 对交给任务的对象**自持 +1**，任务结束再 **−1**
                //      ⇒ 任务异步读取期间，对象**由任务侧引用兜底**，调用方释放不会造成悬垂 ✓✓
                //      （这正是此前后端**编译模式 TIMEOUT** 的根治：先前只有"调用点 −1"、无接收方 +1 ⇒ 提前回收 ✗）
                //   ② **前端侧（本处）**：闭包字面量等**自有右值**实参（现场新建、无他人持有）⇒ 调用后 −1 ✓
                //      否则**每启动一个任务泄漏一个 `闭包环境`** —— `115` 实测 `闭包环境 = 280` 恰等于
                //      三段"任务启动"次数（200 + 50 + 30）✓✓ 算术证实 ✓
                //   ⚠ 门控与 K/M/N 同款：**只收"自有右值"**（新建值 / 闭包字面量 / 用户函数调用结果）；
                //     变量引用（如 `批量等待(句柄列)` 的句柄列表）等**借用型**实参一律不收 ✓
                if !完整实参.is_empty()
                    && (是新建值(&完整实参[0])
                        || matches!(完整实参[0], 高层表示表达式::匿名函数(_))
                        || 是用户函数调用(&完整实参[0], 函数签名详情))
                {
                    if let 操作数::局部变量(槽) = 参数操作数 {
                        发射释放槽(当前块, 局部表, 槽);
                    }
                }
                return 操作数::局部变量(ret);
            }
            // ── 单源（2026-08-30 彻底单源重构）：「名→操作码」由 标准库元数据表 派生。
            //    原此处 45 行手写 match 是第三张真相表（与 公共降级.rs::内置索引 重复、易漂移），已删除。
            //    新增容器/文本/转换方法只需在 标准库元数据.rs 加一条，此处无需改动。
            let 直接操作码 = crate::标准库元数据::按base名查操作码(函数名, 完整实参.len());
            if let Some(操作码) = 直接操作码 {
                // 直接生成寄存器操作码指令，不走CALL
                let mut 参数操作数: Vec<操作数> = Vec::new();
                // 记录首参数原始寄存器索引（用于COW写回）
                let mut 首参原始索引: Option<usize> = None;
                // 首参数是否为传引用形参（需走 间接加载/间接存储）
                let mut 首参是引用 = false;
                // ⚡双模式⚡ A2: 检测首参数是否为「字段访问」接收者（如 `自身.交易记录.追加(x)`），
                // 若是则变异操作（数组追加/字段存储等）的结果需写回该字段，而非仅作用于副本。
                // （当前写回改由 发射字段接收者写回 统一处理，此处仅保留提取逻辑供诊断；实际调用传 完整实参.get(0)。）
                let _接收者字段访问: Option<(Box<高层表示表达式>, usize)> = match 完整实参.get(0) {
                    Some(高层表示表达式::字段访问 { 对象, 字段索引, .. }) => Some((对象.clone(), *字段索引)),
                    _ => None,
                };
                for (i, arg) in 完整实参.iter().enumerate() {
                    if let 高层表示表达式::变量引用 { 名称, .. } = arg {
                        if let Some(&原始索引) = 变量映射.get(名称) {
                            // 传引用接收者：间接加载取得实际对象，COW写回改走 间接存储
                            if 当前函数引用局部.with(|s| s.borrow().contains(&原始索引)) {
                                let tmp = 局部表.len(); 局部表.push(底层表示类型::整数64);
                                当前块.指令列表.push(三地址码 { 结果:操作数::局部变量(tmp), 操作码:操作码::间接加载, 操作数1:操作数::局部变量(原始索引), 操作数2:None, 调试位置:None, 操作数3: None, });
                                参数操作数.push(操作数::局部变量(tmp));
                                if i == 0 { 首参原始索引 = Some(原始索引); 首参是引用 = true; }
                                continue;
                            }
                            let tmp = 局部表.len(); 局部表.push(局部表.get(原始索引).cloned().unwrap_or(底层表示类型::整数64));
                            当前块.指令列表.push(三地址码 { 结果:操作数::局部变量(tmp), 操作码:操作码::加载, 操作数1:操作数::局部变量(原始索引), 操作数2:None, 调试位置:None, 操作数3: None, });
                            参数操作数.push(操作数::局部变量(tmp));
                            if i == 0 { 首参原始索引 = Some(原始索引); }
                            continue;
                        }
                    }
                    let op = 转换表达式(arg, 当前块, 块列表, 块编号, 后续块标识, 局部表, 变量映射, 常量池, 结构体布局, 函数索引映射, 结构体类型索引, 函数签名详情, 全局变量名列表, 匿名函数收集);
                    参数操作数.push(op);
                }
                // 提前判断是否为变异操作（在操作码被move前）
                let 是存储类 = matches!(操作码, 操作码::映射存储);  // 仅映射存储需走CALL
                // ⚡双模式⚡ 单源判定：覆盖 opcode 路径 + 方法名后缀（统一治分叉）
                let 是变异操作 = 是字段变异写回(&函数名, &操作码);
                let ret = 局部表.len(); 局部表.push(底层表示类型::空值);
                let src1 = 参数操作数.first().cloned().unwrap_or(操作数::立即空值);
                // 数组下标语义（规范：数组索引从1开始）：用户 数组[索引] 直接 1-based 透传运行时
                // （运行时 堆_数组加载/堆_数组存储 读 v[索引-1]，故用户索引 1 = 首元素 v[0]）。
                // 不再做 +1 桥接。枚举/闭包成员比较的 数组加载 由前端直接发射硬编码索引（不经此路径），不受影响。双模统一。
                let src2 = if matches!(操作码, 操作码::数组加载 | 操作码::数组存储) {
                    match 参数操作数.get(1).cloned() {
                        Some(操作数::立即整数(n)) => Some(操作数::立即整数(n)),
                        Some(其它) => Some(其它),
                        None => None,
                    }
                } else {
                    参数操作数.get(1).cloned()
                };
                // 三元操作码（数组存储/数组插入/映射存储/文本截取/文本替换/容器插入/索引存储）需要第三操作数。
                // 单一真相：判定集中到 操作码::需要第三操作数()，新增三元 opcode 只改指令集.rs 一处。
                let 是三元 = 操作码.需要第三操作数();
                let src3 = if 是三元 { 参数操作数.get(2).cloned() } else { None };
                if 是存储类 {
                    let idx = 解析函数索引(函数名, 函数索引映射);
                    for param_op in &参数操作数 {
                        当前块.指令列表.push(三地址码 { 结果:操作数::无, 操作码:操作码::加载, 操作数1:param_op.clone(), 操作数2:None, 调试位置:None, 操作数3: None, });
                    }
                    当前块.指令列表.push(三地址码 { 结果:操作数::局部变量(ret), 操作码:操作码::调用, 操作数1:操作数::函数引用(idx), 操作数2:None, 调试位置:Some(位置.clone()), 操作数3: None, });
                    // 存储类也需要 COW 写回：
                    //   - 变量引用接收者：经 存储/间接存储 写回调用方变量（映射传引用失效修复）
                    //   - 字段访问接收者（如 `自身.数据.插入(k,v)`）：必须写回该字段，
                    //     否则 映射存储 返回的新句柄(new_map)未落回 自身.数据，字段仍指向旧空映射（长度=0）。
                    if 是变异操作 {
                        if let Some(原始索引) = 首参原始索引 {
                            // 传引用接收者：经 间接存储 写回调用方变量（与数组等非存储类路径一致），
                            // 否则只写进参数自身槽位、调用方看不到改动（映射传引用失效）。
                            let 写回操作码 = if 首参是引用 { 操作码::间接存储 } else { 操作码::存储 };
                            当前块.指令列表.push(三地址码 {
                                结果: 操作数::无,
                                操作码: 写回操作码,
                                操作数1: 操作数::局部变量(原始索引),
                                操作数2: Some(操作数::局部变量(ret)),
                                调试位置: None,
                            操作数3: None, });
                        }
                        // ⚡双模式⚡ 字段访问接收者（如 `自身.数据.插入(k,v)`）COW 写回：委托单源函数
                        // 注意：传完整接收者表达式（自身.姓名表），由单源函数递归解 对象+字段索引。
                        if let Some(接收者表达式) = 完整实参.get(0) {
                            发射字段接收者写回(接收者表达式, 操作数::局部变量(ret), 当前块, 块列表, 块编号, 后续块标识, 局部表, 变量映射, 常量池, 结构体布局, 函数索引映射, 结构体类型索引, 函数签名详情, 全局变量名列表, 匿名函数收集);
                        }
                    }
                } else if src2.is_some() || src3.is_some() {
                    // ⚡值语义 + RC 平衡（2026-09-21）⚡ 全部**值存储类** opcode 的 base 实现都对**写入值** +1
                    //   （容器/结构体获得一份引用）：索引存储/数组存储（`容器[i] = 值`）、
                    //   数组追加（`.追加(值)`）、数组插入（`.插入(i, 值)`）、容器插入（`.插入(键, 值)`）。
                    //   两条纪律（与 赋值 臂 同源，保证双模 parity）：
                    //   ① **值语义**：写入值须为**独立对象**。新建值（`创建结构体`/复合字面量）本身即独立；
                    //      **既有值**（变量/形参/字段…）须先 **深度复制**，否则与源共享 ⇒ 元素被写入时触发
                    //      COW 分离，而新句柄**无法写回容器元素** ⇒ 修改丢失（实测 `丁.追加(戊); 丁[2].移动(74)`
                    //      读回 4）。深拷贝后元素独占对象 ⇒ 原地修改生效 ⇒ 与 `赋值` 路径语义一致。
                    //   ② **RC 平衡**：容器对写入值 +1 ⇒ 语句持有的这一份（新建值或深拷贝副本）须在存储后 −1，
                    //      否则计数永久虚高 1 ⇒ 后续写入触发 COW 分离丢失修改（实测：索引赋值 85→4、
                    //      `.追加` 70→1、`.插入` 71→2，双模一致）。
                    //   仅动**写入值**实参；接收者/索引/键等其它实参不触碰。
                    let 值存储偏移 = match 操作码 {
                        操作码::索引存储 | 操作码::数组存储 | 操作码::数组插入 | 操作码::容器插入 => Some(2),
                        操作码::数组追加 => Some(1),
                        _ => None,
                    };
                    let mut src2 = src2;
                    let mut src3 = src3;
                    let mut 待释放写入值: Option<操作数> = None;
                    if let Some(vi) = 值存储偏移 {
                        if let Some(值实参) = 完整实参.get(vi) {
                            let 值实参类型 = 从表达式推断(值实参);
                            // ⚠ **容器元素恒为独立副本**（规范 §4993-5001）：`列表 = [车甲]` ⇒ 复制数据，
                            //   槽位是**独立副本**、与 `车甲` 互不影响 ⇒ 写入值**一律值语义复制**，
                            //   **不因元素类型是接口而改走"复制标签"**（那会使槽位与源实例共享 ⇒ 违反规范）。
                            if 是复合类型(&值实参类型) {
                                let 原操作数 = if vi == 1 { src2.clone() } else { src3.clone() };
                                if let Some(原) = 原操作数 {
                                    let 新建 = matches!(值实参, 高层表示表达式::创建结构体 { .. }) || 是复合字面量(值实参);
                                    let 写入值 = if 新建 {
                                        原
                                    } else {
                                        发射深拷贝_类型感知(当前块, 块列表, 块编号, 局部表, 原, &值实参类型, true, 结构体类型索引)
                                    };
                                    if vi == 1 { src2 = Some(写入值.clone()); } else { src3 = Some(写入值.clone()); }
                                    待释放写入值 = Some(写入值);
                                }
                            }
                        }
                    }
                    当前块.指令列表.push(三地址码 { 结果:操作数::局部变量(ret), 操作码, 操作数1:src1, 操作数2:src2, 操作数3:src3, 调试位置:Some(位置.clone()) });
                    if let Some(写入值) = 待释放写入值 {
                        释放字面量源(当前块, 局部表, &写入值, true);
                    }
                } else {
                    当前块.指令列表.push(三地址码 { 结果:操作数::局部变量(ret), 操作码, 操作数1:src1, 操作数2:None, 操作数3:None, 调试位置:Some(位置.clone()) });
                }
                // COW 写回：对于返回新堆ID的变异操作，将结果写回源变量/源字段
                if 是变异操作 && !是存储类 {
                    if let Some(原始索引) = 首参原始索引 {
                        if 首参是引用 {
                            // 传引用接收者：经 间接存储 写回调用方变量
                            当前块.指令列表.push(三地址码 {
                                结果: 操作数::无,
                                操作码: 操作码::间接存储,
                                操作数1: 操作数::局部变量(原始索引),
                                操作数2: Some(操作数::局部变量(ret)),
                                调试位置: None,
                            操作数3: None, });
                        } else {
                            当前块.指令列表.push(三地址码 {
                                结果: 操作数::无,
                                操作码: 操作码::存储,
                                操作数1: 操作数::局部变量(原始索引),  // dest
                                操作数2: Some(操作数::局部变量(ret)),  // source value
                                调试位置: None,
                            操作数3: None, });
                        }
                    }
                    // ⚡双模式⚡ A2: 字段访问接收者（如 `自身.交易记录.追加(x)`）的变异结果写回：委托单源函数
                    // 注意：传完整接收者表达式（自身.交易记录），由单源函数递归解 对象+字段索引。
                    if let Some(接收者表达式) = 完整实参.get(0) {
                        发射字段接收者写回(接收者表达式, 操作数::局部变量(ret), 当前块, 块列表, 块编号, 后续块标识, 局部表, 变量映射, 常量池, 结构体布局, 函数索引映射, 结构体类型索引, 函数签名详情, 全局变量名列表, 匿名函数收集);
                    }
                }
                return 操作数::局部变量(ret);
            }
            // V3: 收集所有参数的 LIR 操作数（含默认值填充后的完整参数）
            // 传引用：被调形参为 传引用 时，实参须取调用方变量地址（取地址），而非加载其值
            // 🆕 FFI: 是否外部函数——须在实参降级（深拷贝判定）之前确定；跨模块限定名先剥模块前缀。
            // 跨模块调用外部函数时（如 `界面.呈现窗口`），函数名带模块前缀，
            // 而 当前外部函数集 / 函数索引映射 存的都是外部块声明的名字（`呈现窗口`）。
            let 是外部 = 当前外部函数集.with(|s| {
                let 集合 = s.borrow();
                if 集合.contains(函数名.as_str()) {
                    true
                } else if 函数名.contains('.') {
                    集合.contains(函数名.split('.').last().unwrap_or(函数名.as_str()))
                } else {
                    // 🆕 2026-09-22 F1 修复（兜底）：集合内可能是**限定名**（`样例库.加法`）而调用点是裸名
                    //   ⇒ 反向按「末段裸名」比对（与上面正向比对对称，双向都命中）。
                    集合.iter().any(|名| 名.rsplit('.').next() == Some(函数名.as_str()))
                }
            });
            let 被调签名 = 函数签名详情.get(函数名.as_str()).map(|(_, _, m, t)| (m.clone(), t.clone()));
            let 被调传递方式 = 被调签名.as_ref().map(|(m, _)| m.clone());
            let 被调形参类型 = 被调签名.map(|(_, t)| t);
            let mut 参数操作数列表: Vec<操作数> = Vec::new();
            let mut 回拷列表: Vec<(usize, usize)> = Vec::new();  // (被引用原始索引, 取地址临时索引)
            // 🔁 2026-09-24（**soak M/K 形状修复**）：**调用方自持的复合实参**须在**调用返回后** −1。
            //   依据（前端所有权规则，与"形参从不登记"配套）：
            //     · **形参 = 借用**（`函数转换.rs` 明示"形参从不登记 ⇒ 释放形参引用本就不可能"）；
            //     · 而调用点为**值语义**须为被调方准备一份**深拷贝副本**（复合类型、可能被别名持有）
            //       ⇒ 被调方借用完毕后，**这份副本由调用方负责 −1**（否则逐轮泄漏：实测 M `消耗(列)` **+1/轮**）；
            //     · 实参为**新建值**（字面量 / 构造）时免拷贝 ⇒ 调用方**自持该新建对象** ⇒ 调用后同样 −1 ✓
            //   实测 K `消耗(造列(计数))` **+2/轮** = 「造列 返回的源临时」+「调用点副本」各 1 ✓
            //   ⚠ 释放**必须在 CALL 之后**（被调方借用期间不得回收）✓；传引用 / 接口 / 只读检视 / FFI 数组
            //     实参一律**不**入此表（它们本就共享句柄、无副本）✓
            let mut 调用后释放槽: Vec<usize> = Vec::new();
            // 🆕 2026-09-22 **只读检视型系统函数 ⇒ 复合类型实参跳过深拷贝**（见 `是只读检视系统函数` 注释）：
            //   修"每次接口方法调用泄漏 1 个结构体副本"——生成的接口分发适配函数 `__接口分发_*` 拥有型槽为空，
            //   而对 `取结构体类型索引(__对象)` 的实参深拷贝出的副本**无人释放** ⇒ 逐调用泄漏 ✓
            let 只读检视 = 是只读检视系统函数(函数名.as_str());
            for (i, arg) in 完整实参.iter().enumerate() {
                let 是引用 = 被调传递方式.as_ref().and_then(|m| m.get(i)) == Some(&参数传递方式::传引用);
                // 接口型形参按引用语义传递：接口方法需在原实例上原地修改，
                // 故实参仅传句柄（指针），绝不深拷贝原实例（否则方法修改只作用于副本）。
                let 形参是接口 = 被调形参类型.as_ref().and_then(|t| t.get(i)).map(是接口引用类型).unwrap_or(false);
                if 是引用 {
                    if let 高层表示表达式::变量引用 { 名称, .. } = arg {
                        if let Some(&原始索引) = 变量映射.get(名称) {
                            let tmp = 局部表.len(); 局部表.push(底层表示类型::整数64);
                            当前块.指令列表.push(三地址码 { 结果:操作数::局部变量(tmp), 操作码:操作码::取地址, 操作数1:操作数::局部变量(原始索引), 操作数2:None, 调试位置:None, 操作数3: None, });
                            参数操作数列表.push(操作数::局部变量(tmp));
                            回拷列表.push((原始索引, tmp));
                            continue;
                        }
                    }
                    // 非变量实参不能以传引用方式传递（语义应在分析期报错）；此处退回值传递以保证不崩溃
                }
                if let 高层表示表达式::变量引用 { 名称, .. } = arg {
                    if let Some(&原始索引) = 变量映射.get(名称) {
                        // 接口型参数按【值传句柄】：接口变量存储的是指向实例的句柄（引用语义），
                        // 复制句柄即共享同一实例，零数据复制。此处【不得取地址】——若取地址，
                        // 被调函数形参槽位存的是"引用单元"，thunk 内再 间接加载 解引用一次后，
                        // 传给具体结构体方法的 self 就是"引用单元"而非实例句柄，导致
                        // `自身.字段=...` 把字段写入引用单元，原实例不被修改（parity bug）。
                        let tmp = 局部表.len(); 局部表.push(局部表.get(原始索引).cloned().unwrap_or(底层表示类型::整数64));
                        当前块.指令列表.push(三地址码 { 结果:操作数::局部变量(tmp), 操作码:操作码::加载, 操作数1:操作数::局部变量(原始索引), 操作数2:None, 调试位置:None, 操作数3: None });
                        let 需拷贝_变量实参 = !是引用 && !形参是接口 && !只读检视
                            && 是复合类型(&从表达式推断(arg)) && !是新建值(arg)
                            && !(是外部 && 是外部数组形参(函数名, i));
                        let 拷后 = 发射深拷贝_类型感知(当前块, 块列表, 块编号, 局部表, 操作数::局部变量(tmp), &从表达式推断(arg), 需拷贝_变量实参, 结构体类型索引);
                        if 需拷贝_变量实参 {
                            if let 操作数::局部变量(槽) = 拷后 { 调用后释放槽.push(槽); }
                        }
                        参数操作数列表.push(拷后);
                        continue;
                    }
                }
                let op = 转换表达式(arg, 当前块, 块列表, 块编号, 后续块标识, 局部表, 变量映射, 常量池, 结构体布局, 函数索引映射, 结构体类型索引, 函数签名详情, 全局变量名列表, 匿名函数收集);
                if 是引用 {
                    // 传引用形参（thunk __object / 方法 self）且实参非变量引用（数组元素/字段访问/其它）：
                    // 先加载到临时再取地址，创建引用单元，使被调方内 间接加载 能解引用得到真实句柄，
                    // 从而原地修改作用于共享实例（数组槽位等接收者随之更新）。
                    let tmp = 局部表.len(); 局部表.push(底层表示类型::整数64);
                    当前块.指令列表.push(三地址码 { 结果:操作数::局部变量(tmp), 操作码:操作码::加载, 操作数1:op.clone(), 操作数2:None, 调试位置:None, 操作数3: None, });
                    let addr = 局部表.len(); 局部表.push(底层表示类型::整数64);
                    当前块.指令列表.push(三地址码 { 结果:操作数::局部变量(addr), 操作码:操作码::取地址, 操作数1:操作数::局部变量(tmp), 操作数2:None, 调试位置:None, 操作数3: None, });
                    参数操作数列表.push(操作数::局部变量(addr));
                } else if 形参是接口 {
                    // 接口型参数传句柄值（非变量引用场景如 数组元素/字段访问）：仅加载句柄，不取地址
                    参数操作数列表.push(op);
                } else {
                    let 推断实参类型 = 从表达式推断(arg);
                    let 需拷贝_其它实参 = !是引用 && !只读检视 && 是复合类型(&推断实参类型)
                        && !是新建值(arg) && !(是外部 && 是外部数组形参(函数名, i));
                    let 拷后 = 发射深拷贝_类型感知(当前块, 块列表, 块编号, 局部表, op.clone(), &推断实参类型, 需拷贝_其它实参, 结构体类型索引);
                    if 需拷贝_其它实参 {
                        // 🔁 2026-09-24：**副本**由调用方在调用返回后 −1 ✓
                        if let 操作数::局部变量(槽) = 拷后 { 调用后释放槽.push(槽); }
                        // 🔁 2026-09-24（K 收尾）：实参为**调用方自持的自有右值**（`字面量` / **用户函数调用结果**）
                        //   时，深拷贝之后**源临时也须 −1**（与声明/赋值臂 `释放字面量源` 同款规则：
                        //   `需要_实际 && (是复合字面量 || 是用户函数调用)` ✓）
                        if 是复合字面量(arg) || 是用户函数调用(arg, 函数签名详情) {
                            if let 操作数::局部变量(槽) = op { 调用后释放槽.push(槽); }
                        }
                    } else if !是引用 && !只读检视 && 是复合类型(&推断实参类型) && 是新建值(arg) {
                        // 🔁 2026-09-24：**免拷贝**（新建值 ⇒ 调用方自持该新建对象）⇒ 调用后释放**源临时** ✓
                        if let 操作数::局部变量(槽) = op { 调用后释放槽.push(槽); }
                    } else if !是引用 && !只读检视
                        && (是新建文本表达式(arg) || 是并发新建返回值(arg))
                        && 是深转不保留名(函数名)
                    {
                        // 🔁 2026-09-25（**与 `方法调用` 路径同款修正**）：本分支原本含 `!形参是接口`，
                        //   而 `通道.发送` 的载荷形参类型是**动态**（接口/任意）⇒ 门控恒真 ⇒ 从不发射 ✗
                        //   详见 `方法调用` 路径同位注释（含 `F12` 的 +1/轮 实测证据）✓
                        // 🔁 2026-09-24（**item 7 发送实参侧 · 白名单化**）：被调方**同步深转**、
                        //   调用返回后**不再引用**调用方对象（`是实参深转不保留内置` 已核实项）⇒
                        //   **自有右值**文本实参（`转文本(..)` / 拼接 / 并发新建返回值）调用后 −1 ✓
                        //   ⚠ **必须白名单**：泛化到"所有调用"实测致 `总网络模块全面测试`（解释）
                        //     `悬垂(拥有型)=5` ✗（网络类内置经**任务异步持有**、交接处未 +1 ⇒ 与 D1 同源）
                        //     ⇒ 依铁律「宁可泄漏，绝不误回收」仅收已核实项 ✓
                        if let 操作数::局部变量(槽) = op { 调用后释放槽.push(槽); }
                    } else if !是引用 && 只读检视
                        && (是新建值(arg)
                            || 是新建文本表达式(arg)
                            || 是用户函数调用(arg, 函数签名详情)
                            || 是并发新建返回值(arg))
                    {
                        // 🔁 2026-09-25（**只读检视 + 自有右值 ⇒ 调用后释放源临时**）★★ 修 `T` 形状回归：
                        //   只读检视 ⇒ **跳过深拷贝**（首条分支 `需拷贝_其它实参` 含 `!只读检视`）
                        //   ⇒ 实参以**原对象**传入（该对象由**调用方自持**）⇒ 若它是**自有右值**
                        //     （新建值 / 文本新建 / 用户函数调用结果 / 并发新建返回值）⇒ **调用后必须 −1**，
                        //     否则该临时**无人释放** ⇒ 逐轮泄漏 ✗
                        //   **实测（soak 门禁立功）**：把 `转文本` 纳入只读检视表后，
                        //     `T_映射渲染嵌套字面量`（`中转 = 转文本({"甲":计数,"乙":{"丙":计数}})`）
                        //     由**完全平坦** → **+2/轮（差 18000）** ✗ ⇒ 即本条缺失所致 ✓
                        //   ⚠ 安全性：只读检视 = **只读取、不存储/不返回/不共享**（既有收录标准 ✓）
                        //     + 实参为**自有右值**（非借用别名）⇒ −1 安全 ✓（借用型一律不收 ✓）
                        if let 操作数::局部变量(槽) = op { 调用后释放槽.push(槽); }
                    }
                    参数操作数列表.push(拷后);
                }
            }
            // 现在安全地嵌入CALL和参数（不会被刷新缓冲清掉）
            // ⚡双模式⚡ A1/A3 闭包变量优先：若 函数名 是局部变量（闭包句柄），一律走 间接调用，
            // 否则再按函数索引解析。闭包（乘积 = 函数(...)）被语义层同时登记为函数与变量时，
            // 若不优先判定变量，会误把闭包调用发射成 操作码::调用（指向内置 fn），导致编译模式参数计数错位（case 11）。
            // ★F3 修复（2026-10-14，规范 5875）：**精化「闭包变量优先」判据** ——
            //   本节原逻辑「函数名是局部变量 ⇒ 一律间接调用」会**误伤显式限定的模块函数调用** ✗。
            //   场景（实测 C/P2）：函数内 `求和 = 5` 遮蔽了模块级函数 `求和`（§2.4.7 允许），
            //   随后 `本模块.求和(41)`（规范 5875 的"显式访问被遮蔽的模块成员"）在语义层正确发射
            //   `调用{函数名:"求和"}` ✓，但此处因 `变量映射` 命中**同名局部**（整数 5）⇒ 发射
            //   `间接调用`（经局部槽）⇒ **运行期返回空值** ✗（未捕获异常: 空值不能参与类型转换）。
            //   判据精化：只有同名局部**确实是闭包句柄**（槽类型 = `函数指针`）时才走间接调用 ✓；
            //   否则（普通值局部 ⇒ 遮蔽情形）落到下方**函数索引**⇒ 正确调用模块函数 ✓。
            //   安全性：语义层对可调用变量已发射 `间接调用`（`表达式分析` 的可调用类型判定 ✓），
            //   仅"类型未推断的闭包变量 + 裸名调用"才依赖本兜底，而该形态的槽类型正是 `函数指针` ✓。
            let 同名局部是闭包句柄 = 变量映射
                .get(函数名.as_str())
                .map_or(false, |&槽| 局部表.get(槽).map_or(false, |t| *t == 底层表示类型::函数指针));
            if 同名局部是闭包句柄 {
                let var_idx = *变量映射.get(函数名.as_str()).unwrap();
                let ret = 局部表.len(); 局部表.push(底层表示类型::空值);
                for param_op in &参数操作数列表 {
                    当前块.指令列表.push(三地址码 { 结果:操作数::无, 操作码:操作码::加载, 操作数1:param_op.clone(), 操作数2:None, 调试位置:None, 操作数3: None, });
                }
                当前块.指令列表.push(三地址码 { 结果:操作数::局部变量(ret), 操作码:操作码::间接调用, 操作数1:操作数::局部变量(var_idx), 操作数2:None, 调试位置:None, 操作数3: None, });
                // 🔁 2026-09-24（soak M/K 修复）：调用返回后释放**调用方自持的复合实参**（副本 / 新建源临时）✓
                for 槽 in &调用后释放槽 { 发射释放槽(当前块, 局部表, *槽); }
                return 操作数::局部变量(ret);
            }
            let mut idx = 解析函数索引(函数名, 函数索引映射);
            // 🆕 2026-10-13（**F1 修复**，规范 §2.4.7「方法内区分规则」）：
            //   裸名调用（无 `.`）命中**规范全局函数**（§4.1 的预定义标识符：输出/输入/错误输出/类型/
            //   转整数/转小数/转文本…）时，**必须**解析到标准库索引。
            //   为什么必须在此纠正：结构体方法会被登记为函数 `结构体.方法名`，同时**裸名键**也进入
            //   `函数索引映射`；而 `解析函数索引` 为支持「外部块函数遮蔽同名内置」**先查用户映射** ⇒
            //   裸名 `转整数` 被"同名方法"劫持 ⇒ 方法内 `转整数(...)` 调到自己 ⇒ **无限递归栈溢出**
            //   （实测：`调用调试 名=转整数 索引=400 用户区=true`；`键调试` 同时存在 `丙物.转整数=400`
            //   与裸名 `转整数=400`）；跨结构体同名方法则**静默取错值**（实测 `P1=7`，应为 42）✗。
            //   规范口径：方法只能经 `自身.方法()` / `实例.方法()` 调用（§2.4.7），裸名一律是全局函数 ✓。
            if !函数名.contains('.')
                && crate::标准库元数据::全局函数名集合().contains(函数名.as_str())
            {
                if let Some(标准索引) = crate::标准库元数据::取标准库索引映射()
                    .get(函数名.as_str())
                    .copied()
                {
                    idx = 标准索引;
                }
            }

            // ★跨模块外部函数索引回退（2026-08-10 修复「跨模块调用 FFI 函数静默空转」）：
            //   外部函数登记进 函数索引映射 时用的是外部块内的名字（展开导入即裸名），
            //   **不带**声明所在模块的前缀。于是 `界面.呈现窗口(窗口)` 查不到索引，
            //   解析函数索引 返回 usize::MAX，VM 端「未定义函数静默返回空值」——
            //   调用看似成功、实际什么都没做（GTK 窗口因此永远不显示，且毫无报错）。
            //   这里在确认是外部函数后，剥掉模块前缀用裸名重查一次。
            if 是外部 && idx == usize::MAX {
                if let Some(裸名) = 函数名.rsplit('.').next() {
                    if 裸名 != 函数名.as_str() {
                        idx = 解析函数索引(裸名, 函数索引映射);
                    }
                }
            }
            // 🆕 函数索引未找到且名称是局部变量 → 转为间接调用（兜底）
            if idx == usize::MAX {
                if let Some(&var_idx) = 变量映射.get(函数名.as_str()) {
                    let ret = 局部表.len(); 局部表.push(底层表示类型::空值);
                    for param_op in &参数操作数列表 {
                        当前块.指令列表.push(三地址码 { 结果:操作数::无, 操作码:操作码::加载, 操作数1:param_op.clone(), 操作数2:None, 调试位置:None, 操作数3: None, });
                    }
                    当前块.指令列表.push(三地址码 { 结果:操作数::局部变量(ret), 操作码:操作码::间接调用, 操作数1:操作数::局部变量(var_idx), 操作数2:None, 调试位置:None, 操作数3: None, });
                    return 操作数::局部变量(ret);
                }
            }
            // ⚡双模式⚡ 无参常量（数学.圆周率 107 ~ 数学.是否无效小数 114）返回值为小数，
            // 返回临时必须标 小数64，否则编译模式下游运算（如 π/2）会把 f64 位模式
            // 当整数做整数除法，产生垃圾值（parity bug 根因）。其它系统函数沿用 空值
            // （由各操作码分支 记录结果类型 修正）。
            // 🆕 小数()（全局类型转换 116）运行时必返回 运行时值::小数(f64)：若返临时标 空值，
            // 编译模式会把 432.0 的 f64 位模式当 i64 整数加载做除法，致 小数(432)/小数(6)
            // 编译模式得 ~1.006 而非 72.0（parity bug，2026-08-13 53 号集成测试实锤）。
            // 整数()/文本() 等返回整数/句柄 默认为 空值 修正路径即正确，唯 小数64 缺失必崩。
            let 返回类型 = if (107..=114).contains(&idx) {
                底层表示类型::小数64
            } else if 函数名 == "小数" {
                底层表示类型::小数64
            } else {
                底层表示类型::空值
            };
            let ret = 局部表.len(); 局部表.push(返回类型);
            // 先将参数通过LOAD(结果:无)标记（此时不会触发其他指令的刷新）
            for param_op in &参数操作数列表 {
                当前块.指令列表.push(三地址码 { 结果:操作数::无, 操作码:操作码::加载, 操作数1:param_op.clone(), 操作数2:None, 调试位置:None, 操作数3: None, });
            }
            // 然后立即生成CALL（外部函数走 外部调用 opcode）；是外部 已在索引解析前判定。
            let 调用的操作码 = if 是外部 {
                操作码::外部调用
            } else {
                操作码::调用
            };
            当前块.指令列表.push(三地址码 { 结果:操作数::局部变量(ret), 操作码:调用的操作码, 操作数1:操作数::函数引用(idx), 操作数2:None, 调试位置:Some(位置.clone()), 操作数3: None, });
            // 🆕 2026-10-13（**#13 收窄版**）：仅当**调用返回文本**时登记结果槽（复合类型可能按身份借用 ⇒ 不可 −1）
            if matches!(类型, 类型信息::基本型(基本类型::文本)) {
                当前条件可释放临时.with(|s| s.borrow_mut().push(ret));
            }
            // 🔁 2026-09-24（soak M/K 修复）：**CALL 之后**释放调用方自持的复合实参（副本 / 新建源临时）✓
            //   ⚠ 位置必须在 CALL 之后：被调方以**借用**方式使用实参，调用期间不得回收 ✓
            // 🔁 2026-09-24（**被调方白名单门**）：仅当被调方"不保留实参"时才释放 ✓
            //   （未知内置可能把实参**移动**进自有结构体（无 `+1`）⇒ 释放即多释放 ✗ 见 `实参可释放` ✓）
            if 实参可释放(函数名, 函数签名详情) {
                for 槽 in &调用后释放槽 { 发射释放槽(当前块, 局部表, *槽); }
            }
            // by-ref 回拷：编译模式以堆单元句柄作引用，调用后须把修改结果写回原变量
            // （解释模式为别名，回拷为无害自写，双模式语义一致）。
            for (原始索引, ref_tmp) in &回拷列表 {
                let cb = 局部表.len(); 局部表.push(底层表示类型::整数64);
                当前块.指令列表.push(三地址码 { 结果:操作数::局部变量(cb), 操作码:操作码::间接加载, 操作数1:操作数::局部变量(*ref_tmp), 操作数2:None, 调试位置:None, 操作数3: None, });
                当前块.指令列表.push(三地址码 { 结果:操作数::无, 操作码:操作码::存储, 操作数1:操作数::局部变量(*原始索引), 操作数2:Some(操作数::局部变量(cb)), 调试位置:None, 操作数3: None, });
            }
            操作数::局部变量(ret)
        }
            高层表示表达式::方法调用 { 对象, 结构体名, 方法名, 实参列表, .. } => {
            // 精确小数 canonical 分派名（2026-08-30 方案A）：其结构体注册名为「精确小数」，
            // 但 base 注册/标准库门面对齐为「数学.精确小数」（与短小数/无符号整数对称），
            // 故合成分派名时用 数学.精确小数 前缀，消除 精确小数.加法 不对称分派名。
            // 🆕 2026-09-04 修复：方法分派名统一基于 裸结构体名 合成——对象类型键可能是 前缀(数学.短小数)
            // 或 裸(短小数) 双轨（M1 双键注册后 构造/无标注 → 前缀，裸标注 → 裸）。此前直接以 结构体名
            // 合成：前缀对象使 方法分派模块 查不到注册表条目回退自身 → 「数学.短小数.数学.短小数.加法」
            // 双重前缀 → 索引解析 MAX → 回退「短小数.加法」亦不在映射 → CALL 越界索引 → 返回空值
            // （probe_g/probe_f「空值不能参与类型转换」根因，P6 打点实证：前缀对象完整索引=MAX）。
            let 裸结构体名 = 结构体名.rsplit('.').next().unwrap_or(结构体名.as_str());
            let 模块前缀 = crate::标准库元数据::方法分派模块(&裸结构体名);
            let 完整函数名 = format!("{}.{}.{}", 模块前缀, 裸结构体名, 方法名);
            // 🆕 跨模块结构体方法：方法函数以「裸名.方法」注册于函数表；跨模块名（模块.结构体.方法）需回退裸名。
            let 裸完整函数名 = format!("{}.{}", 裸结构体名, 方法名);
            // 方法（名称唯一，不重载）：签名详情直接取自 函数签名详情（含 自身 形参）。
            // 内置方法(通道.发送等)不在表中→回退 (0, [])，由 VM 专用操作码处理。
            let (形参数量, 默认值列表) = match 函数签名详情.get(&完整函数名).or_else(|| 函数签名详情.get(&裸完整函数名)) {
                Some(&(n, ref d, _, _)) => (n, d.clone()),
                None => (0, vec![]),
            };
            let mut 完整实参: Vec<高层表示表达式> = 实参列表.clone();
            // 🆕 死循环防御：占位为 Some(None)（有占位无默认值）时既不 push 也不 break，
            //     旧逻辑会 while 死循环。改为显式 break（无默认值则停止填充，缺参由 VM 兜底）。
            while 完整实参.len() < 形参数量.saturating_sub(1) { // -1 for self
                let 缺失位置 = 完整实参.len();
                match 默认值列表.get(缺失位置 + 1) { // +1 skip self
                    Some(Some(默认表达式)) => 完整实参.push(默认表达式.clone()),
                    _ => break,
                }
            }
            let obj_op = 转换表达式(对象, 当前块, 块列表, 块编号, 后续块标识, 局部表, 变量映射, 常量池, 结构体布局, 函数索引映射, 结构体类型索引, 函数签名详情, 全局变量名列表, 匿名函数收集);

            // ── 任务专用操作码（方法调用路径，文档 5.7.2/5.7.3）──
            // 性能优化：避免 CALL 开销，直接映射为 VM 专用 opcode（Go 风格零开销抽象）
            if crate::标准库元数据::是零开销发射(&完整函数名) {
                let 码 = crate::标准库元数据::查操作码(&完整函数名, 0)
                    .expect("任务.等待结果 必须在标准库元数据表注册专用操作码");
                let ret = 局部表.len(); 局部表.push(底层表示类型::空值);
                当前块.指令列表.push(三地址码 { 结果:操作数::局部变量(ret), 操作码:码, 操作数1:obj_op, 操作数2:None, 调试位置:None, 操作数3: None, });
                return 操作数::局部变量(ret);
            }

            // 注：通道.发送/通道.接收 的 VM 专用 opcode 使用 4 操作数编码（三地址码不匹配），
            //     保持 CALL 路径（索引 67/68），功能等价且经过充分测试。

            let mut 参数操作数列表 = vec![obj_op];
            let mut 回拷列表: Vec<(usize, usize)> = Vec::new();  // (被引用原始索引, 取地址临时索引)
            // 🔁 2026-09-24（**soak N 形状修复**）：方法调用路径与普通调用**同一所有权缺口** ——
            //   调用点为值语义准备了**深拷贝副本**（形参 = 借用、从不登记）⇒ 副本须由调用方在调用后 −1；
            //   实参为**新建值 / 用户函数调用结果**（调用方自持）时，源临时亦须 −1 ✓（详见 调用 路径注释）
            let mut 调用后释放槽: Vec<usize> = Vec::new();
            // 方法调用：自身 占参数 0，故实参 i 对应形参 i+1
            let 被调签名 = 函数签名详情.get(&完整函数名).or_else(|| 函数签名详情.get(&裸完整函数名)).map(|(_, _, m, t)| (m.clone(), t.clone()));
            let 被调传递方式 = 被调签名.as_ref().map(|(m, _)| m.clone());
            let 被调形参类型_含自身 = 被调签名.map(|(_, t)| t);
            for (i, arg) in 完整实参.iter().enumerate() {
                let 是引用 = 被调传递方式.as_ref().and_then(|m| m.get(i + 1)) == Some(&参数传递方式::传引用);
                // 接口型形参按引用语义传递：接口方法需在原实例上原地修改，故实参仅传句柄，不深拷贝。
                let 形参是接口 = 被调形参类型_含自身.as_ref().and_then(|t| t.get(i + 1)).map(是接口引用类型).unwrap_or(false);
                if 是引用 {
                    if let 高层表示表达式::变量引用 { 名称, .. } = arg {
                        if let Some(&原始索引) = 变量映射.get(名称) {
                            let tmp = 局部表.len(); 局部表.push(底层表示类型::整数64);
                            当前块.指令列表.push(三地址码 { 结果:操作数::局部变量(tmp), 操作码:操作码::取地址, 操作数1:操作数::局部变量(原始索引), 操作数2:None, 调试位置:None, 操作数3: None, });
                            参数操作数列表.push(操作数::局部变量(tmp));
                            回拷列表.push((原始索引, tmp));
                            continue;
                        }
                    }
                }
                if let 高层表示表达式::变量引用 { 名称, .. } = arg {
                    if let Some(&原始索引) = 变量映射.get(名称) {
                        // 接口型参数按【值传递句柄】处理：接口变量存储的是指向实例的句柄（整数引用），
                        // 复制句柄即获得对同一实例的引用，零数据复制；经 thunk 调用方法时，
                        // 调用点已对 thunk 的 __object（传引用形参）取地址，故此处不应再取地址，
                        // 否则会双重取地址，导致方法修改作用于错误的目标（原实例不被修改）。
                        let tmp = 局部表.len(); 局部表.push(局部表.get(原始索引).cloned().unwrap_or(底层表示类型::整数64));
                        当前块.指令列表.push(三地址码 { 结果:操作数::局部变量(tmp), 操作码:操作码::加载, 操作数1:操作数::局部变量(原始索引), 操作数2:None, 调试位置:None, 操作数3: None });
                        let 需拷贝_变量实参 = !是引用 && !形参是接口 && 是复合类型(&从表达式推断(arg)) && !是新建值(arg);
                        let 拷后 = 发射深拷贝_类型感知(当前块, 块列表, 块编号, 局部表, 操作数::局部变量(tmp), &从表达式推断(arg), 需拷贝_变量实参, 结构体类型索引);
                        if 需拷贝_变量实参 {
                            if let 操作数::局部变量(槽) = 拷后 { 调用后释放槽.push(槽); }
                        }
                        参数操作数列表.push(拷后);
                        continue;
                    }
                }
                let op = 转换表达式(arg, 当前块, 块列表, 块编号, 后续块标识, 局部表, 变量映射, 常量池, 结构体布局, 函数索引映射, 结构体类型索引, 函数签名详情, 全局变量名列表, 匿名函数收集);
                // 接口型参数（thunk __object）按引用语义传递：临时存值后取地址，传引用而非深拷贝，
                // 使接口方法原地修改作用于原实例（数组/映射元素加载、链式调用等非变量引用场景）。
                if 形参是接口 {
                    let tmp = 局部表.len(); 局部表.push(底层表示类型::整数64);
                    当前块.指令列表.push(三地址码 { 结果:操作数::局部变量(tmp), 操作码:操作码::加载, 操作数1:op.clone(), 操作数2:None, 调试位置:None, 操作数3: None });
                    let addr = 局部表.len(); 局部表.push(底层表示类型::整数64);
                    当前块.指令列表.push(三地址码 { 结果:操作数::局部变量(addr), 操作码:操作码::取地址, 操作数1:操作数::局部变量(tmp), 操作数2:None, 调试位置:None, 操作数3: None });
                    参数操作数列表.push(操作数::局部变量(addr));
                } else {
                    let 推断实参类型 = 从表达式推断(arg);
                    let 需拷贝_其它实参 = !是引用 && !形参是接口 && 是复合类型(&推断实参类型) && !是新建值(arg);
                    let 拷后 = 发射深拷贝_类型感知(当前块, 块列表, 块编号, 局部表, op.clone(), &推断实参类型, 需拷贝_其它实参, 结构体类型索引);
                    if 需拷贝_其它实参 {
                        if let 操作数::局部变量(槽) = 拷后 { 调用后释放槽.push(槽); }
                        // 自有右值（字面量 / 用户函数调用结果）深拷贝后，源临时亦须 −1 ✓
                        if 是复合字面量(arg) || 是用户函数调用(arg, 函数签名详情) {
                            if let 操作数::局部变量(槽) = op { 调用后释放槽.push(槽); }
                        }
                    } else if !是引用 && !形参是接口 && 是复合类型(&推断实参类型) && 是新建值(arg) {
                        if let 操作数::局部变量(槽) = op { 调用后释放槽.push(槽); }
                    } else if !是引用
                        && (是新建文本表达式(arg) || 是并发新建返回值(arg))
                        && 是深转不保留名(&完整函数名)
                    {
                        // 🔁 2026-09-25（**白名单分支不得受「形参是接口」门控**）★★ —— 修 100% 泄漏：
                        //   原条件含 `!形参是接口`，而 **`通道.发送` 的载荷形参类型是动态（接口/任意）**
                        //   ⇒ `形参是接口 = true` ⇒ **本分支从不发射** ⇒ 发送侧文本**逐个泄漏** ✗✗
                        //   实测（`F12_发送侧文本释放探针`，解释模式）：N=500/2000/8000 ⇒ 存活
                        //     **503/2003/8003**、文本 **502/2002/8002** ⇒ **+1/轮（100% 泄漏）** ✗
                        //   **为什么必须去掉该门控**：本分支的依据是「**被调方同步深转、不保留调用方引用**」
                        //     （`是深转不保留名` 已核实：`通道.发送` = `运行时值转拥有值` 深转自包含值 + 同步 send ✓）
                        //     —— 它与"形参静态上是否接口型"**毫无关系** ✓（接口型形参照样可以深转不保留）✓
                        //   ⚠ 安全性仍由**白名单**保证（当前仅 `通道.发送/尝试发送`；泛化实测会致网络用例悬垂 ✗）✓
                        // 🔁 2026-09-24（**item 7 发送实参侧 · 白名单化**）：与 `普通调用` 路径同法 ——
                        //   `通道甲.发送(转文本(..))`（**方法调用** 形态）的文本实参为**自有右值**，
                        //   而 base `并发发送` **同步深转、不保留** ⇒ 调用后 −1 ✓
                        //   （实测修后 `115` 文本 **104 → 1**、总存活 **226 → 19** ✓✓）
                        //   ⚠ 白名单理由与红线见 `是实参深转不保留内置` 注释（泛化会致网络用例悬垂 ✗）✓
                        if let 操作数::局部变量(槽) = op { 调用后释放槽.push(槽); }
                    }
                    参数操作数列表.push(拷后);
                }
            }
            for param_op in &参数操作数列表 {
                当前块.指令列表.push(三地址码 { 结果:操作数::无, 操作码:操作码::加载, 操作数1:param_op.clone(), 操作数2:None, 调试位置:None, 操作数3: None, });
            }
            let 完整索引 = 解析函数索引(&完整函数名, 函数索引映射);
            let idx = if 完整索引 == usize::MAX {
                解析函数索引(&裸完整函数名, 函数索引映射)
            } else { 完整索引 };
            if idx == usize::MAX {
                // 🆕 函数索引未找到：检查是否为局部变量（函数类型变量 → 间接调用）
                if let Some(&var_idx) = 变量映射.get(&完整函数名) {
                    // 改为间接调用：加载变量值作为闭包目标，参数在前
                    let ret = 局部表.len(); 局部表.push(底层表示类型::空值);
                    for param_op in &参数操作数列表 {
                        当前块.指令列表.push(三地址码 { 结果:操作数::无, 操作码:操作码::加载, 操作数1:param_op.clone(), 操作数2:None, 调试位置:None, 操作数3: None });
                    }
                    当前块.指令列表.push(三地址码 { 结果:操作数::局部变量(ret), 操作码:操作码::间接调用, 操作数1:操作数::局部变量(var_idx), 操作数2:None, 调试位置:None, 操作数3: None, });
                    // 🔁 2026-09-24（soak N 修复）：调用返回后释放调用方自持的复合实参 ✓
                    for 槽 in &调用后释放槽 { 发射释放槽(当前块, 局部表, *槽); }
                    return 操作数::局部变量(ret);
                }
            }
            let ret = 局部表.len(); 局部表.push(底层表示类型::空值);
            当前块.指令列表.push(三地址码 { 结果:操作数::局部变量(ret), 操作码:操作码::调用, 操作数1:操作数::函数引用(idx), 操作数2:None, 调试位置:None, 操作数3: None, });
            // 🔁 2026-09-24（soak N 修复）：**CALL 之后**释放调用方自持的复合实参（副本 / 新建源临时）✓
            // ⚠ **本路径不加"被调方白名单门"**（2026-09-24 实测）：方法调用路径的接收者方法多为
            //   **用户结构体方法**，其"完整函数名"与 `函数签名详情` 的键**不一致** ⇒ 加门会**误滤**
            //   ⇒ 实测 `N_用户方法实参` 由平坦回归为 **2/轮** ✗（故此处保持原样 ✓）。
            //   而**拦截器形态属"普通调用"**（`网络.获取(url, {选项})` ✓）⇒ 门加在 `调用` 路径即已覆盖 ✓✓
            for 槽 in &调用后释放槽 { 发射释放槽(当前块, 局部表, *槽); }
            // by-ref 回拷：编译模式以堆单元句柄作引用，调用后须把修改结果写回原变量
            for (原始索引, ref_tmp) in &回拷列表 {
                let cb = 局部表.len(); 局部表.push(底层表示类型::整数64);
                当前块.指令列表.push(三地址码 { 结果:操作数::局部变量(cb), 操作码:操作码::间接加载, 操作数1:操作数::局部变量(*ref_tmp), 操作数2:None, 调试位置:None, 操作数3: None, });
                当前块.指令列表.push(三地址码 { 结果:操作数::无, 操作码:操作码::存储, 操作数1:操作数::局部变量(*原始索引), 操作数2:Some(操作数::局部变量(cb)), 调试位置:None, 操作数3: None, });
            }
            // ⚡双模式⚡ A3: 接收者字段访问（如 `自身.数据.插入(x)`）的变异结果必须写回该字段。
            // 映射存储/数组追加 等 COW 双寄存器操作把新句柄写入 ret 寄存器，而原字段（自身.数据）仍指向旧副本；
            // 若不写回，后续 `自身.数据.获取/长度` 读到的是未修改的旧映射（长度=0）。
            // 单源判定覆盖任意接收者类型（含接口数组/映射元素）；写回归一委托单源函数（递归解嵌套）。
            if 是字段变异写回(&完整函数名, &操作码::调用) {
                let 应写回 = matches!(对象.as_ref(), 高层表示表达式::字段访问 { .. })
                    || matches!(对象.as_ref(), 高层表示表达式::调用 { 函数名, .. } if crate::标准库元数据::是容器加载调用(函数名));
                if 应写回 {
                    发射字段接收者写回(对象, 操作数::局部变量(ret), 当前块, 块列表, 块编号, 后续块标识, 局部表, 变量映射, 常量池, 结构体布局, 函数索引映射, 结构体类型索引, 函数签名详情, 全局变量名列表, 匿名函数收集);
                }
            }
            操作数::局部变量(ret)
        }
        高层表示表达式::间接调用 { 目标, 实参列表, 类型, .. } => {
            // ⚡双模式⚡ 闭包/函数指针 间接调用：发射 间接调用(闭包源, args...) opcode
            let 闭包操作数 = 转换表达式(目标, 当前块, 块列表, 块编号, 后续块标识, 局部表, 变量映射, 常量池, 结构体布局, 函数索引映射, 结构体类型索引, 函数签名详情, 全局变量名列表, 匿名函数收集);
            // ★★ 2026-09-20 缺口修复（真实现缺陷；致「函数类型作形参 + 间接调用」双模不可用）★★
            //   **必须与普通/系统函数调用同款「两阶段」模式**（见本文件 1548-1578 的 参数操作数 循环）：
            //     阶段①：把**全部实参**逐个求值为 操作数（此阶段可能发射任意指令，如 变量引用 会插入
            //             一条**带结果**的 `加载(tmp←槽)` 以承载槽类型）；
            //     阶段②：**连续**发射 `加载(结果=无, 操作数1=实参操作数)`，把参数压入字节码生成器的
            //             **实参缓冲**，随后由 `间接调用` 一次性内嵌编码。
            //   旧实现把两阶段**交错**（求值一条 → 缓冲一条）⇒ 下一条实参求值期间发射的带结果指令
            //     会触发 `字节码生成.rs::刷新参数缓冲()`——而该函数是 **`参数缓冲.clear()`（直接丢弃！）**
            //     ⇒ 已缓冲的实参被静默丢弃 ⇒ 间接调用只收到「最后一条实参」。
            //   实证（VM 打点，`探针C_参数位置.智`）：`回调(甲, 乙)` 得到
            //     `目标标签=6(函数指针) 参数个数=1`（应为 2）⇒ 调用后返回空值 ⇒
            //     双模一致地表现为「函数类型形参不可用」。普通调用因采用两阶段而从未暴露此问题。
            let mut 实参操作数: Vec<操作数> = Vec::with_capacity(实参列表.len());
            for arg in 实参列表 {
                let val = 转换表达式(arg, 当前块, 块列表, 块编号, 后续块标识, 局部表, 变量映射, 常量池, 结构体布局, 函数索引映射, 结构体类型索引, 函数签名详情, 全局变量名列表, 匿名函数收集);
                实参操作数.push(val);
            }
            for val in &实参操作数 {
                当前块.指令列表.push(三地址码 { 结果:操作数::无, 操作码:操作码::加载, 操作数1:val.clone(), 操作数2:None, 调试位置:None, 操作数3: None, });
            }
            let ret = 局部表.len(); 局部表.push(转换类型(类型));
            当前块.指令列表.push(三地址码 { 结果:操作数::局部变量(ret), 操作码:操作码::间接调用, 操作数1:闭包操作数, 操作数2:None, 调试位置:None, 操作数3: None, });
            操作数::局部变量(ret)
        }
        高层表示表达式::字段访问 { 对象, 字段索引, 类型, 位置, .. } => {
            let obj = 转换表达式(对象, 当前块, 块列表, 块编号, 后续块标识, 局部表, 变量映射, 常量池, 结构体布局, 函数索引映射, 结构体类型索引, 函数签名详情, 全局变量名列表, 匿名函数收集);
            // parity bug 根因：字段访问结果临时变量类型须与字段真实类型一致（小数字段→小数64），否则后续按类型分派的运算（如 乘法/除法）据 局部变量表 误判为「是整数」而错误计算（同 变量引用 修复 430-432 对称）。
            let tmp = 局部表.len(); 局部表.push(转换类型(&类型));
            当前块.指令列表.push(三地址码 { 结果:操作数::局部变量(tmp), 操作码:操作码::字段加载, 操作数1:obj, 操作数2:Some(操作数::立即整数(*字段索引 as i64 + 1)), 调试位置:Some(位置.clone()), 操作数3: None, });
            操作数::局部变量(tmp)
        }
        高层表示表达式::创建结构体 { 结构体名, 实参列表, 字段数量, .. } => {
            // ── 内置并发类型（通道/终止器）的构造函数走 syscall 而非 struct 创建 ──
            if let Some(构造名) = crate::标准库元数据::取构造内部名(&结构体名) {
                let 函数名查 = 构造名.to_string();
                let idx = 解析函数索引(&函数名查, 函数索引映射);
                let mut 参数操作数列表 = Vec::new();
                for arg in 实参列表.iter() {
                    let op = 转换表达式(arg, 当前块, 块列表, 块编号, 后续块标识, 局部表, 变量映射, 常量池, 结构体布局, 函数索引映射, 结构体类型索引, 函数签名详情, 全局变量名列表, 匿名函数收集);
                    参数操作数列表.push(op);
                }
                for param_op in &参数操作数列表 {
                    当前块.指令列表.push(三地址码 { 结果:操作数::无, 操作码:操作码::加载, 操作数1:param_op.clone(), 操作数2:None, 调试位置:None, 操作数3: None, });
                }
                let ret = 局部表.len(); 局部表.push(底层表示类型::空值);
                当前块.指令列表.push(三地址码 { 结果:操作数::局部变量(ret), 操作码:操作码::调用, 操作数1:操作数::函数引用(idx), 操作数2:None, 调试位置:None, 操作数3: None, });
                return 操作数::局部变量(ret);
            }
            let obj = 局部表.len(); 局部表.push(底层表示类型::指针);
            // 🆕 跨模块结构体构造：结构体名可能是「模块名.结构体名」，而运行时结构体注册表以「裸名」登记。
            // 查类型索引时回退到裸名（最后一段），确保跨模块构造与裸构造得到一致的类型索引。
            let 裸结构体名 = 结构体名.rsplit('.').next().unwrap_or(结构体名.as_str());
            let 类型索引 = 结构体类型索引.get(结构体名).or_else(|| 结构体类型索引.get(裸结构体名)).copied().unwrap_or(0) as i64;
            当前块.指令列表.push(三地址码 { 结果:操作数::局部变量(obj), 操作码:操作码::创建结构体, 操作数1:操作数::立即整数(类型索引), 操作数2:None, 调试位置:None, 操作数3: None, });
            let 字段数 = *字段数量;
            let 参数数 = 实参列表.len().saturating_sub(字段数);
            // 🆕 填充方案 [字段在前+参数在后]：
            //   Step ①: 填充参数值 → 槽位 字段数..字段数+参数数，保存操作数用于 init 调用
            let mut 参数操作数 = Vec::new();
            for (i, arg) in 实参列表.iter().enumerate().take(参数数) {
                let arg_op = 转换表达式(arg, 当前块, 块列表, 块编号, 后续块标识, 局部表, 变量映射, 常量池, 结构体布局, 函数索引映射, 结构体类型索引, 函数签名详情, 全局变量名列表, 匿名函数收集);
                let 槽索引 = 字段数 + i;
                当前块.指令列表.push(三地址码 { 结果:操作数::局部变量(obj), 操作码:操作码::字段存储, 操作数1:操作数::局部变量(obj), 操作数2:Some(操作数::立即整数(槽索引 as i64 + 1)), 调试位置:None, 操作数3: Some(arg_op.clone()) });
                参数操作数.push(arg_op);
            }
            //   Step ②: 注册 自身 到变量映射（字段默认值中的 字段访问{自身,...} 可解析）
            //   🆕 🐛 保存旧的自身（嵌套结构体创建时可能已有外层自身），Step ③ 后复原
            let 旧的自身 = 变量映射.get("自身").copied();
            变量映射.insert("自身".to_string(), obj);
            //   Step ③: 填充字段默认值 → 槽位 0..字段数
            for (i, arg) in 实参列表.iter().enumerate().skip(参数数) {
                let arg_op = 转换表达式(arg, 当前块, 块列表, 块编号, 后续块标识, 局部表, 变量映射, 常量池, 结构体布局, 函数索引映射, 结构体类型索引, 函数签名详情, 全局变量名列表, 匿名函数收集);
                let 槽索引 = i - 参数数;
                当前块.指令列表.push(三地址码 { 结果:操作数::局部变量(obj), 操作码:操作码::字段存储, 操作数1:操作数::局部变量(obj), 操作数2:Some(操作数::立即整数(槽索引 as i64 + 1)), 调试位置:None, 操作数3: Some(arg_op.clone()) });
                // 🔁 2026-09-22 **字段默认值 RC 平衡**（证据定位，非类比）：
                //   base `堆_字段存储` 对**写入值** +1（字段获得一份引用），而本语句另持有该值的**临时**
                //   （默认值字面量/新建结构体 ⇒ 新建临时、无别名）⇒ 此处须 −1 归位；
                //   否则**每个含复合类型默认字段的构造**泄漏 1 个容器 ✗
                //   （实测 `G_复合默认字段泄漏_取证`：500 轮 ⇒ 不可达 501；`114内存基线千轮` ⇒ 存活 1019）。
                //   ⚠ 仅在源为**新建值**时释放：若默认值表达式是变量/字段（极罕见）⇒ 该操作数是别人持有的引用，
                //     释放它会把字段那份引用也扣掉 ⇒ 误回收 ✗。
                if 是新建值(arg) { 释放字面量源(当前块, 局部表, &arg_op, true); }
            }
            // 🆕 复原外层自身（防止嵌套结构体创建时变量映射被覆盖丢失）
            if let Some(旧索引) = 旧的自身 {
                变量映射.insert("自身".to_string(), 旧索引);
            } else {
                变量映射.remove("自身");
            }
            //   Step ④: 调用初始化（传递自身 + 结构体构造参数值）
            // 🆕 别名/跨模块结构体（辅助模块.圆）初始化函数以 原名/裸名 注册（辅助模块.圆.初始化 / 圆.初始化），
            //     先查原名，再回退裸名（与 方法调用 裸名回退一致）。归一后 结构体名 恒为原名（辅助模块.圆），
            //     原名键注册为「模块名.结构体名.初始化」时命中原名；注册为「结构体名.初始化」时命中裸名。
            let 初始化函数名 = format!("{}.初始化", 结构体名);
            let 裸初始化函数名 = format!("{}.初始化", 结构体名.rsplit('.').next().unwrap_or(结构体名));
            let 初始化索引 = 函数索引映射.get(&初始化函数名).or_else(|| 函数索引映射.get(&裸初始化函数名)).copied();
            if let Some(初始化索引) = 初始化索引 {
                当前块.指令列表.push(三地址码 { 结果:操作数::无, 操作码:操作码::加载, 操作数1:操作数::局部变量(obj), 操作数2:None, 调试位置:None, 操作数3: None, });
                for op in &参数操作数 {
                    当前块.指令列表.push(三地址码 { 结果:操作数::无, 操作码:操作码::加载, 操作数1:op.clone(), 操作数2:None, 调试位置:None, 操作数3: None, });
                }
                // 调用初始化：**仅完成字段初始化**，不消费返回值。
                // 【A2 已彻底移除（2026-09-21 · COW 退役）】此前此处把初始化返回值（隐式 `返回 自身`）
                //   加载回 obj —— 那是 COW 机制下持久化"分离出的新句柄"所必需。COW 退役后写入一律
                //   原地进行、句柄恒不变 ⇒ 该加载成为**恒等冗余**，已删除。
                // 语言定义：**初始化 = 普通方法、无返回值**（规范 §2.4）；**实例由本创建表达式产出**
                //   （`obj` = `创建结构体` 已产出的句柄），初始化只负责写字段。
                // 保留结果槽：函数调用约定要求一个结果寄存器（被调用方返回 空值，内容不被消费）。
                let _调用结果 = 局部表.len(); 局部表.push(底层表示类型::空值);
                当前块.指令列表.push(三地址码 { 结果:操作数::局部变量(_调用结果), 操作码:操作码::调用, 操作数1:操作数::函数引用(初始化索引), 操作数2:None, 调试位置:None, 操作数3: None, });
            }
            操作数::局部变量(obj)
        }
        高层表示表达式::枚举成员访问 { 枚举名, 成员名: _, 成员索引, 数据, .. } => {
            // 🆕 2026-10-12：标签含**类型身份**（见 `枚举成员标签`），与判等侧同源
            let 枚举成员编号 = 枚举成员标签(枚举名, *成员索引);
            // ⚡双模式⚡ 数据枚举：创建堆数组 [标签, 数据1, 数据2, ...] 作为运行时载体
            let arr = 局部表.len(); 局部表.push(底层表示类型::指针);
            当前块.指令列表.push(三地址码 { 结果:操作数::局部变量(arr), 操作码:操作码::调用, 操作数1:操作数::函数引用(base::标准库索引::创建数组), 操作数2:None, 调试位置:None, 操作数3: None, });
            // 追加标签（成员编号，整数）
            let 标签临时 = 局部表.len(); 局部表.push(底层表示类型::整数64);
            当前块.指令列表.push(三地址码 { 结果:操作数::局部变量(标签临时), 操作码:操作码::加载, 操作数1:操作数::立即整数(枚举成员编号), 操作数2:None, 调试位置:None, 操作数3: None, });
            let 追加后 = 局部表.len(); 局部表.push(底层表示类型::指针);
            当前块.指令列表.push(三地址码 { 结果:操作数::局部变量(追加后), 操作码:操作码::数组追加, 操作数1:操作数::局部变量(arr), 操作数2:Some(操作数::局部变量(标签临时)), 调试位置:None, 操作数3: None, });
            当前块.指令列表.push(三地址码 { 结果:操作数::无, 操作码:操作码::存储, 操作数1:操作数::局部变量(arr), 操作数2:Some(操作数::局部变量(追加后)), 调试位置:None, 操作数3: None, });
            // 追加各数据字段
            for 数据表达式 in 数据 {
                let val = 转换表达式(数据表达式, 当前块, 块列表, 块编号, 后续块标识, 局部表, 变量映射, 常量池, 结构体布局, 函数索引映射, 结构体类型索引, 函数签名详情, 全局变量名列表, 匿名函数收集);
                let 追加后2 = 局部表.len(); 局部表.push(底层表示类型::指针);
                当前块.指令列表.push(三地址码 { 结果:操作数::局部变量(追加后2), 操作码:操作码::数组追加, 操作数1:操作数::局部变量(arr), 操作数2:Some(val), 调试位置:None, 操作数3: None, });
                当前块.指令列表.push(三地址码 { 结果:操作数::无, 操作码:操作码::存储, 操作数1:操作数::局部变量(arr), 操作数2:Some(操作数::局部变量(追加后2)), 调试位置:None, 操作数3: None, });
            }
            操作数::局部变量(arr)
        }
        高层表示表达式::成员访问 { 对象, 成员名, .. } => {
            eprintln!("[降级警告] 未预期的成员访问: 对象={:?}, 成员={}", 对象, 成员名);
            let tmp = 局部表.len();
            局部表.push(底层表示类型::空值);
            当前块.指令列表.push(三地址码 { 结果:操作数::局部变量(tmp), 操作码:操作码::加载, 操作数1:操作数::立即整数(0), 操作数2:None, 调试位置:None, 操作数3: None, });
            操作数::局部变量(tmp)
        }
        高层表示表达式::隐式转换 { 源表达式, 目标类型 } => {
            let 源操作数 = 转换表达式(源表达式, 当前块, 块列表, 块编号, 后续块标识, 局部表, 变量映射, 常量池, 结构体布局, 函数索引映射, 结构体类型索引, 函数签名详情, 全局变量名列表, 匿名函数收集);
            let 转换操作码 = match &目标类型 {
                类型信息::基本型(基本类型::小数) => Some(操作码::整数转小数),
                类型信息::基本型(基本类型::整数) => Some(操作码::小数转整数),
                类型信息::基本型(基本类型::文本) => Some(操作码::任意转文本),
                _ => None,
            };
            if let Some(op) = 转换操作码 {
                let tmp = 局部表.len();
                let 目标底层类型 = match &目标类型 {
                    类型信息::基本型(基本类型::小数) => 底层表示类型::小数64,
                    类型信息::基本型(基本类型::整数) => 底层表示类型::整数64,
                    类型信息::基本型(基本类型::文本) => 底层表示类型::文本,
                    _ => 底层表示类型::空值,
                };
                局部表.push(目标底层类型);
                当前块.指令列表.push(三地址码 { 结果:操作数::局部变量(tmp), 操作码:op, 操作数1:源操作数, 操作数2:None, 调试位置:None, 操作数3: None, });
                操作数::局部变量(tmp)
            } else {
                源操作数
            }
        }
        高层表示表达式::匿名函数(_函数定义) => {
            // 闭包：仅捕获闭包体内实际引用的自由变量（⚡双模式⚡ 修复：原“作用域内全部局部变量”导致捕获数/签名/dispatch 三者不一致）
            let 参数名: Vec<String> = _函数定义.形参列表.iter().map(|(n, _)| n.clone()).collect();
            let 自由变量名: HashSet<String> = 收集闭包自由变量(&_函数定义.函数体, &参数名, &HashSet::new());
            let mut 候选捕获: Vec<(String, usize)> = 自由变量名.iter()
                .filter(|名| !全局变量名列表.iter().any(|g| g.as_str() == 名.as_str()))
                .filter_map(|名| 变量映射.get(名.as_str()).copied().map(|idx| (名.clone(), idx)))
                .collect();
            候选捕获.sort_by_key(|(_, idx)| *idx);
            let 捕获列表: Vec<(String, 底层表示类型)> = 候选捕获.iter()
                .map(|(名, idx)| (名.clone(), 局部表[*idx].clone()))
                .collect();

            // ⚡双模式⚡ A1 闭包固定索引 = 200 + K + 闭包序（K=用户函数数，闭包序=已收集闭包数）。
            // 与编译器 函数名映射(200+i, i=函数列表位置) 同源：函数列表 = 用户函数(K) + 闭包(C，按 idx 升序)，
            // 闭包 c 在列表位置 K+c → 编译器索引 200+K+c，与降级层注册索引严格一致（不受外部函数数 E 干扰）。
            let 闭包序 = 匿名函数收集.len();
            let 匿名函数索引 = crate::底层表示::模块结构::用户函数索引基址 + crate::降级::语句转换::模块用户函数数.with(|c| c.load(std::sync::atomic::Ordering::SeqCst)) + 闭包序;
            let 闭包函数名 = format!("*闭包_{}", 匿名函数索引);
            函数索引映射.insert(闭包函数名.clone(), 匿名函数索引);

            // ★ 2026-10-22（**F47 修复**：`λ 内定义 λ` ⇒ 索引冲突，外层 λ 实际执行的是内层函数体）
            //   原实现「**先递归转换、后 push**」：内层 λ 递归时 `匿名函数收集.len()` 与外层**相同**
            //   （外层还没 push）⇒ 两层拿到同一个 `闭包序` / 同一个函数索引 ⇒ 内层的 push 覆盖外层，
            //   运行时"外层 λ 的引用"指向**内层函数体**。
            //   **实测现象**（双模一致 ✗）：λ 内**哪怕只定义、不调用**内层 λ，外层也直接返回内层 λ 的
            //   返回值、且后续语句被整体跳过（探针：外层 `返回 3` ⇒ 实际得 99；`C 调用后` 那行不打印）。
            //   修法：**先占位再递归**，使「索引 == 收集列表位置」，且外层永远排在它的内层之前。
            let 占位函数 = 底层表示函数 {
                名称: 闭包函数名,
                形参列表: vec![],
                形参局部索引: vec![],
                返回类型: 底层表示类型::空值,
                基本块列表: vec![基本块 {
                    标识符: 0,
                    指令列表: vec![],
                    终止指令: 终止指令::返回(None),
                    异常目标: 异常目标::无,
                }],
                局部变量表: vec![底层表示类型::整数64],
                拥有型槽索引: vec![],
            };
            匿名函数收集.push((匿名函数索引, 占位函数));

            // 递归转换闭包函数体（捕获变量前置到局部表）
            let 闭包底层函数 = 转换函数(
                _函数定义, 常量池, 结构体布局, 函数索引映射, 结构体类型索引,
                全局变量名列表, 函数签名详情, 匿名函数收集, Some(&捕获列表),
            );
            匿名函数收集[闭包序] = (匿名函数索引, 闭包底层函数);

            // 创建闭包：按捕获顺序缓冲捕获变量值，再发射创建闭包
            let closure_tmp = 局部表.len(); 局部表.push(底层表示类型::指针);
            for (名, _外层索引) in &候选捕获 {
                let outer_idx = 变量映射.get(名.as_str()).copied().unwrap();
                当前块.指令列表.push(三地址码 { 结果:操作数::无, 操作码:操作码::加载, 操作数1:操作数::局部变量(outer_idx), 操作数2:None, 调试位置:None, 操作数3: None, });
            }
            当前块.指令列表.push(三地址码 { 结果:操作数::局部变量(closure_tmp), 操作码:操作码::创建闭包, 操作数1:操作数::函数引用(匿名函数索引), 操作数2:Some(操作数::立即整数(候选捕获.len() as i64)), 调试位置:None, 操作数3: None, });
            操作数::局部变量(closure_tmp)
        }
    }
}
